def now_ms() -> int:
    return int(time.time() * 1000)


def guide_famous_generals_payload() -> dict[str, Any]:
    return shared_guide_reference_payload({
        "resource": "famous-generals",
        "sourceText": GUIDE_FAMOUS_GENERALS_FILE.read_text(encoding="utf-8-sig"),
    })


def guide_articles_payload() -> dict[str, Any]:
    return shared_guide_reference_payload({"resource": "articles"})


def guide_article_payload(article_id: str) -> dict[str, Any]:
    normalized = str(article_id or "").strip()
    valid = any(item_id == normalized for item_id, _title in GUIDE_ARTICLE_SPECS)
    request = {"resource": "article", "id": normalized}
    if valid:
        request["sourceText"] = (
            GUIDE_ARTICLE_DIR / f"{normalized}.txt"
        ).read_text(encoding="utf-8-sig")
    return shared_guide_reference_payload(request)


def guide_open_server_calculation_payload(version_index: int, server: int) -> dict[str, Any]:
    return shared_guide_reference_payload({
        "resource": "open-server-calculation",
        "versionIndex": version_index,
        "server": server,
    })


def guide_open_server_options_payload(today: date | None = None) -> dict[str, Any]:
    request: dict[str, Any] = {"resource": "open-server-options"}
    if today is not None:
        request["today"] = today.isoformat()
    return shared_guide_reference_payload(request)


def guide_reference_request_body(query: dict[str, list[str]]) -> dict[str, Any]:
    resource = str((query.get("resource") or [""])[0] or "")
    body: dict[str, Any] = {"resource": resource}
    if resource == "famous-generals":
        body["sourceText"] = GUIDE_FAMOUS_GENERALS_FILE.read_text(encoding="utf-8-sig")
    elif resource == "article":
        article_id = str((query.get("id") or [""])[0] or "").strip()
        body["id"] = article_id
        if any(item_id == article_id for item_id, _title in GUIDE_ARTICLE_SPECS):
            body["sourceText"] = (
                GUIDE_ARTICLE_DIR / f"{article_id}.txt"
            ).read_text(encoding="utf-8-sig")
    elif resource == "open-server-calculation":
        body["versionIndex"] = (query.get("versionIndex") or ["0"])[0]
        body["server"] = (query.get("server") or ["0"])[0]
    return body


def guide_reference_payload(query: dict[str, list[str]]) -> dict[str, Any]:
    return shared_guide_reference_payload(guide_reference_request_body(query))


def json_safe(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(k): json_safe(v) for k, v in value.items() if k not in {"thread", "stopEvent"}}
    if isinstance(value, list):
        return [json_safe(v) for v in value]
    if isinstance(value, tuple):
        return [json_safe(v) for v in value]
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    return str(value)


def local_time_text(ts_ms: int | None = None) -> str:
    ts = (ts_ms if ts_ms is not None else now_ms()) / 1000
    return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(ts))


def storage_slug(value: Any, fallback: str = "unknown") -> str:
    text = str(value or "").strip()
    if not text:
        text = fallback
    text = re.sub(r"\s+", "_", text)
    text = re.sub(r"[^0-9A-Za-z_\-\u4e00-\u9fff]+", "_", text)
    text = re.sub(r"_+", "_", text).strip("_")
    return text[:80] or fallback


def normalize_platform_key(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return DEFAULT_PLATFORM_KEY
    lowered = text.lower()
    for key, profile in PLATFORM_PROFILES.items():
        aliases = profile.get("aliases") or ()
        if lowered == key.lower() or any(
            lowered == str(alias or "").strip().lower()
            for alias in aliases
        ):
            return key
    raise RuntimeError(
        f"不支持的游戏平台：{text}；目前仅支持热血三国联盟、当乐帝王三国"
    )


def platform_profile(value: Any = None) -> dict[str, Any]:
    return PLATFORM_PROFILES[normalize_platform_key(value)]


def platform_display_name(value: Any = None) -> str:
    return str(platform_profile(value).get("name") or "")


def default_server_query(value: Any = None) -> str:
    return str(
        platform_profile(value).get("defaultServerQuery")
        or PLATFORM_PROFILES[DEFAULT_PLATFORM_KEY]["defaultServerQuery"]
    )


def record_platform_key(record: dict[str, Any] | None) -> str:
    return normalize_platform_key((record or {}).get("platform"))


def normalized_area_key(*values: Any) -> str:
    first = ""
    for raw in values:
        text = str(raw or "").strip()
        if not text:
            continue
        if not first:
            first = text
        m = re.search(r"qzone[_-]?(\d+)", text, re.I) or re.search(r"(\d+)\s*区", text)
        if m:
            return f"区{m.group(1)}"
    return storage_slug(first or "未知区服")


def account_storage_key(sess: dict[str, Any] | None = None, acc: dict[str, Any] | None = None, session_id: str | None = None) -> str:
    sid = str(session_id or (sess or {}).get("sessionId") or (acc or {}).get("sessionId") or "")
    if not sess and sid:
        sess = SESSIONS.get(sid)
    if not acc and sid:
        acc = ACCOUNTS.get(sid)
    username = (sess or {}).get("username") or (acc or {}).get("username") or "unknown"
    area = (sess or {}).get("area") or (acc or {}).get("area") or {}
    area_key = normalized_area_key(
        area.get("serverKey"),
        area.get("areaName"),
        (acc or {}).get("serverQuery"),
        (acc or {}).get("areaName"),
    )
    platform_key = record_platform_key(sess or acc)
    # Preserve existing 三国联盟 habit/log keys while isolating every other
    # platform from accounts that happen to use the same username and zone.
    prefix = "" if platform_key == DEFAULT_PLATFORM_KEY else f"{platform_key}_"
    return storage_slug(
        f"{prefix}{username}_{area_key}",
        fallback=(f"session_{sid[:8]}" if sid else "unknown_account"),
    )


def account_config_dir(sess: dict[str, Any] | None = None, acc: dict[str, Any] | None = None, session_id: str | None = None) -> Path:
    key = account_storage_key(sess=sess, acc=acc, session_id=session_id)
    return ACCOUNT_CONFIG_DIR / key


def shared_map_server_key(sess: dict[str, Any] | None) -> str:
    area = (sess or {}).get("area")
    if not isinstance(area, dict) or not area:
        return ""
    values = [
        area.get("serverKey"),
        area.get("areaName"),
        area.get("serverQuery"),
    ]
    platform_key = record_platform_key(sess)
    if any(str(value or "").strip() for value in values):
        area_key = normalized_area_key(*values)
        # Existing 三国联盟 maps keep their original key. 当乐 and future
        # platforms receive an explicit namespace and can never cross-share.
        return (
            area_key
            if platform_key == DEFAULT_PLATFORM_KEY
            else f"{platform_key}:{area_key}"
        )
    area_id = str(area.get("areaId") or "").strip()
    if not area_id.isdigit():
        return ""
    area_key = f"区{area_id}"
    return (
        area_key
        if platform_key == DEFAULT_PLATFORM_KEY
        else f"{platform_key}:{area_key}"
    )


def shared_map_storage_path(server_key: str, map_kind: str) -> Path:
    stem = storage_slug(f"{server_key}_{map_kind}", fallback="unknown_map")
    return SHARED_MAP_DIR / f"{stem}.json"


def shared_map_response_path(server_key: str, map_kind: str) -> Path:
    stem = storage_slug(f"{server_key}_{map_kind}", fallback="unknown_map")
    return SHARED_MAP_DIR / f"{stem}_responses.jsonl"


def new_shared_map(server_key: str, map_kind: str) -> dict[str, Any]:
    return {
        "version": 1,
        "serverKey": server_key,
        "mapKind": map_kind,
        "createdAt": now_ms(),
        "updatedAt": 0,
        "regions": {},
        "targets": {},
        "scanLeases": {},
    }


def compact_bandit_target(target: dict[str, Any], scan_x: int, scan_y: int) -> dict[str, Any]:
    """Keep only fields used by map display, filtering, revalidation and dispatch."""
    composition = target.get("composition")
    compact_composition = {}
    if isinstance(composition, dict) and composition.get("source") == "8540-units":
        compact_composition = {
            "foot": int(composition.get("foot") or 0),
            "bow": int(composition.get("bow") or 0),
            "cavalry": int(composition.get("cavalry") or 0),
            "chariot": int(composition.get("chariot") or 0),
            "source": "8540-units",
        }
    compact = {
        "id": int(target.get("id") or 0),
        "idHex": str(target.get("idHex") or ""),
        "kind": str(target.get("kind") or "山贼"),
        "name": str(target.get("name") or "山贼"),
        "level": int(target.get("level") or 0),
        "x": int(target.get("x") or 0),
        "y": int(target.get("y") or 0),
        "resource": str(target.get("resource") or ""),
        "dropCategories": [
            str(value)
            for value in (target.get("dropCategories") or [])
            if str(value or "")
        ],
        "lootIds": [
            int(value)
            for value in (target.get("lootIds") or [])
            if str(value).lstrip("-").isdigit()
        ],
        "composition": compact_composition,
        "compositionCode": str(target.get("compositionCode") or ""),
        "units": [
            {"soldierTypeCode": int(unit.get("soldierTypeCode", -1))}
            for unit in (target.get("units") or [])
            if int(unit.get("soldierTypeCode", -1)) >= 0
        ],
        "source": str(target.get("source") or ""),
        "scanCoord": [int(scan_x), int(scan_y)],
    }
    return compact


def compact_loaded_bandit_map(shared_map: dict[str, Any]) -> bool:
    """Migrate legacy maps that duplicated raw responses and full target structures."""
    if str(shared_map.get("mapKind") or "") != "bandit":
        return False
    changed = False
    for record in shared_map.setdefault("targets", {}).values():
        if not isinstance(record, dict) or not isinstance(record.get("target"), dict):
            continue
        target = record["target"]
        coord = target.get("scanCoord")
        scan_x = int(coord[0]) if isinstance(coord, (list, tuple)) and len(coord) >= 2 else int(target.get("x") or 0)
        scan_y = int(coord[1]) if isinstance(coord, (list, tuple)) and len(coord) >= 2 else int(target.get("y") or 0)
        compact = compact_bandit_target(target, scan_x, scan_y)
        if target != compact:
            record["target"] = compact
            changed = True
        for field in ("firstSeenAt", "seenCount", "statusReason"):
            if field in record:
                record.pop(field, None)
                changed = True
    for coord_key, entry in list(shared_map.setdefault("regions", {}).items()):
        if not isinstance(entry, dict):
            shared_map["regions"].pop(coord_key, None)
            changed = True
            continue
        compact_entry = {
            "scannedAt": int(entry.get("scannedAt") or 0),
            "targetKeys": [
                str(value)
                for value in (entry.get("targetKeys") or [])
                if str(value or "")
            ],
        }
        if entry != compact_entry:
            shared_map["regions"][coord_key] = compact_entry
            changed = True
    return changed


def _load_shared_map_locked(server_key: str, map_kind: str) -> dict[str, Any]:
    cache_key = (server_key, map_kind)
    cached = SHARED_MAPS.get(cache_key)
    if isinstance(cached, dict):
        return cached
    loaded = _read_json_file(shared_map_storage_path(server_key, map_kind))
    if not isinstance(loaded, dict) or loaded.get("serverKey") != server_key:
        loaded = new_shared_map(server_key, map_kind)
    loaded["version"] = 1
    loaded["serverKey"] = server_key
    loaded["mapKind"] = map_kind
    if not isinstance(loaded.get("regions"), dict):
        loaded["regions"] = {}
    if not isinstance(loaded.get("targets"), dict):
        loaded["targets"] = {}
    if not isinstance(loaded.get("scanLeases"), dict):
        loaded["scanLeases"] = {}
    migrated = compact_loaded_bandit_map(loaded)
    expired = _cleanup_shared_map_leases_locked(loaded, now_ms())
    SHARED_MAPS[cache_key] = loaded
    if migrated or expired:
        _persist_shared_map_locked(loaded)
    return loaded


def _persist_shared_map_locked(shared_map: dict[str, Any]) -> None:
    server_key = str(shared_map.get("serverKey") or "")
    map_kind = str(shared_map.get("mapKind") or "")
    if not server_key or not map_kind:
        return
    shared_map["updatedAt"] = now_ms()
    path = shared_map_storage_path(server_key, map_kind)
    tmp = path.with_name(f".{path.name}.{uuid4().hex}.tmp")
    tmp.write_text(
        json.dumps(
            json_safe(shared_map),
            ensure_ascii=False,
            separators=(",", ":"),
        ),
        encoding="utf-8",
    )
    tmp.replace(path)


def shared_map_target_key(target: dict[str, Any]) -> str:
    raw_id = normalize_bandit_target_id(target)
    if raw_id:
        return f"id:{raw_id}"
    return "coord:" + ":".join([
        str(target.get("x") or ""),
        str(target.get("y") or ""),
        str(target.get("kind") or ""),
        str(target.get("level") or ""),
        str(target.get("name") or ""),
    ])


def _cleanup_shared_map_leases_locked(shared_map: dict[str, Any], at_ms: int) -> bool:
    changed = False
    scan_leases = shared_map.setdefault("scanLeases", {})
    for coord_key, lease in list(scan_leases.items()):
        if not isinstance(lease, dict) or int(lease.get("leaseUntil") or 0) <= at_ms:
            scan_leases.pop(coord_key, None)
            changed = True
    targets = shared_map.setdefault("targets", {})
    expired_target_keys: set[str] = set()
    if str(shared_map.get("mapKind") or "") == "bandit":
        expired_target_keys = {
            str(target_key)
            for target_key, record in targets.items()
            if (
                not isinstance(record, dict)
                or at_ms - int(record.get("lastSeenAt") or 0) >= SHARED_MAP_TARGET_TTL_MS
            )
        }
        for target_key in expired_target_keys:
            targets.pop(target_key, None)
            changed = True
        for coord_key, entry in list(shared_map.setdefault("regions", {}).items()):
            if not isinstance(entry, dict) or at_ms - int(entry.get("scannedAt") or 0) >= SHARED_MAP_TARGET_TTL_MS:
                shared_map["regions"].pop(coord_key, None)
                changed = True
                continue
            old_keys = list(entry.get("targetKeys") or [])
            new_keys = [key for key in old_keys if str(key) not in expired_target_keys]
            if old_keys != new_keys:
                entry["targetKeys"] = new_keys
                changed = True
    for record in targets.values():
        if not isinstance(record, dict):
            continue
        status = str(record.get("status") or "available")
        expired_reservation = (
            status == "reserved"
            and int(record.get("leaseUntil") or 0) <= at_ms
        )
        expired_reject = (
            status == "rejected"
            and int(record.get("retryAfter") or 0) <= at_ms
        )
        if expired_reservation or expired_reject:
            record["status"] = "available" if record.get("seenIn") else "missing"
            record["reservedBy"] = ""
            record["reservedTaskId"] = ""
            record["leaseUntil"] = 0
            record["retryAfter"] = 0
            changed = True
    for target_key, record in list(targets.items()):
        if not isinstance(record, dict) or str(record.get("status") or "") == "missing":
            targets.pop(target_key, None)
            changed = True
    return changed


DROP_CATEGORY_BITS = {
    "资源": 1,
    "宝箱": 2,
    "装备": 4,
    "宝物": 8,
}


def bandit_db_path() -> Path:
    return SHARED_MAP_DIR / "shared_maps.sqlite3"


def normalize_bandit_target_id(target_or_key: Any) -> str:
    if isinstance(target_or_key, dict):
        raw = str(target_or_key.get("idHex") or "")
        if not raw and target_or_key.get("id") not in (None, ""):
            raw = f"{int(target_or_key.get('id')):x}"
    else:
        raw = str(target_or_key or "")
    raw = raw.lower().removeprefix("id:").removeprefix("0x")
    clean = "".join(char for char in raw if char in "0123456789abcdef")
    return clean[-16:].rjust(16, "0") if clean else ""


def bandit_drop_mask(categories: Any, reward_text: Any = "") -> int:
    values = list(categories or []) if isinstance(categories, (list, tuple, set)) else []
    if not values:
        values = bandit_drop_categories(reward_text)
    mask = 0
    for value in values:
        mask |= DROP_CATEGORY_BITS.get(str(value), 0)
    return mask


def bandit_drop_categories_from_mask(mask: Any) -> list[str]:
    value = int(mask or 0)
    return [name for name, bit in DROP_CATEGORY_BITS.items() if value & bit]


def _bandit_db_connect(*, initialize: bool = True) -> sqlite3.Connection:
    path = bandit_db_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    path_key = str(path.resolve())
    cached = getattr(SQLITE_THREAD_LOCAL, "bandit_connection", None)
    cached_path = getattr(SQLITE_THREAD_LOCAL, "bandit_connection_path", "")
    if cached is not None and cached_path == path_key:
        if initialize:
            _initialize_bandit_db(cached, path)
        return cached
    if cached is not None:
        try:
            cached.close()
        except sqlite3.Error:
            pass
    connection = sqlite3.connect(
        str(path),
        timeout=5.0,
        isolation_level=None,
    )
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys=ON")
    connection.execute("PRAGMA busy_timeout=5000")
    connection.execute("PRAGMA synchronous=NORMAL")
    if initialize:
        _initialize_bandit_db(connection, path)
    SQLITE_THREAD_LOCAL.bandit_connection = connection
    SQLITE_THREAD_LOCAL.bandit_connection_path = path_key
    return connection


def _initialize_bandit_db(connection: sqlite3.Connection, path: Path) -> None:
    path_key = str(path.resolve())
    if path_key in BANDIT_DB_INITIALIZED_PATHS:
        return
    with BANDIT_DB_INIT_LOCK:
        if path_key in BANDIT_DB_INITIALIZED_PATHS:
            return
        connection.execute("PRAGMA journal_mode=WAL")
        connection.execute("PRAGMA synchronous=NORMAL")
        connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS bandit_meta (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS bandit_targets (
                server_key TEXT NOT NULL,
                target_id_hex TEXT NOT NULL,
                name TEXT NOT NULL,
                kind TEXT NOT NULL,
                level INTEGER NOT NULL,
                x INTEGER NOT NULL,
                y INTEGER NOT NULL,
                reward_text TEXT NOT NULL DEFAULT '',
                drop_mask INTEGER NOT NULL DEFAULT 0,
                loot_ids_json TEXT NOT NULL DEFAULT '[]',
                unit_types_json TEXT NOT NULL DEFAULT '[]',
                foot_count INTEGER NOT NULL DEFAULT 0,
                bow_count INTEGER NOT NULL DEFAULT 0,
                cavalry_count INTEGER NOT NULL DEFAULT 0,
                chariot_count INTEGER NOT NULL DEFAULT 0,
                last_seen_at INTEGER NOT NULL,
                status TEXT NOT NULL DEFAULT 'available',
                reserved_by TEXT NOT NULL DEFAULT '',
                reserved_task_id TEXT NOT NULL DEFAULT '',
                lease_until INTEGER NOT NULL DEFAULT 0,
                retry_after INTEGER NOT NULL DEFAULT 0,
                status_reason TEXT NOT NULL DEFAULT '',
                status_at INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (server_key, target_id_hex)
            );

            CREATE TABLE IF NOT EXISTS bandit_regions (
                server_key TEXT NOT NULL,
                scan_x INTEGER NOT NULL,
                scan_y INTEGER NOT NULL,
                scanned_at INTEGER NOT NULL,
                PRIMARY KEY (server_key, scan_x, scan_y)
            );

            CREATE TABLE IF NOT EXISTS bandit_target_regions (
                server_key TEXT NOT NULL,
                target_id_hex TEXT NOT NULL,
                scan_x INTEGER NOT NULL,
                scan_y INTEGER NOT NULL,
                last_seen_at INTEGER NOT NULL,
                PRIMARY KEY (
                    server_key, target_id_hex, scan_x, scan_y
                ),
                FOREIGN KEY (server_key, target_id_hex)
                    REFERENCES bandit_targets(server_key, target_id_hex)
                    ON DELETE CASCADE,
                FOREIGN KEY (server_key, scan_x, scan_y)
                    REFERENCES bandit_regions(server_key, scan_x, scan_y)
                    ON DELETE CASCADE
            );

            CREATE TABLE IF NOT EXISTS bandit_scan_leases (
                server_key TEXT NOT NULL,
                scan_x INTEGER NOT NULL,
                scan_y INTEGER NOT NULL,
                owner TEXT NOT NULL,
                lease_until INTEGER NOT NULL,
                PRIMARY KEY (server_key, scan_x, scan_y)
            );

            CREATE INDEX IF NOT EXISTS idx_bandit_targets_recent
                ON bandit_targets(server_key, last_seen_at);
            CREATE INDEX IF NOT EXISTS idx_bandit_targets_available
                ON bandit_targets(server_key, status, level, last_seen_at);
            CREATE INDEX IF NOT EXISTS idx_bandit_targets_xy
                ON bandit_targets(server_key, x, y);
            CREATE INDEX IF NOT EXISTS idx_bandit_target_regions_scan
                ON bandit_target_regions(server_key, scan_x, scan_y);
            CREATE INDEX IF NOT EXISTS idx_bandit_target_regions_latest
                ON bandit_target_regions(server_key, target_id_hex, last_seen_at);

            CREATE TABLE IF NOT EXISTS mine_meta (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS mine_targets (
                server_key TEXT NOT NULL,
                target_id_hex TEXT NOT NULL,
                type_code INTEGER NOT NULL,
                business_id INTEGER,
                kind TEXT NOT NULL,
                protocol_kind TEXT NOT NULL DEFAULT '',
                level INTEGER NOT NULL,
                x INTEGER NOT NULL,
                y INTEGER NOT NULL,
                detail_flag INTEGER NOT NULL DEFAULT 1,
                owner_name TEXT NOT NULL DEFAULT '',
                owner_country TEXT NOT NULL DEFAULT '',
                player_occupied INTEGER NOT NULL DEFAULT 0,
                amount_a INTEGER,
                amount_b INTEGER,
                description TEXT NOT NULL DEFAULT '',
                value_j INTEGER,
                value_k INTEGER,
                troop_groups_json TEXT NOT NULL DEFAULT '[]',
                defender_count INTEGER NOT NULL DEFAULT 0,
                defenders_json TEXT NOT NULL DEFAULT '[]',
                last_seen_at INTEGER NOT NULL,
                status TEXT NOT NULL DEFAULT 'available',
                reserved_by TEXT NOT NULL DEFAULT '',
                reserved_task_id TEXT NOT NULL DEFAULT '',
                lease_until INTEGER NOT NULL DEFAULT 0,
                retry_after INTEGER NOT NULL DEFAULT 0,
                status_reason TEXT NOT NULL DEFAULT '',
                status_at INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (server_key, target_id_hex)
            );

            CREATE TABLE IF NOT EXISTS mine_regions (
                server_key TEXT NOT NULL,
                scan_x INTEGER NOT NULL,
                scan_y INTEGER NOT NULL,
                scanned_at INTEGER NOT NULL,
                PRIMARY KEY (server_key, scan_x, scan_y)
            );

            CREATE TABLE IF NOT EXISTS mine_target_regions (
                server_key TEXT NOT NULL,
                target_id_hex TEXT NOT NULL,
                scan_x INTEGER NOT NULL,
                scan_y INTEGER NOT NULL,
                last_seen_at INTEGER NOT NULL,
                PRIMARY KEY (server_key, target_id_hex, scan_x, scan_y),
                FOREIGN KEY (server_key, target_id_hex)
                    REFERENCES mine_targets(server_key, target_id_hex)
                    ON DELETE CASCADE,
                FOREIGN KEY (server_key, scan_x, scan_y)
                    REFERENCES mine_regions(server_key, scan_x, scan_y)
                    ON DELETE CASCADE
            );

            CREATE TABLE IF NOT EXISTS mine_scan_leases (
                server_key TEXT NOT NULL,
                scan_x INTEGER NOT NULL,
                scan_y INTEGER NOT NULL,
                owner TEXT NOT NULL,
                lease_until INTEGER NOT NULL,
                PRIMARY KEY (server_key, scan_x, scan_y)
            );

            CREATE INDEX IF NOT EXISTS idx_mine_targets_recent
                ON mine_targets(server_key, last_seen_at);
            CREATE INDEX IF NOT EXISTS idx_mine_targets_available
                ON mine_targets(
                    server_key, status, kind, player_occupied, last_seen_at
                );
            CREATE INDEX IF NOT EXISTS idx_mine_targets_xy
                ON mine_targets(server_key, x, y);
            CREATE INDEX IF NOT EXISTS idx_mine_target_regions_scan
                ON mine_target_regions(server_key, scan_x, scan_y);
            """
        )
        bandit_columns = {
            str(row["name"])
            for row in connection.execute("PRAGMA table_info(bandit_targets)").fetchall()
        }
        if "unit_types_json" not in bandit_columns:
            connection.execute(
                "ALTER TABLE bandit_targets ADD COLUMN unit_types_json TEXT NOT NULL DEFAULT '[]'"
            )
        connection.execute(
            """
            INSERT INTO bandit_meta(key, value) VALUES('schema_version', ?)
            ON CONFLICT(key) DO UPDATE SET value=excluded.value
            """,
            (str(BANDIT_DB_SCHEMA_VERSION),),
        )
        connection.execute(
            """
            INSERT INTO mine_meta(key, value) VALUES('schema_version', ?)
            ON CONFLICT(key) DO UPDATE SET value=excluded.value
            """,
            (str(MINE_DB_SCHEMA_VERSION),),
        )
        _migrate_bandit_json_files(connection)
        _migrate_mine_json_files(connection)
        BANDIT_DB_INITIALIZED_PATHS.add(path_key)


def _bandit_cleanup_sql(
    connection: sqlite3.Connection,
    at_ms: int,
) -> None:
    cutoff = int(at_ms) - SHARED_MAP_TARGET_TTL_MS
    connection.execute(
        """
        UPDATE bandit_targets
        SET status='available', reserved_by='', reserved_task_id='',
            lease_until=0, retry_after=0, status_reason=''
        WHERE status='reserved' AND lease_until <= ?
        """,
        (int(at_ms),),
    )
    connection.execute(
        """
        UPDATE bandit_targets
        SET status='available', reserved_by='', reserved_task_id='',
            lease_until=0, retry_after=0, status_reason=''
        WHERE status='rejected' AND retry_after <= ?
        """,
        (int(at_ms),),
    )
    connection.execute(
        "DELETE FROM bandit_scan_leases WHERE lease_until <= ?",
        (int(at_ms),),
    )
    connection.execute(
        "DELETE FROM bandit_targets WHERE last_seen_at < ?",
        (cutoff,),
    )
    connection.execute(
        "DELETE FROM bandit_regions WHERE scanned_at < ?",
        (cutoff,),
    )
    connection.execute(
        """
        DELETE FROM bandit_targets
        WHERE NOT EXISTS (
            SELECT 1 FROM bandit_target_regions relation
            WHERE relation.server_key=bandit_targets.server_key
              AND relation.target_id_hex=bandit_targets.target_id_hex
        )
        """
    )


def _bandit_target_from_row(row: sqlite3.Row) -> dict[str, Any]:
    target_id_hex = normalize_bandit_target_id(row["target_id_hex"])
    try:
        loot_ids = [
            int(value)
            for value in json.loads(str(row["loot_ids_json"] or "[]"))
            if str(value).lstrip("-").isdigit()
        ]
    except Exception:
        loot_ids = []
    try:
        unit_types = [
            int(value)
            for value in json.loads(str(row["unit_types_json"] or "[]"))
        ]
    except Exception:
        unit_types = []
    target = {
        "id": int(target_id_hex, 16) if target_id_hex else 0,
        "idHex": target_id_hex,
        "kind": str(row["kind"] or "山贼"),
        "name": str(row["name"] or "山贼"),
        "level": int(row["level"] or 0),
        "x": int(row["x"] or 0),
        "y": int(row["y"] or 0),
        "resource": str(row["reward_text"] or ""),
        "dropCategories": bandit_drop_categories_from_mask(row["drop_mask"]),
        "lootIds": loot_ids,
        "composition": {
            "foot": int(row["foot_count"] or 0),
            "bow": int(row["bow_count"] or 0),
            "cavalry": int(row["cavalry_count"] or 0),
            "chariot": int(row["chariot_count"] or 0),
            "source": "8540-units",
        },
        "compositionCode": (
            f"{int(row['foot_count'] or 0)}{int(row['bow_count'] or 0)}"
            f"{int(row['cavalry_count'] or 0)}{int(row['chariot_count'] or 0)}"
        ),
        "units": [{"soldierTypeCode": code} for code in unit_types],
        "source": "8540-structured",
    }
    row_keys = set(row.keys())
    if "scan_x" in row_keys and row["scan_x"] is not None:
        target["scanCoord"] = [int(row["scan_x"]), int(row["scan_y"])]
    return target


def _bandit_target_select_sql(where_sql: str = "") -> str:
    return f"""
        SELECT target.*,
            (
                SELECT relation.scan_x
                FROM bandit_target_regions relation
                WHERE relation.server_key=target.server_key
                  AND relation.target_id_hex=target.target_id_hex
                ORDER BY relation.last_seen_at DESC
                LIMIT 1
            ) AS scan_x,
            (
                SELECT relation.scan_y
                FROM bandit_target_regions relation
                WHERE relation.server_key=target.server_key
                  AND relation.target_id_hex=target.target_id_hex
                ORDER BY relation.last_seen_at DESC
                LIMIT 1
            ) AS scan_y
        FROM bandit_targets target
        {where_sql}
    """


def _migrate_bandit_json_files(connection: sqlite3.Connection) -> None:
    for obsolete_path in SHARED_MAP_DIR.glob("*_bandit.json.migrated"):
        try:
            obsolete_path.unlink()
        except Exception:
            pass
    migrated = connection.execute(
        "SELECT value FROM bandit_meta WHERE key='legacy_json_migrated'"
    ).fetchone()
    if migrated:
        return
    cutoff = now_ms() - SHARED_MAP_TARGET_TTL_MS
    for path in sorted(SHARED_MAP_DIR.glob("*_bandit.json")):
        payload = _read_json_file(path)
        if not isinstance(payload, dict):
            continue
        server_key = str(payload.get("serverKey") or "").strip()
        if not server_key:
            continue
        regions = payload.get("regions") if isinstance(payload.get("regions"), dict) else {}
        targets = payload.get("targets") if isinstance(payload.get("targets"), dict) else {}
        connection.execute("BEGIN IMMEDIATE")
        try:
            for coord_key, entry in regions.items():
                if not isinstance(entry, dict):
                    continue
                try:
                    scan_x, scan_y = [int(value) for value in str(coord_key).split(",", 1)]
                except Exception:
                    continue
                scanned_at = int(entry.get("scannedAt") or 0)
                if scanned_at < cutoff:
                    continue
                connection.execute(
                    """
                    INSERT INTO bandit_regions(server_key, scan_x, scan_y, scanned_at)
                    VALUES(?, ?, ?, ?)
                    ON CONFLICT(server_key, scan_x, scan_y)
                    DO UPDATE SET scanned_at=excluded.scanned_at
                    """,
                    (server_key, scan_x, scan_y, scanned_at),
                )
            for record in targets.values():
                if not isinstance(record, dict) or not isinstance(record.get("target"), dict):
                    continue
                target = record["target"]
                last_seen_at = int(record.get("lastSeenAt") or 0)
                target_id = normalize_bandit_target_id(target)
                if not target_id or last_seen_at < cutoff:
                    continue
                composition = target.get("composition") or {}
                connection.execute(
                    """
                    INSERT OR REPLACE INTO bandit_targets(
                        server_key, target_id_hex, name, kind, level, x, y,
                        reward_text, drop_mask, loot_ids_json,
                        foot_count, bow_count, cavalry_count, chariot_count,
                        last_seen_at, status, reserved_by, reserved_task_id,
                        lease_until, retry_after
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        server_key, target_id,
                        str(target.get("name") or "山贼"),
                        str(target.get("kind") or "山贼"),
                        int(target.get("level") or 0),
                        int(target.get("x") or 0),
                        int(target.get("y") or 0),
                        str(target.get("resource") or ""),
                        bandit_drop_mask(target.get("dropCategories"), target.get("resource")),
                        json.dumps(target.get("lootIds") or [], separators=(",", ":")),
                        int(composition.get("foot") or 0),
                        int(composition.get("bow") or 0),
                        int(composition.get("cavalry") or 0),
                        int(composition.get("chariot") or 0),
                        last_seen_at,
                        str(record.get("status") or "available"),
                        str(record.get("reservedBy") or ""),
                        str(record.get("reservedTaskId") or ""),
                        int(record.get("leaseUntil") or 0),
                        int(record.get("retryAfter") or 0),
                    ),
                )
                seen_in = record.get("seenIn") if isinstance(record.get("seenIn"), dict) else {}
                if not seen_in:
                    coord = target.get("scanCoord")
                    if isinstance(coord, (list, tuple)) and len(coord) >= 2:
                        seen_in = {f"{int(coord[0])},{int(coord[1])}": last_seen_at}
                for coord_key, relation_seen_at in seen_in.items():
                    try:
                        scan_x, scan_y = [int(value) for value in str(coord_key).split(",", 1)]
                    except Exception:
                        continue
                    connection.execute(
                        """
                        INSERT OR IGNORE INTO bandit_regions(
                            server_key, scan_x, scan_y, scanned_at
                        ) VALUES(?, ?, ?, ?)
                        """,
                        (server_key, scan_x, scan_y, int(relation_seen_at or last_seen_at)),
                    )
                    connection.execute(
                        """
                        INSERT OR REPLACE INTO bandit_target_regions(
                            server_key, target_id_hex, scan_x, scan_y, last_seen_at
                        ) VALUES(?, ?, ?, ?, ?)
                        """,
                        (server_key, target_id, scan_x, scan_y, int(relation_seen_at or last_seen_at)),
                    )
            _bandit_cleanup_sql(connection, now_ms())
            connection.execute("COMMIT")
        except Exception:
            connection.execute("ROLLBACK")
            raise
        try:
            path.unlink()
        except Exception:
            pass
    for response_path in SHARED_MAP_DIR.glob("*_bandit_responses.jsonl"):
        try:
            response_path.unlink()
        except Exception:
            pass
    connection.execute(
        """
        INSERT INTO bandit_meta(key, value) VALUES('legacy_json_migrated', ?)
        ON CONFLICT(key) DO UPDATE SET value=excluded.value
        """,
        (str(now_ms()),),
    )


def _mine_cleanup_sql(connection: sqlite3.Connection, at_ms: int) -> None:
    cutoff = int(at_ms) - MINE_MAP_TARGET_TTL_MS
    connection.execute(
        """
        UPDATE mine_targets
        SET status='available', reserved_by='', reserved_task_id='',
            lease_until=0, retry_after=0, status_reason=''
        WHERE status='reserved' AND lease_until<=?
        """,
        (int(at_ms),),
    )
    connection.execute(
        """
        UPDATE mine_targets
        SET status='available', reserved_by='', reserved_task_id='',
            lease_until=0, retry_after=0, status_reason=''
        WHERE status='rejected' AND retry_after<=?
        """,
        (int(at_ms),),
    )
    connection.execute(
        "DELETE FROM mine_scan_leases WHERE lease_until<=?",
        (int(at_ms),),
    )
    connection.execute(
        "DELETE FROM mine_targets WHERE last_seen_at<?",
        (cutoff,),
    )
    connection.execute(
        "DELETE FROM mine_regions WHERE scanned_at<?",
        (cutoff,),
    )
    connection.execute(
        """
        DELETE FROM mine_targets
        WHERE NOT EXISTS (
            SELECT 1 FROM mine_target_regions relation
            WHERE relation.server_key=mine_targets.server_key
              AND relation.target_id_hex=mine_targets.target_id_hex
        )
        """
    )


def cleanup_shared_map_if_due(
    connection: sqlite3.Connection,
    map_kind: str,
    at_ms: int,
) -> bool:
    """Run expensive TTL cleanup at most once a minute per database."""
    row = connection.execute("PRAGMA database_list").fetchone()
    database_path = str(row[2] if row and len(row) > 2 else bandit_db_path())
    cleanup_key = (database_path, str(map_kind))
    with SHARED_MAP_CLEANUP_LOCK:
        previous = int(SHARED_MAP_LAST_CLEANUP_AT.get(cleanup_key) or 0)
        if int(at_ms) - previous < SHARED_MAP_CLEANUP_INTERVAL_MS:
            return False
        SHARED_MAP_LAST_CLEANUP_AT[cleanup_key] = int(at_ms)
    try:
        connection.execute("BEGIN IMMEDIATE")
        if map_kind == "bandit":
            _bandit_cleanup_sql(connection, at_ms)
        else:
            _mine_cleanup_sql(connection, at_ms)
        connection.execute("COMMIT")
        return True
    except Exception:
        connection.execute("ROLLBACK")
        with SHARED_MAP_CLEANUP_LOCK:
            SHARED_MAP_LAST_CLEANUP_AT.pop(cleanup_key, None)
        raise


def _mine_json_list(value: Any) -> list[Any]:
    if isinstance(value, list):
        return value
    try:
        parsed = json.loads(str(value or "[]"))
        return parsed if isinstance(parsed, list) else []
    except Exception:
        return []


def _mine_target_from_row(row: sqlite3.Row) -> dict[str, Any]:
    target_id_hex = normalize_bandit_target_id(row["target_id_hex"])
    troop_groups = _mine_json_list(row["troop_groups_json"])
    defenders = _mine_json_list(row["defenders_json"])
    owner_name = str(row["owner_name"] or "")
    owner_country = str(row["owner_country"] or "")
    amount_a = row["amount_a"]
    amount_b = row["amount_b"]
    detail = {
        "flag": int(row["detail_flag"] or 0),
        "ownerName": owner_name,
        "ownerCountry": owner_country,
        "text1": owner_name,
        "text2": owner_country,
        "amountA": amount_a,
        "amountB": amount_b,
        "description": str(row["description"] or ""),
        "valueJ": row["value_j"],
        "valueK": row["value_k"],
    }
    occupied = bool(row["player_occupied"])
    target = {
        "id": int(target_id_hex, 16) if target_id_hex else 0,
        "idHex": target_id_hex,
        "typeCode": int(row["type_code"] or 0),
        "businessId": row["business_id"],
        "kind": str(row["kind"] or ""),
        "protocolKind": str(row["protocol_kind"] or ""),
        "name": (
            str(row["kind"] or "")
            if int(row["type_code"] or 0) == 5
            else f"{int(row['level'] or 0)}级{str(row['kind'] or '')}"
        ),
        "level": int(row["level"] or 0),
        "rank": int(row["level"] or 0),
        "x": int(row["x"] or 0),
        "y": int(row["y"] or 0),
        "detailFlag": int(row["detail_flag"] or 0),
        "detail": detail,
        "ownerName": owner_name,
        "ownerCountry": owner_country,
        "playerOccupied": occupied,
        "unoccupiedByPlayer": not occupied,
        "isEmpty": not occupied,
        "occupied": occupied,
        "amountA": amount_a,
        "amountB": amount_b,
        "storage": amount_a,
        "productionPerHour": amount_b,
        "description": str(row["description"] or ""),
        "valueJ": row["value_j"],
        "valueK": row["value_k"],
        "troopGroups": troop_groups,
        "defenders": defenders,
        "defenderCount": int(row["defender_count"] or 0),
        "hasDefenders": int(row["defender_count"] or 0) > 0,
        "source": "sqlite-8542",
    }
    row_keys = set(row.keys())
    if "scan_x" in row_keys and row["scan_x"] is not None:
        target["scanCoord"] = [int(row["scan_x"]), int(row["scan_y"])]
    return target


def _mine_target_select_sql(where_sql: str = "") -> str:
    return f"""
        SELECT target.*,
            (
                SELECT relation.scan_x
                FROM mine_target_regions relation
                WHERE relation.server_key=target.server_key
                  AND relation.target_id_hex=target.target_id_hex
                ORDER BY relation.last_seen_at DESC LIMIT 1
            ) AS scan_x,
            (
                SELECT relation.scan_y
                FROM mine_target_regions relation
                WHERE relation.server_key=target.server_key
                  AND relation.target_id_hex=target.target_id_hex
                ORDER BY relation.last_seen_at DESC LIMIT 1
            ) AS scan_y
        FROM mine_targets target
        {where_sql}
    """


def _mine_upsert_target(
    connection: sqlite3.Connection,
    server_key: str,
    target: dict[str, Any],
    seen_at: int,
) -> str:
    target_id = normalize_bandit_target_id(target)
    if not target_id:
        return ""
    detail = target.get("detail") if isinstance(target.get("detail"), dict) else {}
    owner_name = str(
        target.get("ownerName") or detail.get("ownerName") or detail.get("text1") or ""
    )
    owner_country = str(
        target.get("ownerCountry") or detail.get("ownerCountry") or detail.get("text2") or ""
    )
    occupied = bool(
        target.get("playerOccupied")
        if target.get("playerOccupied") is not None
        else (owner_name or owner_country)
    )
    amount_a = target.get("amountA", detail.get("amountA", target.get("storage")))
    amount_b = target.get(
        "amountB", detail.get("amountB", target.get("productionPerHour"))
    )
    connection.execute(
        """
        INSERT INTO mine_targets(
            server_key, target_id_hex, type_code, business_id, kind,
            protocol_kind, level, x, y, detail_flag, owner_name,
            owner_country, player_occupied, amount_a, amount_b,
            description, value_j, value_k, troop_groups_json,
            defender_count, defenders_json, last_seen_at
        ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(server_key, target_id_hex) DO UPDATE SET
            type_code=excluded.type_code,
            business_id=excluded.business_id,
            kind=excluded.kind,
            protocol_kind=excluded.protocol_kind,
            level=excluded.level,
            x=excluded.x,
            y=excluded.y,
            detail_flag=excluded.detail_flag,
            owner_name=excluded.owner_name,
            owner_country=excluded.owner_country,
            player_occupied=excluded.player_occupied,
            amount_a=excluded.amount_a,
            amount_b=excluded.amount_b,
            description=excluded.description,
            value_j=excluded.value_j,
            value_k=excluded.value_k,
            troop_groups_json=excluded.troop_groups_json,
            defender_count=excluded.defender_count,
            defenders_json=excluded.defenders_json,
            last_seen_at=excluded.last_seen_at,
            status=CASE
                WHEN mine_targets.status='missing' THEN 'available'
                ELSE mine_targets.status
            END
        """,
        (
            server_key,
            target_id,
            int(target.get("typeCode") or 0),
            target.get("businessId"),
            str(target.get("kind") or ""),
            str(target.get("protocolKind") or ""),
            int(target.get("level") or 0),
            int(target.get("x") or 0),
            int(target.get("y") or 0),
            int(target.get("detailFlag") or detail.get("flag") or 0),
            owner_name,
            owner_country,
            int(occupied),
            amount_a,
            amount_b,
            str(target.get("description") or detail.get("description") or ""),
            target.get("valueJ", detail.get("valueJ")),
            target.get("valueK", detail.get("valueK")),
            json.dumps(target.get("troopGroups") or [], ensure_ascii=False, separators=(",", ":")),
            int(target.get("defenderCount") or len(target.get("defenders") or [])),
            json.dumps(target.get("defenders") or [], ensure_ascii=False, separators=(",", ":")),
            int(seen_at),
        ),
    )
    return target_id


def _migrate_mine_json_files(connection: sqlite3.Connection) -> None:
    for obsolete_path in SHARED_MAP_DIR.glob("*_mine.json.migrated"):
        try:
            obsolete_path.unlink()
        except Exception:
            pass
    migrated = connection.execute(
        "SELECT value FROM mine_meta WHERE key='legacy_json_migrated'"
    ).fetchone()
    if migrated:
        return
    cutoff = now_ms() - MINE_MAP_TARGET_TTL_MS
    for path in sorted(SHARED_MAP_DIR.glob("*_mine.json")):
        payload = _read_json_file(path)
        if not isinstance(payload, dict):
            continue
        server_key = str(payload.get("serverKey") or "").strip()
        if not server_key:
            continue
        regions = payload.get("regions") if isinstance(payload.get("regions"), dict) else {}
        targets = payload.get("targets") if isinstance(payload.get("targets"), dict) else {}
        connection.execute("BEGIN IMMEDIATE")
        try:
            for coord_key, entry in regions.items():
                if not isinstance(entry, dict):
                    continue
                try:
                    scan_x, scan_y = [int(value) for value in str(coord_key).split(",", 1)]
                except Exception:
                    continue
                scanned_at = int(entry.get("scannedAt") or 0)
                if scanned_at < cutoff:
                    continue
                connection.execute(
                    """
                    INSERT INTO mine_regions(server_key, scan_x, scan_y, scanned_at)
                    VALUES(?, ?, ?, ?)
                    ON CONFLICT(server_key, scan_x, scan_y)
                    DO UPDATE SET scanned_at=excluded.scanned_at
                    """,
                    (server_key, scan_x, scan_y, scanned_at),
                )
            for record in targets.values():
                if not isinstance(record, dict) or not isinstance(record.get("target"), dict):
                    continue
                target = record["target"]
                seen_at = int(record.get("lastSeenAt") or 0)
                if seen_at < cutoff:
                    continue
                target_id = _mine_upsert_target(connection, server_key, target, seen_at)
                if not target_id:
                    continue
                seen_in = record.get("seenIn") if isinstance(record.get("seenIn"), dict) else {}
                if not seen_in:
                    coord = target.get("scanCoord")
                    if isinstance(coord, (list, tuple)) and len(coord) >= 2:
                        seen_in = {f"{int(coord[0])},{int(coord[1])}": seen_at}
                for coord_key, relation_seen_at in seen_in.items():
                    try:
                        scan_x, scan_y = [int(value) for value in str(coord_key).split(",", 1)]
                    except Exception:
                        continue
                    relation_seen_at = int(relation_seen_at or seen_at)
                    connection.execute(
                        """
                        INSERT OR IGNORE INTO mine_regions(
                            server_key, scan_x, scan_y, scanned_at
                        ) VALUES(?, ?, ?, ?)
                        """,
                        (server_key, scan_x, scan_y, relation_seen_at),
                    )
                    connection.execute(
                        """
                        INSERT OR REPLACE INTO mine_target_regions(
                            server_key, target_id_hex, scan_x, scan_y, last_seen_at
                        ) VALUES(?, ?, ?, ?, ?)
                        """,
                        (server_key, target_id, scan_x, scan_y, relation_seen_at),
                    )
            _mine_cleanup_sql(connection, now_ms())
            connection.execute("COMMIT")
        except Exception:
            connection.execute("ROLLBACK")
            raise
        try:
            path.unlink()
        except Exception:
            pass
    connection.execute(
        """
        INSERT INTO mine_meta(key, value) VALUES('legacy_json_migrated', ?)
        ON CONFLICT(key) DO UPDATE SET value=excluded.value
        """,
        (str(now_ms()),),
    )


def public_bandit_map(sess: dict[str, Any]) -> dict[str, Any]:
    server_key = shared_map_server_key(sess)
    if not server_key:
        raise RuntimeError("当前账号没有可识别的区服，无法读取山贼地图")
    at_ms = now_ms()
    with _bandit_db_connect() as connection:
        cleanup_shared_map_if_due(connection, "bandit", at_ms)
        connection.execute("BEGIN IMMEDIATE")
        try:
            rows = connection.execute(
                _bandit_target_select_sql(
                    "WHERE target.server_key=?"
                ),
                (server_key,),
            ).fetchall()
            updated_row = connection.execute(
                "SELECT MAX(scanned_at) AS updated_at FROM bandit_regions WHERE server_key=?",
                (server_key,),
            ).fetchone()
            connection.execute("COMMIT")
        except Exception:
            connection.execute("ROLLBACK")
            raise
    records = []
    for row in rows:
        target = _bandit_target_from_row(row)
        records.append({
            **target,
            "updatedAt": int(row["last_seen_at"] or 0),
            "status": str(row["status"] or "available"),
        })
    return shared_local_view("GET", "/api/maps/bandits", {
        "serverKey": server_key,
        "updatedAt": int((updated_row or {})["updated_at"] or 0),
        "records": records,
    })


