def shared_map_region_entry(
    sess: dict[str, Any],
    map_kind: str,
    coord_key: str,
) -> dict[str, Any] | None:
    server_key = shared_map_server_key(sess)
    if not server_key:
        return None
    if map_kind in {"bandit", "mine"}:
        try:
            scan_x, scan_y = [int(value) for value in str(coord_key).split(",", 1)]
        except Exception:
            return None
        prefix = "bandit" if map_kind == "bandit" else "mine"
        with _bandit_db_connect() as connection:
            row = connection.execute(
                f"""
                SELECT scanned_at FROM {prefix}_regions
                WHERE server_key=? AND scan_x=? AND scan_y=?
                """,
                (server_key, scan_x, scan_y),
            ).fetchone()
            if not row:
                return None
            keys = [
                f"id:{str(item['target_id_hex'])}"
                for item in connection.execute(
                    f"""
                    SELECT target_id_hex FROM {prefix}_target_regions
                    WHERE server_key=? AND scan_x=? AND scan_y=?
                    """,
                    (server_key, scan_x, scan_y),
                ).fetchall()
            ]
        return {"scannedAt": int(row["scanned_at"]), "targetKeys": keys}
    with SHARED_MAP_LOCK:
        shared_map = _load_shared_map_locked(server_key, map_kind)
        entry = shared_map.get("regions", {}).get(coord_key)
        return dict(entry) if isinstance(entry, dict) else None


def shared_map_region_scan_times(
    sess: dict[str, Any],
    map_kind: str,
    coords: list[tuple[int, int]],
) -> dict[tuple[int, int], int]:
    """Read scan timestamps for a batch of coordinates in one SQLite query."""
    server_key = shared_map_server_key(sess)
    normalized = list(dict.fromkeys(
        (int(coord[0]), int(coord[1]))
        for coord in coords
        if isinstance(coord, (list, tuple)) and len(coord) >= 2
    ))
    if not server_key or not normalized:
        return {}
    if map_kind not in {"bandit", "mine"}:
        return {
            coord: int(entry.get("scannedAt") or 0)
            for coord in normalized
            for entry in [shared_map_region_entry(
                sess, map_kind, f"{coord[0]},{coord[1]}",
            )]
            if isinstance(entry, dict)
        }
    prefix = "bandit" if map_kind == "bandit" else "mine"
    placeholders = ",".join("(?, ?)" for _ in normalized)
    params: list[Any] = [
        value
        for coord in normalized
        for value in coord
    ]
    params.append(server_key)
    with _bandit_db_connect() as connection:
        rows = connection.execute(
            f"""
            WITH requested(scan_x, scan_y) AS (VALUES {placeholders})
            SELECT region.scan_x, region.scan_y, region.scanned_at
            FROM {prefix}_regions AS region
            JOIN requested
              ON requested.scan_x=region.scan_x
             AND requested.scan_y=region.scan_y
            WHERE region.server_key=?
            """,
            params,
        ).fetchall()
    return {
        (int(row["scan_x"]), int(row["scan_y"])): int(row["scanned_at"])
        for row in rows
    }


def shared_map_available_targets(
    sess: dict[str, Any],
    map_kind: str,
    *,
    target_kind: str,
    level: int | list[int] | tuple[int, ...] | set[int] | None,
    drops: list[str],
    composition_filter: dict[str, Any],
    max_age_ms: int = SHARED_MAP_TARGET_TTL_MS,
    max_results: int | None = None,
    center_x: int | None = None,
    center_y: int | None = None,
) -> list[dict[str, Any]]:
    server_key = shared_map_server_key(sess)
    if not server_key:
        return []
    at_ms = now_ms()
    if map_kind == "bandit":
        where_parts = [
            "target.server_key=?",
            """
            (
                target.status='available'
                OR (
                    target.status='reserved'
                    AND target.lease_until<=?
                )
            )
            """,
            "target.last_seen_at>=?",
        ]
        params: list[Any] = [server_key, at_ms, at_ms - int(max_age_ms)]
        if str(target_kind or ""):
            where_parts.append("instr(target.kind, ?) > 0")
            params.append(str(target_kind))
        levels = normalize_brush_levels(
            level if isinstance(level, (list, tuple, set)) else None,
            None if isinstance(level, (list, tuple, set)) else level,
        )
        if levels:
            where_parts.append(
                "target.level IN (" + ",".join("?" for _ in levels) + ")"
            )
            params.extend(levels)
        drop_keywords = normalize_drop_keywords(drops)
        if drop_keywords and set(drop_keywords) != {
            "宝物", "资源", "装备", "宝箱",
        }:
            drop_mask = sum(DROP_CATEGORY_BITS.get(value, 0) for value in drop_keywords)
            if drop_mask:
                where_parts.append("(target.drop_mask & ?) <> 0")
                params.append(drop_mask)
        if composition_filter:
            where_parts.extend([
                "target.foot_count<=?",
                "target.bow_count<=?",
                "target.cavalry_count<=?",
                "target.chariot_count<=?",
            ])
            params.extend([
                int(composition_filter.get("maxFoot", 9)),
                int(composition_filter.get("maxBow", 9)),
                int(composition_filter.get("maxCavalry", 9)),
                int(composition_filter.get("maxChariot", 9)),
            ])
            if composition_filter.get("requireFoot"):
                where_parts.append("target.foot_count>0")
        suffix = "WHERE " + " AND ".join(where_parts)
        if center_x is not None and center_y is not None:
            suffix += (
                " ORDER BY "
                "((target.x-?)*(target.x-?)+(target.y-?)*(target.y-?)), "
                "target.x, target.y, target.target_id_hex"
            )
            params.extend([
                int(center_x), int(center_x), int(center_y), int(center_y),
            ])
        if max_results is not None:
            suffix += " LIMIT ?"
            params.append(max(1, int(max_results)))
        with _bandit_db_connect() as connection:
            cleanup_shared_map_if_due(connection, "bandit", at_ms)
            rows = connection.execute(
                _bandit_target_select_sql(suffix),
                params,
            ).fetchall()
        available = []
        for row in rows:
            target = _bandit_target_from_row(row)
            if not target_matches_search_filter(
                target,
                target_kind,
                level,
                drops,
                composition_filter,
            ):
                continue
            available.append({
                **target,
                "sharedTargetKey": f"id:{target['idHex']}",
                "fromSharedMap": True,
                "fromCache": True,
            })
        return dedupe_targets(available)
    changed = False
    available: list[dict[str, Any]] = []
    with SHARED_MAP_LOCK:
        shared_map = _load_shared_map_locked(server_key, map_kind)
        changed = _cleanup_shared_map_leases_locked(shared_map, at_ms)
        for target_key, record in shared_map.get("targets", {}).items():
            if not isinstance(record, dict):
                continue
            if str(record.get("status") or "") != "available":
                continue
            if at_ms - int(record.get("lastSeenAt") or 0) >= max_age_ms:
                continue
            target = record.get("target")
            if not isinstance(target, dict):
                continue
            if not target_matches_search_filter(
                target,
                target_kind,
                level,
                drops,
                composition_filter,
            ):
                continue
            available.append({
                **target,
                "sharedTargetKey": target_key,
                "fromSharedMap": True,
                "fromCache": True,
            })
        if changed:
            _persist_shared_map_locked(shared_map)
    return dedupe_targets(available)


def mine_target_matches(
    target: dict[str, Any],
    *,
    resource_types: list[str] | None = None,
    levels: list[int] | None = None,
    only_empty: bool = False,
    only_defended: bool = False,
    allow_player_occupied: bool = False,
    exact_x: int | None = None,
    exact_y: int | None = None,
) -> bool:
    return shared_mine_target_matches(
        target,
        resource_types=resource_types,
        levels=levels,
        only_empty=only_empty,
        only_defended=only_defended,
        allow_player_occupied=allow_player_occupied,
        exact_x=exact_x,
        exact_y=exact_y,
    )


def shared_map_available_mine_targets(
    sess: dict[str, Any],
    *,
    resource_types: list[str] | None = None,
    levels: list[int] | None = None,
    only_empty: bool = False,
    only_defended: bool = False,
    allow_player_occupied: bool = False,
    exact_x: int | None = None,
    exact_y: int | None = None,
    max_age_ms: int = MINE_MAP_TARGET_TTL_MS,
) -> list[dict[str, Any]]:
    server_key = shared_map_server_key(sess)
    if not server_key:
        return []
    at_ms = now_ms()
    with _bandit_db_connect() as connection:
        cleanup_shared_map_if_due(connection, "mine", at_ms)
        rows = connection.execute(
            _mine_target_select_sql(
                """
                WHERE target.server_key=?
                  AND (
                      target.status='available'
                      OR (
                          target.status='reserved'
                          AND target.lease_until<=?
                      )
                  )
                  AND target.last_seen_at>=?
                """
            ),
            (server_key, at_ms, at_ms - int(max_age_ms)),
        ).fetchall()
    available: list[dict[str, Any]] = []
    for row in rows:
        target = _mine_target_from_row(row)
        if not mine_target_matches(
                target,
                resource_types=resource_types,
                levels=levels,
                only_empty=only_empty,
                only_defended=only_defended,
                allow_player_occupied=allow_player_occupied,
                exact_x=exact_x,
                exact_y=exact_y,
        ):
            continue
        available.append({
            **target,
            "sharedTargetKey": f"id:{target['idHex']}",
            "fromSharedMap": True,
            "fromCache": True,
        })
    return dedupe_targets(available)


def claim_shared_map_scan(
    sess: dict[str, Any],
    map_kind: str,
    coord_key: str,
    owner: str,
) -> bool:
    server_key = shared_map_server_key(sess)
    if not server_key:
        return True
    at_ms = now_ms()
    if map_kind in {"bandit", "mine"}:
        try:
            scan_x, scan_y = [int(value) for value in str(coord_key).split(",", 1)]
        except Exception:
            return False
        prefix = "bandit" if map_kind == "bandit" else "mine"
        with _bandit_db_connect() as connection:
            cleanup_shared_map_if_due(connection, map_kind, at_ms)
            connection.execute("BEGIN IMMEDIATE")
            try:
                cursor = connection.execute(
                    f"""
                    INSERT INTO {prefix}_scan_leases(
                        server_key, scan_x, scan_y, owner, lease_until
                    ) VALUES(?, ?, ?, ?, ?)
                    ON CONFLICT(server_key, scan_x, scan_y) DO UPDATE SET
                        owner=excluded.owner,
                        lease_until=excluded.lease_until
                    WHERE {prefix}_scan_leases.owner=excluded.owner
                       OR {prefix}_scan_leases.lease_until<=?
                    """,
                    (
                        server_key, scan_x, scan_y, owner,
                        at_ms + SHARED_MAP_SCAN_LEASE_MS,
                        at_ms,
                    ),
                )
                claimed = cursor.rowcount == 1
                connection.execute("COMMIT")
                return claimed
            except Exception:
                connection.execute("ROLLBACK")
                raise
    with SHARED_MAP_LOCK:
        shared_map = _load_shared_map_locked(server_key, map_kind)
        changed = _cleanup_shared_map_leases_locked(shared_map, at_ms)
        current = shared_map.setdefault("scanLeases", {}).get(coord_key)
        if (
            isinstance(current, dict)
            and str(current.get("owner") or "") != owner
            and int(current.get("leaseUntil") or 0) > at_ms
        ):
            if changed:
                _persist_shared_map_locked(shared_map)
            return False
        shared_map["scanLeases"][coord_key] = {
            "owner": owner,
            "claimedAt": at_ms,
            "leaseUntil": at_ms + SHARED_MAP_SCAN_LEASE_MS,
        }
        _persist_shared_map_locked(shared_map)
        return True


def release_shared_map_scan(
    sess: dict[str, Any],
    map_kind: str,
    coord_key: str,
    owner: str,
) -> None:
    server_key = shared_map_server_key(sess)
    if not server_key:
        return
    if map_kind in {"bandit", "mine"}:
        try:
            scan_x, scan_y = [int(value) for value in str(coord_key).split(",", 1)]
        except Exception:
            return
        prefix = "bandit" if map_kind == "bandit" else "mine"
        with _bandit_db_connect() as connection:
            connection.execute(
                f"""
                DELETE FROM {prefix}_scan_leases
                WHERE server_key=? AND scan_x=? AND scan_y=? AND owner=?
                """,
                (server_key, scan_x, scan_y, owner),
            )
        return
    with SHARED_MAP_LOCK:
        shared_map = _load_shared_map_locked(server_key, map_kind)
        current = shared_map.setdefault("scanLeases", {}).get(coord_key)
        if isinstance(current, dict) and str(current.get("owner") or "") == owner:
            shared_map["scanLeases"].pop(coord_key, None)
            _persist_shared_map_locked(shared_map)


def record_shared_map_region(
    sess: dict[str, Any],
    map_kind: str,
    *,
    x: int,
    y: int,
    http_code: int,
    opcodes: list[str],
    response_data: bytes,
    response_payloads: list[bytes],
    targets: list[dict[str, Any]],
    replace_region: bool = True,
    scanned_at_millis: int | None = None,
) -> dict[str, Any] | None:
    server_key = shared_map_server_key(sess)
    if not server_key:
        return None
    scanned_at = (
        now_ms()
        if scanned_at_millis is None
        else max(1, int(scanned_at_millis))
    )
    coord_key = f"{int(x)},{int(y)}"
    normalized_targets: list[dict[str, Any]] = []
    for target in targets:
        normalized = (
            compact_bandit_target(target, int(x), int(y))
            if map_kind == "bandit"
            else {**target, "scanCoord": [int(x), int(y)]}
        )
        normalized["sharedTargetKey"] = shared_map_target_key(normalized)
        normalized_targets.append(normalized)
    new_keys = {target["sharedTargetKey"] for target in normalized_targets}
    if map_kind == "bandit":
        new_ids = {
            normalize_bandit_target_id(target)
            for target in normalized_targets
            if normalize_bandit_target_id(target)
        }
        with _bandit_db_connect() as connection:
            cleanup_shared_map_if_due(connection, "bandit", scanned_at)
            connection.execute("BEGIN IMMEDIATE")
            try:
                old_ids = {
                    str(row["target_id_hex"])
                    for row in connection.execute(
                        """
                        SELECT target_id_hex FROM bandit_target_regions
                        WHERE server_key=? AND scan_x=? AND scan_y=?
                        """,
                        (server_key, int(x), int(y)),
                    ).fetchall()
                }
                connection.execute(
                    """
                    INSERT INTO bandit_regions(server_key, scan_x, scan_y, scanned_at)
                    VALUES(?, ?, ?, ?)
                    ON CONFLICT(server_key, scan_x, scan_y)
                    DO UPDATE SET scanned_at=excluded.scanned_at
                    """,
                    (server_key, int(x), int(y), scanned_at),
                )
                for target in normalized_targets:
                    target_id = normalize_bandit_target_id(target)
                    if not target_id:
                        continue
                    composition = target.get("composition") or {}
                    connection.execute(
                        """
                        INSERT INTO bandit_targets(
                            server_key, target_id_hex, name, kind, level, x, y,
                            reward_text, drop_mask, loot_ids_json, unit_types_json,
                            foot_count, bow_count, cavalry_count, chariot_count,
                            last_seen_at
                        ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        ON CONFLICT(server_key, target_id_hex) DO UPDATE SET
                            name=excluded.name,
                            kind=excluded.kind,
                            level=excluded.level,
                            x=excluded.x,
                            y=excluded.y,
                            reward_text=excluded.reward_text,
                            drop_mask=excluded.drop_mask,
                            loot_ids_json=excluded.loot_ids_json,
                            unit_types_json=excluded.unit_types_json,
                            foot_count=excluded.foot_count,
                            bow_count=excluded.bow_count,
                            cavalry_count=excluded.cavalry_count,
                            chariot_count=excluded.chariot_count,
                            last_seen_at=excluded.last_seen_at
                        """,
                        (
                            server_key, target_id,
                            str(target.get("name") or "山贼"),
                            str(target.get("kind") or "山贼"),
                            int(target.get("level") or 0),
                            int(target.get("x") or 0),
                            int(target.get("y") or 0),
                            str(target.get("resource") or ""),
                            bandit_drop_mask(
                                target.get("dropCategories"),
                                target.get("resource"),
                            ),
                            json.dumps(
                                target.get("lootIds") or [],
                                separators=(",", ":"),
                            ),
                            json.dumps(
                                [
                                    int(unit.get("soldierTypeCode", -1))
                                    for unit in target.get("units") or []
                                    if int(unit.get("soldierTypeCode", -1)) >= 0
                                ],
                                separators=(",", ":"),
                            ),
                            int(composition.get("foot") or 0),
                            int(composition.get("bow") or 0),
                            int(composition.get("cavalry") or 0),
                            int(composition.get("chariot") or 0),
                            scanned_at,
                        ),
                    )
                    connection.execute(
                        """
                        INSERT INTO bandit_target_regions(
                            server_key, target_id_hex, scan_x, scan_y, last_seen_at
                        ) VALUES(?, ?, ?, ?, ?)
                        ON CONFLICT(
                            server_key, target_id_hex, scan_x, scan_y
                        ) DO UPDATE SET last_seen_at=excluded.last_seen_at
                        """,
                        (server_key, target_id, int(x), int(y), scanned_at),
                    )
                removed_ids = old_ids - new_ids if replace_region else set()
                if removed_ids:
                    placeholders = ",".join("?" for _ in removed_ids)
                    connection.execute(
                        f"""
                        DELETE FROM bandit_target_regions
                        WHERE server_key=? AND scan_x=? AND scan_y=?
                          AND target_id_hex IN ({placeholders})
                        """,
                        (server_key, int(x), int(y), *sorted(removed_ids)),
                    )
                    connection.execute(
                        """
                        DELETE FROM bandit_targets
                        WHERE server_key=?
                          AND NOT EXISTS (
                              SELECT 1 FROM bandit_target_regions relation
                              WHERE relation.server_key=bandit_targets.server_key
                                AND relation.target_id_hex=bandit_targets.target_id_hex
                          )
                        """,
                        (server_key,),
                    )
                connection.execute("COMMIT")
            except Exception:
                connection.execute("ROLLBACK")
                raise
        added_ids = sorted(new_ids - old_ids)
        removed_ids = sorted(old_ids - new_ids) if replace_region else []
        return {
            "scannedAt": scanned_at,
            "targetKeys": [f"id:{target_id}" for target_id in sorted(new_ids)],
            "diff": {
                "added": [f"id:{target_id}" for target_id in added_ids],
                "removed": [f"id:{target_id}" for target_id in removed_ids],
                "retainedCount": len(new_ids & old_ids),
            },
        }
    if map_kind == "mine":
        new_ids = {
            normalize_bandit_target_id(target)
            for target in normalized_targets
            if normalize_bandit_target_id(target)
        }
        with _bandit_db_connect() as connection:
            cleanup_shared_map_if_due(connection, "mine", scanned_at)
            connection.execute("BEGIN IMMEDIATE")
            try:
                old_ids = {
                    str(row["target_id_hex"])
                    for row in connection.execute(
                        """
                        SELECT target_id_hex FROM mine_target_regions
                        WHERE server_key=? AND scan_x=? AND scan_y=?
                        """,
                        (server_key, int(x), int(y)),
                    ).fetchall()
                }
                connection.execute(
                    """
                    INSERT INTO mine_regions(server_key, scan_x, scan_y, scanned_at)
                    VALUES(?, ?, ?, ?)
                    ON CONFLICT(server_key, scan_x, scan_y)
                    DO UPDATE SET scanned_at=excluded.scanned_at
                    """,
                    (server_key, int(x), int(y), scanned_at),
                )
                for target in normalized_targets:
                    target_id = _mine_upsert_target(
                        connection, server_key, target, scanned_at
                    )
                    if not target_id:
                        continue
                    connection.execute(
                        """
                        INSERT INTO mine_target_regions(
                            server_key, target_id_hex, scan_x, scan_y, last_seen_at
                        ) VALUES(?, ?, ?, ?, ?)
                        ON CONFLICT(
                            server_key, target_id_hex, scan_x, scan_y
                        ) DO UPDATE SET last_seen_at=excluded.last_seen_at
                        """,
                        (server_key, target_id, int(x), int(y), scanned_at),
                    )
                removed_ids = old_ids - new_ids if replace_region else set()
                if removed_ids:
                    placeholders = ",".join("?" for _ in removed_ids)
                    connection.execute(
                        f"""
                        DELETE FROM mine_target_regions
                        WHERE server_key=? AND scan_x=? AND scan_y=?
                          AND target_id_hex IN ({placeholders})
                        """,
                        (server_key, int(x), int(y), *sorted(removed_ids)),
                    )
                    connection.execute(
                        """
                        DELETE FROM mine_targets
                        WHERE server_key=?
                          AND NOT EXISTS (
                              SELECT 1 FROM mine_target_regions relation
                              WHERE relation.server_key=mine_targets.server_key
                                AND relation.target_id_hex=mine_targets.target_id_hex
                          )
                        """,
                        (server_key,),
                    )
                connection.execute("COMMIT")
            except Exception:
                connection.execute("ROLLBACK")
                raise
        added_ids = sorted(new_ids - old_ids)
        removed_ids = sorted(old_ids - new_ids) if replace_region else []
        return {
            "scannedAt": scanned_at,
            "targetKeys": [f"id:{target_id}" for target_id in sorted(new_ids)],
            "diff": {
                "added": [f"id:{target_id}" for target_id in added_ids],
                "removed": [f"id:{target_id}" for target_id in removed_ids],
                "retainedCount": len(new_ids & old_ids),
            },
        }
    with SHARED_MAP_LOCK:
        shared_map = _load_shared_map_locked(server_key, map_kind)
        _cleanup_shared_map_leases_locked(shared_map, scanned_at)
        regions = shared_map.setdefault("regions", {})
        previous = regions.get(coord_key)
        old_keys = set(previous.get("targetKeys") or []) if isinstance(previous, dict) else set()
        added_keys = sorted(new_keys - old_keys)
        removed_keys = sorted(old_keys - new_keys)
        retained_keys = sorted(new_keys & old_keys)
        records = shared_map.setdefault("targets", {})
        for target_key in removed_keys:
            record = records.get(target_key)
            if not isinstance(record, dict):
                continue
            seen_in = record.setdefault("seenIn", {})
            seen_in.pop(coord_key, None)
            if not seen_in:
                records.pop(target_key, None)
        for target in normalized_targets:
            target_key = str(target["sharedTargetKey"])
            record = records.get(target_key)
            if not isinstance(record, dict):
                record = {
                    "key": target_key,
                    "status": "available",
                    "seenIn": {},
                }
                records[target_key] = record
            stored_target = dict(target)
            stored_target.pop("sharedTargetKey", None)
            record["target"] = json_safe(stored_target)
            record["lastSeenAt"] = scanned_at
            record.setdefault("seenIn", {})[coord_key] = scanned_at
        regions[coord_key] = {
            "scannedAt": scanned_at,
            "targetKeys": sorted(new_keys),
        }
        _persist_shared_map_locked(shared_map)
        return {
            **dict(regions[coord_key]),
            "diff": {
                "added": added_keys,
                "removed": removed_keys,
                "retainedCount": len(retained_keys),
            },
        }


def _shared_snapshot_target(row: dict[str, Any]) -> dict[str, Any]:
    fields = dict(row.get("filterFields") or {})
    target: dict[str, Any] = {
        "id": int(row.get("targetId") or 0),
        "x": int(row.get("x") or 0),
        "y": int(row.get("y") or 0),
        "kind": str(row.get("type") or fields.get("kind") or ""),
        "type": str(row.get("type") or fields.get("kind") or ""),
        "level": int(row.get("level") or fields.get("level") or 0),
        "scanCoord": [
            int(row.get("scanX", row.get("x") or 0)),
            int(row.get("scanY", row.get("y") or 0)),
        ],
    }
    integer_fields = {
        "businessId", "typeCode", "rank", "amountA", "amountB",
        "storage", "productionPerHour", "defenderCount",
    }
    boolean_fields = {
        "playerOccupied", "unoccupiedByPlayer", "isEmpty", "occupied",
        "hasDefenders",
    }
    list_fields = {"dropCategories", "lootIds"}
    for key, raw in fields.items():
        if key in list_fields:
            try:
                value = json.loads(str(raw))
            except (TypeError, ValueError, json.JSONDecodeError):
                value = []
            target[key] = value if isinstance(value, list) else []
        elif key in integer_fields:
            try:
                target[key] = int(raw)
            except (TypeError, ValueError):
                continue
        elif key in boolean_fields:
            target[key] = str(raw).strip().lower() in {"1", "true", "yes"}
        else:
            target[key] = str(raw)
    composition_code = str(target.get("compositionCode") or "")
    if len(composition_code) >= 4 and composition_code[:4].isdigit():
        target["composition"] = {
            name: int(composition_code[index])
            for index, name in enumerate(("foot", "bow", "cavalry", "chariot"))
        }
        target["composition"]["source"] = "8540-units"
    mine_type = str(target.get("resource") or target.get("kind") or "")
    target["mineType"] = mine_type
    target["sharedTargetKey"] = f"id:{normalize_bandit_target_id(target)}"
    return target


def persist_shared_core_map_snapshot(snapshot: dict[str, Any]) -> None:
    """Project a Python-owned query snapshot into the existing desktop map DB."""

    account_ref = str(snapshot.get("accountRef") or "").strip()
    sess = (globals().get("SESSIONS") or {}).get(account_ref)
    if not isinstance(sess, dict):
        raise RuntimeError("地图快照账号未登录")
    map_kind = str(snapshot.get("kind") or "").strip().lower()
    if map_kind not in {"bandit", "mine"}:
        raise ValueError(f"地图快照类型无效：{map_kind}")
    scanned_at = max(1, int(snapshot.get("scannedAtMillis") or now_ms()))
    grouped: dict[tuple[int, int], list[dict[str, Any]]] = {}
    for raw in snapshot.get("targets") or []:
        if not isinstance(raw, dict):
            continue
        target = _shared_snapshot_target(raw)
        if int(target.get("id") or 0) <= 0:
            continue
        scan_coord = target.get("scanCoord") or [target["x"], target["y"]]
        grouped.setdefault(
            (int(scan_coord[0]), int(scan_coord[1])),
            [],
        ).append(target)
    if not grouped:
        center = str(snapshot.get("fingerprint") or "").split("|", 1)[0]
        try:
            center_x, center_y = [int(value) for value in center.split(",", 1)]
        except (TypeError, ValueError):
            return
        grouped[(center_x, center_y)] = []
    for (scan_x, scan_y), targets in grouped.items():
        record_shared_map_region(
            sess,
            map_kind,
            x=scan_x,
            y=scan_y,
            http_code=200,
            opcodes=[],
            response_data=b"",
            response_payloads=[],
            targets=targets,
            # A query snapshot is already filtered.  It may add/update matches,
            # but absence from this filtered view cannot invalidate other rows.
            replace_region=False,
            scanned_at_millis=scanned_at,
        )


def invalidate_shared_core_map_target(
    account_ref: str,
    kind: str,
    target_id: int,
    reason: str,
    _invalidated_at_millis: int,
) -> None:
    sess = (globals().get("SESSIONS") or {}).get(str(account_ref))
    if not isinstance(sess, dict):
        raise RuntimeError("地图失效账号未登录")
    map_kind = str(kind or "").strip().lower()
    if map_kind not in {"bandit", "mine"}:
        raise ValueError(f"地图失效类型无效：{map_kind}")
    update_shared_map_target_status(
        sess,
        map_kind,
        {"id": int(target_id)},
        owner="",
        status="missing",
        reason=str(reason or "shared-core-invalidated"),
    )


def reserve_shared_map_target(
    sess: dict[str, Any],
    map_kind: str,
    target: dict[str, Any],
    *,
    owner: str,
    task_id: str,
) -> bool:
    server_key = shared_map_server_key(sess)
    if not server_key:
        return True
    target_key = str(target.get("sharedTargetKey") or shared_map_target_key(target))
    at_ms = now_ms()
    if map_kind in {"bandit", "mine"}:
        target_id = normalize_bandit_target_id(target_key)
        if not target_id:
            return False
        prefix = "bandit" if map_kind == "bandit" else "mine"
        ttl_ms = (
            SHARED_MAP_TARGET_TTL_MS
            if map_kind == "bandit"
            else MINE_MAP_TARGET_TTL_MS
        )
        with _bandit_db_connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            try:
                (
                    _bandit_cleanup_sql(connection, at_ms)
                    if map_kind == "bandit"
                    else _mine_cleanup_sql(connection, at_ms)
                )
                cursor = connection.execute(
                    f"""
                    UPDATE {prefix}_targets
                    SET status='reserved', reserved_by=?, reserved_task_id=?,
                        lease_until=?, retry_after=0, status_reason='',
                        status_at=?
                    WHERE server_key=? AND target_id_hex=?
                      AND status='available'
                      AND last_seen_at>=?
                    """,
                    (
                        owner, task_id,
                        at_ms + SHARED_MAP_TARGET_LEASE_MS,
                        at_ms, server_key, target_id,
                        at_ms - ttl_ms,
                    ),
                )
                reserved = cursor.rowcount == 1
                connection.execute("COMMIT")
                return reserved
            except Exception:
                connection.execute("ROLLBACK")
                raise
    with SHARED_MAP_LOCK:
        shared_map = _load_shared_map_locked(server_key, map_kind)
        _cleanup_shared_map_leases_locked(shared_map, at_ms)
        record = shared_map.setdefault("targets", {}).get(target_key)
        if not isinstance(record, dict):
            return False
        if str(record.get("status") or "") != "available":
            return False
        record["status"] = "reserved"
        record["reservedBy"] = owner
        record["reservedTaskId"] = task_id
        record["reservedAt"] = at_ms
        record["leaseUntil"] = at_ms + SHARED_MAP_TARGET_LEASE_MS
        _persist_shared_map_locked(shared_map)
        return True


def update_shared_map_target_status(
    sess: dict[str, Any],
    map_kind: str,
    target: dict[str, Any],
    *,
    owner: str,
    status: str,
    reason: str = "",
) -> None:
    server_key = shared_map_server_key(sess)
    if not server_key:
        return
    target_key = str(target.get("sharedTargetKey") or shared_map_target_key(target))
    at_ms = now_ms()
    if map_kind in {"bandit", "mine"}:
        target_id = normalize_bandit_target_id(target_key)
        if not target_id:
            return
        prefix = "bandit" if map_kind == "bandit" else "mine"
        retry_after = (
            at_ms + SHARED_MAP_REJECT_COOLDOWN_MS
            if status == "rejected"
            else 0
        )
        with _bandit_db_connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            try:
                (
                    _bandit_cleanup_sql(connection, at_ms)
                    if map_kind == "bandit"
                    else _mine_cleanup_sql(connection, at_ms)
                )
                connection.execute(
                    f"""
                    UPDATE {prefix}_targets
                    SET status=?, status_at=?, status_reason=?,
                        reserved_by='', reserved_task_id='', lease_until=0,
                        retry_after=?
                    WHERE server_key=? AND target_id_hex=?
                      AND (reserved_by='' OR reserved_by=?)
                    """,
                    (
                        status, at_ms, str(reason or "")[:300],
                        retry_after, server_key, target_id, owner,
                    ),
                )
                connection.execute("COMMIT")
            except Exception:
                connection.execute("ROLLBACK")
                raise
        return
    with SHARED_MAP_LOCK:
        shared_map = _load_shared_map_locked(server_key, map_kind)
        record = shared_map.setdefault("targets", {}).get(target_key)
        if not isinstance(record, dict):
            return
        reserved_by = str(record.get("reservedBy") or "")
        if reserved_by and reserved_by != owner:
            return
        next_status = status
        if status == "available" and not record.get("seenIn"):
            shared_map.setdefault("targets", {}).pop(target_key, None)
            _persist_shared_map_locked(shared_map)
            return
        record["status"] = next_status
        record["statusAt"] = at_ms
        record["statusReason"] = str(reason or "")[:300]
        record["reservedBy"] = ""
        record["reservedTaskId"] = ""
        record["leaseUntil"] = 0
        if status == "dispatched":
            record["dispatchedAt"] = at_ms
            record["dispatchedBy"] = owner
        if status == "rejected":
            record["retryAfter"] = at_ms + SHARED_MAP_REJECT_COOLDOWN_MS
        elif status != "rejected":
            record["retryAfter"] = 0
        _persist_shared_map_locked(shared_map)


def _account_state_db_connect() -> sqlite3.Connection:
    path_key = str(Path(ACCOUNT_STATE_DB_FILE).resolve())
    cached = getattr(SQLITE_THREAD_LOCAL, "account_state_connection", None)
    cached_path = getattr(SQLITE_THREAD_LOCAL, "account_state_connection_path", "")
    if cached is not None and cached_path == path_key:
        return cached
    if cached is not None:
        try:
            cached.close()
        except sqlite3.Error:
            pass
    connection = sqlite3.connect(ACCOUNT_STATE_DB_FILE, timeout=30)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA busy_timeout=30000")
    connection.execute("PRAGMA foreign_keys=ON")
    # This is a local cache/state store in WAL mode. NORMAL avoids forcing a
    # disk sync for every high-frequency task log while retaining WAL recovery.
    connection.execute("PRAGMA synchronous=NORMAL")
    SQLITE_THREAD_LOCAL.account_state_connection = connection
    SQLITE_THREAD_LOCAL.account_state_connection_path = path_key
    return connection


def mine_candidate_target_count() -> int:
    """Global low-frequency mine-map waterline configured from dashboard."""
    if not ACCOUNT_STATE_DB_READY:
        return DEFAULT_MINE_CANDIDATE_TARGET_COUNT
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        row = connection.execute(
            "SELECT value FROM storage_meta WHERE key='mine_candidate_target_count'"
        ).fetchone()
    try:
        return max(1, min(20, int(row["value"]))) if row else DEFAULT_MINE_CANDIDATE_TARGET_COUNT
    except (TypeError, ValueError):
        return DEFAULT_MINE_CANDIDATE_TARGET_COUNT


def save_mine_candidate_target_count(value: Any) -> int:
    count = max(1, min(20, int(value or DEFAULT_MINE_CANDIDATE_TARGET_COUNT)))
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute(
            """
            INSERT INTO storage_meta(key, value, updated_at)
            VALUES('mine_candidate_target_count', ?, ?)
            ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at
            """,
            (str(count), now_ms()),
        )
        connection.commit()
    return count


def _account_record_identity_key(record: dict[str, Any]) -> str:
    return json.dumps(list(account_stable_identity(record)), ensure_ascii=False, separators=(",", ":"))


