def _account_state_schema_v4(connection: sqlite3.Connection) -> None:
    """Namespace the cached area catalog by game platform."""
    columns = {
        str(row[1])
        for row in connection.execute("PRAGMA table_info(area_catalog)").fetchall()
    }
    if not columns:
        connection.execute(
            """
            CREATE TABLE area_catalog (
                platform TEXT NOT NULL,
                server_key TEXT NOT NULL,
                area_id TEXT NOT NULL,
                area_name TEXT NOT NULL,
                target TEXT NOT NULL DEFAULT '',
                server_url TEXT NOT NULL DEFAULT '',
                updated_at INTEGER NOT NULL,
                PRIMARY KEY(platform, server_key, area_id, area_name)
            )
            """
        )
        return
    if "platform" in columns:
        return
    connection.execute("ALTER TABLE area_catalog RENAME TO area_catalog_v3")
    connection.execute(
        """
        CREATE TABLE area_catalog (
            platform TEXT NOT NULL,
            server_key TEXT NOT NULL,
            area_id TEXT NOT NULL,
            area_name TEXT NOT NULL,
            target TEXT NOT NULL DEFAULT '',
            server_url TEXT NOT NULL DEFAULT '',
            updated_at INTEGER NOT NULL,
            PRIMARY KEY(platform, server_key, area_id, area_name)
        )
        """
    )
    connection.execute(
        """
        INSERT INTO area_catalog
            (platform, server_key, area_id, area_name, target, server_url, updated_at)
        SELECT 'sglm', server_key, area_id, area_name, target, server_url, updated_at
        FROM area_catalog_v3
        """
    )
    connection.execute("DROP TABLE area_catalog_v3")


