def _log_row_to_entry(row: sqlite3.Row, *, include_detail: bool = False) -> dict[str, Any]:
    entry = {
        "id": int(row["id"]),
        "time": int(row["time"]),
        "timeText": str(row["time_text"] or ""),
        "level": str(row["level"] or "info"),
        "source": str(row["source"] or ""),
        "sessionId": str(row["session_id"] or ""),
        "accountKey": str(row["account_key"] or ""),
        "message": str(row["message"] or ""),
    }
    if include_detail and row["detail_json"]:
        try:
            entry["detail"] = json.loads(row["detail_json"])
        except Exception:
            pass
    return entry


def _database_insert_system_log(
    connection: sqlite3.Connection,
    entry: dict[str, Any],
) -> None:
    global SYSTEM_LOG_INSERT_COUNT
    connection.execute(
        """
        INSERT INTO system_logs
            (time, time_text, level, source, session_id,
             account_key, message, detail_json)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            int(entry.get("time") or now_ms()),
            str(entry.get("timeText") or ""),
            str(entry.get("level") or "info"),
            str(entry.get("source") or "server"),
            str(entry.get("sessionId") or ""),
            str(entry.get("accountKey") or ""),
            str(entry.get("message") or ""),
            json.dumps(json_safe(entry.get("detail")), ensure_ascii=False)
            if "detail" in entry else None,
        ),
    )
    SYSTEM_LOG_INSERT_COUNT += 1
    if SYSTEM_LOG_INSERT_COUNT >= LOG_TRIM_BATCH_SIZE:
        SYSTEM_LOG_INSERT_COUNT = 0
        connection.execute(
            """
            DELETE FROM system_logs
            WHERE id NOT IN (
                SELECT id FROM system_logs ORDER BY time DESC, id DESC LIMIT ?
            )
            """,
            (SYSTEM_LOG_MAX_LINES,),
        )


def _database_insert_account_log(
    connection: sqlite3.Connection,
    entry: dict[str, Any],
) -> None:
    global ACCOUNT_LOG_INSERT_COUNT
    account_key = str(entry.get("accountKey") or "unknown_account")
    connection.execute(
        """
        INSERT INTO account_logs
            (time, time_text, level, source, session_id,
             account_key, message)
        VALUES (?, ?, ?, ?, ?, ?, ?)
        """,
        (
            int(entry.get("time") or now_ms()),
            str(entry.get("timeText") or ""),
            str(entry.get("level") or "info"),
            str(entry.get("source") or "frontend"),
            str(entry.get("sessionId") or ""),
            account_key,
            str(entry.get("message") or ""),
        ),
    )
    ACCOUNT_LOG_INSERT_COUNT += 1
    if ACCOUNT_LOG_INSERT_COUNT >= LOG_TRIM_BATCH_SIZE:
        ACCOUNT_LOG_INSERT_COUNT = 0
        account_keys = [
            str(row["account_key"])
            for row in connection.execute(
                "SELECT DISTINCT account_key FROM account_logs"
            )
        ]
        for trim_key in account_keys:
            connection.execute(
                """
                DELETE FROM account_logs
                WHERE account_key=? AND id NOT IN (
                    SELECT id FROM account_logs
                    WHERE account_key=?
                    ORDER BY time DESC, id DESC LIMIT ?
                )
                """,
                (trim_key, trim_key, ACCOUNT_LOG_MAX_LINES),
            )


