def database_read_system_logs(limit: int) -> list[dict[str, Any]]:
    if not ACCOUNT_STATE_DB_READY:
        return []
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(
            """
            SELECT id, time, time_text, level, source, session_id,
                   account_key, message, detail_json
            FROM system_logs
            ORDER BY time DESC, id DESC LIMIT ?
            """,
            (max(1, min(int(limit), SYSTEM_LOG_MAX_LINES)),),
        ).fetchall()
    return [_log_row_to_entry(row, include_detail=True) for row in reversed(rows)]


def database_read_system_log_page(
    limit: int,
    *,
    after_id: int | None = None,
) -> tuple[list[dict[str, Any]], int, int]:
    """Read an initial tail or an incremental page using the SQLite row id."""
    if not ACCOUNT_STATE_DB_READY:
        return [], 0, 0
    bounded_limit = max(1, min(int(limit), SYSTEM_LOG_MAX_LINES))
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        latest_row = connection.execute(
            "SELECT COALESCE(MAX(id), 0) AS latest_id FROM system_logs"
        ).fetchone()
        latest_id = int(latest_row["latest_id"] or 0)
        if after_id is None:
            rows = connection.execute(
                """
                SELECT id, time, time_text, level, source, session_id,
                       account_key, message, detail_json
                FROM system_logs
                ORDER BY id DESC LIMIT ?
                """,
                (bounded_limit,),
            ).fetchall()
            rows = list(reversed(rows))
        else:
            rows = connection.execute(
                """
                SELECT id, time, time_text, level, source, session_id,
                       account_key, message, detail_json
                FROM system_logs
                WHERE id > ?
                ORDER BY id ASC LIMIT ?
                """,
                (max(0, int(after_id)), bounded_limit),
            ).fetchall()
    entries = [_log_row_to_entry(row) for row in rows]
    cursor_id = int(rows[-1]["id"]) if rows else max(0, int(after_id or 0))
    return entries, cursor_id, latest_id


