def database_read_success_records(account_key: str, limit: int = 50) -> list[dict[str, Any]]:
    if not ACCOUNT_STATE_DB_READY:
        return []
    bounded = max(1, min(int(limit), 50))
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(
            """
            SELECT id, time, time_text, session_id, account_key,
                   category, message, detail_json
            FROM success_records
            WHERE account_key=?
            ORDER BY time DESC, id DESC LIMIT ?
            """,
            (str(account_key), bounded),
        ).fetchall()
    return [{
        "id": int(row["id"]),
        "time": int(row["time"]),
        "timeText": str(row["time_text"] or ""),
        "sessionId": str(row["session_id"] or ""),
        "accountKey": str(row["account_key"] or ""),
        "category": str(row["category"] or "其他"),
        # 旧版本把客户端“治疗全部”的协议哨兵值 0/-1 直接展示成了
        # “兵种0 -1”。读取时兼容修正，避免升级后最近50条仍显示误导文案。
        "message": (
            "全部伤兵"
            if str(row["category"] or "") == "治疗"
            and str(row["message"] or "").strip() == "兵种0 -1"
            else str(row["message"] or "")
        ),
        "detail": (
            json.loads(row["detail_json"])
            if row["detail_json"] else None
        ),
    } for row in rows]


def database_upsert_important_notice(
    account_key: str,
    notice_key: str,
    *,
    severity: str,
    title: str,
    message: str,
    source: str,
    at_ms: int | None = None,
) -> None:
    if not ACCOUNT_STATE_DB_READY or not str(account_key or "") or not str(notice_key or ""):
        return
    timestamp = int(at_ms or now_ms())
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute(
            """
            INSERT INTO important_notices(
                account_key, notice_key, severity, title, message,
                source, active, created_at, updated_at, resolved_at
            ) VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, NULL)
            ON CONFLICT(account_key, notice_key) DO UPDATE SET
                severity=excluded.severity,
                title=excluded.title,
                message=excluded.message,
                source=excluded.source,
                active=1,
                updated_at=excluded.updated_at,
                resolved_at=NULL
            """,
            (
                str(account_key), str(notice_key), str(severity or "warning"),
                str(title or "重要提示"), str(message or "请查看任务状态"),
                str(source or ""), timestamp, timestamp,
            ),
        )


