def _read_json_file(path: Path) -> Any:
    if not path.exists():
        return None
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


ACCOUNT_SETTINGS_FILENAME = "account_settings.json"
LEGACY_ACCOUNT_SETTINGS_FILENAMES = (
    "last_saved_formations.json",
    "last_saved_config.json",
    "last_saved_military.json",
)


def load_account_settings_payload(
    *,
    sess: dict[str, Any] | None = None,
    acc: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Read the unified account settings, migrating legacy files once."""
    cfg_dir = account_config_dir(sess=sess, acc=acc)
    path = cfg_dir / ACCOUNT_SETTINGS_FILENAME
    account_key = account_storage_key(sess=sess, acc=acc)
    with ACCOUNT_CONFIG_LOCK:
        database_payload = database_load_account_habits(account_key)
        if isinstance(database_payload, dict):
            return database_payload
        payload = _read_json_file(path)
        if isinstance(payload, dict):
            database_save_account_habits(account_key, payload)
            return payload

        formations_payload = _read_json_file(cfg_dir / "last_saved_formations.json") or {}
        config_payload = _read_json_file(cfg_dir / "last_saved_config.json") or {}
        military_payload = _read_json_file(cfg_dir / "last_saved_military.json") or {}
        source = sess or acc or {}
        payload = {
            "time": now_ms(),
            "timeText": local_time_text(),
            "sessionId": source.get("sessionId"),
            "accountKey": account_storage_key(sess=sess, acc=acc),
            "username": source.get("username"),
            "area": source.get("area") or {},
            "formations": formations_payload.get("formations") if isinstance(formations_payload, dict) else [],
            "formationOptions": formations_payload.get("formationOptions") if isinstance(formations_payload, dict) else {"clearOtherGenerals": False},
            "config": config_payload.get("config") if isinstance(config_payload, dict) else None,
            "raid": military_payload.get("raid") if isinstance(military_payload, dict) else None,
            "mine": military_payload.get("mine") if isinstance(military_payload, dict) else None,
            "ministry": None,
            "captives": None,
            "militaryFuture": military_payload.get("militaryFuture") if isinstance(military_payload, dict) else {},
        }
        database_save_account_habits(account_key, payload)
        return payload


def load_account_habits(sess: dict[str, Any]) -> dict[str, Any]:
    """Load per-account saved habits. Key is account+server, not volatile session id."""
    cfg_dir = account_config_dir(sess=sess)
    payload = load_account_settings_payload(sess=sess)
    formations = payload.get("formations")
    formation_options = payload.get("formationOptions")
    config = payload.get("config")
    raid = payload.get("raid")
    mine = payload.get("mine")
    ministry = payload.get("ministry")
    captives = payload.get("captives")
    military_future = payload.get("militaryFuture")
    if isinstance(config, dict):
        config = dict(config)
        config["sessionId"] = sess["sessionId"]
        if isinstance(config.get("brush"), dict):
            config["brush"] = dict(config["brush"])
    return {
        "accountKey": account_storage_key(sess=sess),
        "configDir": str(cfg_dir),
        "formations": formations if isinstance(formations, list) else [],
        "formationOptions": formation_options if isinstance(formation_options, dict) else {"clearOtherGenerals": False},
        "config": config if isinstance(config, dict) else None,
        "raid": raid if isinstance(raid, dict) else None,
        "mine": mine if isinstance(mine, dict) else None,
        "ministry": ministry if isinstance(ministry, dict) else None,
        "captives": captives if isinstance(captives, dict) else None,
        "militaryFuture": military_future if isinstance(military_future, dict) else {},
    }


def apply_account_habits_to_session(sess: dict[str, Any]) -> dict[str, Any]:
    habits = load_account_habits(sess)
    sid = sess["sessionId"]
    if habits.get("formations"):
        try:
            SAVED_FORMATION_RULES[sid] = normalize_formation_rules(
                sess,
                list(habits["formations"] or []),
                require_known=False,
            )
            sess["unresolvedFormationGeneralIds"] = (
                unresolved_saved_general_ids(sess, habits)
            )
        except Exception:
            SAVED_FORMATION_RULES[sid] = list(habits["formations"])
    if habits.get("config"):
        cfg = dict(habits["config"])
        cfg["sessionId"] = sid
        SAVED_CONFIGS[sid] = cfg
    return habits


def save_account_habits(
    sess: dict[str, Any],
    *,
    formations: list[dict[str, Any]] | None = None,
    formation_options: dict[str, Any] | None = None,
    config: dict[str, Any] | None = None,
    raid: dict[str, Any] | None = None,
    mine: dict[str, Any] | None = None,
    ministry: dict[str, Any] | None = None,
    captives: dict[str, Any] | None = None,
    military_future: dict[str, Any] | None = None,
) -> dict[str, Any]:
    saved: dict[str, str] = {}
    with ACCOUNT_CONFIG_LOCK:
        payload = load_account_settings_payload(sess=sess)
        payload = dict(payload) if isinstance(payload, dict) else {}
        if formations is not None:
            payload["formations"] = formations
            payload["formationOptions"] = formation_options or {"clearOtherGenerals": False}
        if config is not None:
            cfg = dict(config)
            cfg["sessionId"] = sess["sessionId"]
            payload["config"] = cfg
        if raid is not None:
            payload["raid"] = raid
        if mine is not None:
            payload["mine"] = mine
        if ministry is not None:
            payload["ministry"] = ministry
        if captives is not None:
            payload["captives"] = captives
        if military_future is not None:
            old_future = payload.get("militaryFuture") if isinstance(payload.get("militaryFuture"), dict) else {}
            next_future = dict(old_future or {})
            next_future.update(military_future)
            payload["militaryFuture"] = next_future
        payload.update({
            "time": now_ms(),
            "timeText": local_time_text(),
            "sessionId": sess["sessionId"],
            "accountKey": account_storage_key(sess=sess),
            "username": sess.get("username"),
            "area": sess.get("area") or {},
        })
        database_save_account_habits(account_storage_key(sess=sess), payload)
    sqlite_uri = f"sqlite://account_habits/{account_storage_key(sess=sess)}"
    if formations is not None:
        saved["formationsFile"] = sqlite_uri
    if config is not None:
        saved["configFile"] = sqlite_uri
    if raid is not None or mine is not None or military_future is not None:
        saved["militaryFile"] = sqlite_uri
    if ministry is not None:
        saved["ministryFile"] = sqlite_uri
    if captives is not None:
        saved["captivesFile"] = sqlite_uri
    saved["settingsFile"] = sqlite_uri
    return saved


def _append_jsonl_limited(path: Path, entry: dict[str, Any], max_lines: int) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    line = json.dumps(json_safe(entry), ensure_ascii=False, separators=(",", ":"))
    with LOG_LOCK:
        with path.open("a", encoding="utf-8") as f:
            f.write(line + "\n")
        try:
            lines = path.read_text(encoding="utf-8").splitlines()
            if len(lines) > max_lines:
                tmp = path.with_name(f"{path.name}.{os.getpid()}.{threading.get_ident()}.tmp")
                tmp.write_text("\n".join(lines[-max_lines:]) + "\n", encoding="utf-8")
                tmp.replace(path)
        except Exception as e:
            print(f"[log] trim failed {path}: {e}")


def read_jsonl_tail(path: Path, limit: int) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    try:
        lines = path.read_text(encoding="utf-8").splitlines()[-max(1, limit):]
    except Exception:
        return []
    out = []
    for line in lines:
        try:
            out.append(json.loads(line))
        except Exception:
            pass
    return out


def clear_system_logs() -> None:
    if not ACCOUNT_STATE_DB_READY:
        return
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        connection.execute("DELETE FROM system_logs")


def system_log(message: str, *, level: str = "info", source: str = "server", session_id: str = "", detail: Any = None) -> None:
    ts = now_ms()
    sid = str(session_id or "")
    entry = {
        "time": ts,
        "timeText": local_time_text(ts),
        "level": level,
        "source": source,
        "sessionId": sid,
        "accountKey": account_storage_key(session_id=sid) if sid else "",
        "message": str(message),
    }
    if detail is not None:
        entry["detail"] = json_safe(detail)
    database_append_system_log(entry)


def record_success_action(
    session_id: str,
    category: str,
    message: str,
    *,
    detail: Any = None,
) -> None:
    sid = str(session_id or "")
    if not sid:
        return
    ts = now_ms()
    database_append_success_record({
        "time": ts,
        "timeText": local_time_text(ts),
        "sessionId": sid,
        "accountKey": account_storage_key(session_id=sid),
        "category": str(category or "其他"),
        "message": re.sub(r"\s+", " ", str(message or "")).strip()[:500],
        "detail": detail,
    })


def success_action_from_log(message: str) -> tuple[str, str] | None:
    """Convert only unambiguous success logs into the compact record feed."""
    text = re.sub(r"\s+", " ", str(message or "")).strip()
    match = re.search(
        r"副本第 \d+ 轮第 (\d+) 条完成：.+? → (.+?第\d+关)，",
        text,
    )
    if match:
        return "副本", f"编队{match.group(1)} > {match.group(2)}"
    match = re.search(
        r"自动加体完成：(.+?) 使用活血丹1个(?:.*?由(\d+)更新为(\d+))?",
        text,
    )
    if match:
        # 加体 and 活血丹使用 are one event; keep both hosts on one category so
        # the history does not split across the 军事 and 政事 tabs.
        detail = f"{match.group(1)}使用1枚活血丹"
        if match.group(2) and match.group(3):
            detail += f"，体力{match.group(2)}→{match.group(3)}"
        return "活血丹", detail
    match = re.search(r"粮食转铜完成：兑换(\d+)铜，消耗粮食(\d+)", text)
    if match:
        return "转铜", f"{match.group(2)}粮换{match.group(1)}铜"
    match = re.search(
        r"治疗伤兵完成：.*?封地=([^；]+?) 范围=全部伤兵(?:；|$)",
        text,
    )
    if match:
        return "治疗", f"{match.group(1)} 全部伤兵"
    match = re.search(
        r"治疗伤兵完成：.*?fief=([^ ]+) 兵种=0 数量=-1(?:；|$)",
        text,
    )
    if match:
        return "治疗", f"封地{match.group(1)} 全部伤兵"
    match = re.search(r"治疗伤兵完成：.*?兵种=([^ ]+) 数量=([^；]+)", text)
    if match:
        soldier_type = match.group(1)
        soldier_text = (
            f"兵种{soldier_type}"
            if re.fullmatch(r"-?\d+", soldier_type)
            else soldier_type
        )
        return "治疗", f"{soldier_text} {match.group(2)}"
    if text.startswith("自动签到完成："):
        return "签到", text.split("：", 1)[1] or "今日签到成功"
    if text.startswith("自动签到后领取每日金钻宝箱：") and "失败" not in text:
        return "签到", "领取每日宝箱成功"
    if text.startswith("领竞技币完成："):
        return "领币", text.split("：", 1)[1] or "领取竞技币成功"
    # 旧版手动/兼容路径：自动捐献完成：44000铜钱、132000粮食
    match = re.search(r"自动捐献完成：(\d+)铜钱、(\d+)粮食", text)
    if match:
        return "捐献", f"捐献成功 {match.group(1)}铜和{match.group(2)}粮"
    # 日常自动化路径：自动捐献完成：自动捐献完成：铜钱成功、粮食成功、科技积分成功
    if text.startswith("自动捐献完成：") and "失败" not in text:
        detail = text.split("：", 1)[1].strip()
        detail = re.sub(r"^(?:自动捐献完成[:：]\s*)+", "", detail).strip() or "捐献成功"
        return "捐献", detail
    # log_daily_feature_result 统一写成「领取俸禄完成：… / 国家征收完成：…」
    if text.startswith("领取俸禄完成："):
        detail = text.split("：", 1)[1].strip() or "领取俸禄成功"
        return "俸禄", detail
    if text.startswith("国家征收完成："):
        detail = text.split("：", 1)[1].strip()
        detail = re.sub(r"^(?:国家征收(?:部分)?完成[:：]\s*)+", "", detail).strip() or "国家征收成功"
        return "国征", detail
    if text.startswith("城主征收完成："):
        detail = text.split("：", 1)[1].strip() or "城主征收成功"
        return "城征", detail
    if text.startswith("名将拜访完成："):
        detail = text.split("：", 1)[1].strip()
        detail = re.sub(r"^(?:名将拜访成功[:：]\s*)+", "", detail).strip() or "名将拜访成功"
        return "拜访", detail
    match = re.search(r"自动开箱成功：(.+)", text)
    if match:
        return "开箱", match.group(1)
    return None


def account_log(session_id: str, message: str, *, level: str = "info", source: str = "frontend", detail: Any = None) -> None:
    sid = str(session_id or "")
    ts = now_ms()
    account_key = account_storage_key(session_id=sid) if sid else "unknown_account"
    concise = re.sub(r"\s+", " ", str(message or "")).strip()
    if len(concise) > 320:
        concise = concise[:317] + "..."
    entry = {
        "time": ts,
        "timeText": local_time_text(ts),
        "level": level,
        "source": source,
        "sessionId": sid,
        "accountKey": account_key,
        "message": concise,
    }
    system_entry = {
        **entry,
        "source": f"account:{source}",
    }
    if detail is not None:
        system_entry["detail"] = json_safe(detail)
    database_append_account_and_system_log(entry, system_entry)
    if str(level or "info") == "info":
        success_action = success_action_from_log(concise)
        if success_action:
            record_success_action(
                sid,
                success_action[0],
                success_action[1],
                detail=detail,
            )


def read_account_log(session_id: str, limit: int = ACCOUNT_LOG_MAX_LINES) -> tuple[str, list[dict[str, Any]]]:
    key = account_storage_key(session_id=session_id) if session_id else "unknown_account"
    return key, database_read_account_logs(key, limit)


def starter_success_records(
    account_id: str,
    account_key: str,
    *,
    limit: int = 50,
) -> list[dict[str, Any]]:
    """Project five-stage deployments into the shared brush/dungeon record feed."""
    if not ACCOUNT_STATE_DB_READY or not account_id:
        return []
    bounded = max(1, min(int(limit), 200))
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(
            """
            SELECT action.id, action.action_type, action.result_json,
                   action.finished_at, action.updated_at
            FROM starter_action_queue AS action
            JOIN starter_jobs AS job ON job.job_id=action.job_id
            WHERE job.account_id=? AND action.status='success'
            ORDER BY COALESCE(action.finished_at, action.updated_at) DESC,
                     action.id DESC
            LIMIT ?
            """,
            (str(account_id), max(50, bounded * 4)),
        ).fetchall()
    records: list[dict[str, Any]] = []
    for row in rows:
        try:
            result = json.loads(str(row["result_json"] or "{}"))
        except json.JSONDecodeError:
            continue
        if not result.get("success"):
            continue
        category = ""
        message = ""
        detail: dict[str, Any] = {
            "starterActionId": int(row["id"]),
            "actionType": str(row["action_type"] or ""),
        }
        target = result.get("target") or {}
        dispatch = result.get("dispatch") or {}
        target_level = int(result.get("targetLevel") or 0)
        if target_level > 0 and target and dispatch.get("success"):
            category = "刷黄"
            general = result.get("general") or {}
            general_name = str(general.get("name") or general.get("id") or "将领")
            target_name = str(target.get("name") or f"{target_level}级山贼")
            coordinate = (
                f"({target.get('x')}，{target.get('y')})"
                if target.get("x") is not None and target.get("y") is not None
                else ""
            )
            message = f"{general_name} > {target_name}{coordinate}"
            detail.update({
                "general": starter_general_ref(general),
                "target": target,
                "targetLevel": target_level,
                "battleId": dispatch.get("successBattleId"),
                "healing": result.get("healing") or {},
            })
        else:
            stage = result.get("stage") or {}
            battle = result.get("battle") or {}
            if (
                stage
                and int(stage.get("stage") or 0) > 0
                and result.get("recordDeployment", True)
                and (
                    battle.get("success")
                    or result.get("settledPendingBattle")
                    or result.get("alreadyCompleted")
                )
            ):
                category = "副本"
                general = result.get("general") or {}
                general_name = str(
                    general.get("name") or general.get("id") or "将领"
                )
                chapter = int(stage.get("chapter") or 0) + 1
                stage_no = int(stage.get("stage") or 0)
                loop_suffix = "循环" if stage.get("loop") else ""
                message = (
                    f"{general_name} > 第{chapter}章第{stage_no}关"
                    f"{loop_suffix}"
                )
                detail.update({
                    "general": starter_general_ref(general),
                    "stage": stage,
                    "battleId": battle.get("battleId"),
                    "healing": result.get("healing") or {},
                })
        if not category:
            continue
        action_time = int(
            (result.get("battle") or {}).get("launchConfirmedAt")
            or (result.get("dispatch") or {}).get("time")
            or row["finished_at"]
            or row["updated_at"]
            or 0
        )
        records.append({
            "id": -int(row["id"]),
            "time": action_time,
            "timeText": local_time_text(action_time),
            "sessionId": str(account_id),
            "accountKey": str(account_key),
            "category": category,
            "message": message,
            "detail": detail,
        })
        if len(records) >= bounded:
            break
    return records


def read_success_records(
    session_id: str,
    limit: int = 50,
    *,
    category: str = "",
) -> tuple[str, list[dict[str, Any]]]:
    key = account_storage_key(session_id=session_id) if session_id else "unknown_account"
    bounded = max(1, min(int(limit), 50))
    entries = [
        *database_read_success_records(key, 50),
        *starter_success_records(session_id, key, limit=50),
    ]
    if category:
        entries = [
            item for item in entries
            if str(item.get("category") or "") == str(category)
        ]
    entries.sort(
        key=lambda item: (int(item.get("time") or 0), int(item.get("id") or 0)),
        reverse=True,
    )
    return key, entries[:bounded]


ACCOUNT_RECORD_FIELDS = (
    "sessionId", "username", "password", "serverQuery", "platform", "serial",
    "displayName", "role", "area", "localOnly", "createdAt", "startedAt",
    "proxyGroup", "proxyNode", "proxyMode", "proxyIp", "proxyStatus",
    "proxyError", "proxyCheckedAt",
)


def normalize_proxy_mode(value: Any) -> str:
    mode = str(value or "auto")
    # HZVPN 的旧模式名为 direct。产品移除该线路后，历史账号迁移为本机直连。
    if mode == "direct":
        return "local"
    return mode if mode in {"auto", "manual", "local"} else "auto"


def migrate_removed_proxy_routes(acc: dict[str, Any]) -> None:
    if str(acc.get("proxyMode") or "") != "direct":
        return
    acc["proxyMode"] = "local"
    acc["proxyGroup"] = ""
    acc["proxyNode"] = ""
    acc["proxyIp"] = ""
    acc["proxyStatus"] = "migrated-local"
    acc["proxyError"] = ""
    acc["proxyCheckedAt"] = None


def account_identity(acc: dict[str, Any]) -> tuple[str, str]:
    username = str(acc.get("username") or "").strip()
    area = acc.get("area") or {}
    server_query = str(acc.get("serverQuery") or (area.get("areaName") if isinstance(area, dict) else "") or "").strip()
    return username, server_query


def account_stable_identity(acc: dict[str, Any]) -> tuple[str, str, str]:
    """Identity used for deduplication; display-name changes must not create a new account."""
    username, server_query = account_identity(acc)
    area = acc.get("area") or {}
    if not isinstance(area, dict):
        area = {}
    area_key = normalized_area_key(
        area.get("serverKey"),
        area.get("areaName"),
        acc.get("serverKey"),
        server_query,
    )
    return record_platform_key(acc), username, area_key


def account_login_identity(acc: dict[str, Any]) -> tuple[str, str]:
    """One platform account has only one valid game session across all servers."""
    username, _server_query = account_identity(acc)
    return record_platform_key(acc), username


def account_record_from_account(acc: dict[str, Any]) -> dict[str, Any]:
    migrate_removed_proxy_routes(acc)
    record = {k: json_safe(acc.get(k)) for k in ACCOUNT_RECORD_FIELDS if acc.get(k) not in (None, "")}
    record["platform"] = platform_display_name(acc.get("platform"))
    username, server_query = account_identity(acc)
    if username and "username" not in record:
        record["username"] = username
    if server_query and "serverQuery" not in record:
        record["serverQuery"] = server_query
    if "area" not in record and server_query:
        record["area"] = {"areaName": server_query}
    if "displayName" not in record and username:
        record["displayName"] = f"{username}@{server_query}"
    return record


def write_account_records_file(
    accounts: list[dict[str, Any]] | None = None,
    *,
    preserve_missing: bool = True,
) -> None:
    """Persist the account ledger in SQLite without erasing missing accounts."""
    global ACCOUNT_RECORDS_LAST_SERIALIZED
    try:
        if accounts is None:
            with ACCOUNT_LOCK:
                records = [account_record_from_account(acc) for acc in ACCOUNTS.values()]
        else:
            records = [account_record_from_account(acc) for acc in accounts]
        records = [r for r in records if str(r.get("username") or "").strip()]
        # runtime_state 的旧版本可能没有保存密码。重写账号文件前，从现有账号记录
        # 回填登录凭据，避免一次服务重启把仍然有效的密码覆盖成空值。
        existing_records: list[dict[str, Any]] = database_account_records()
        existing_by_identity = {
            account_stable_identity(record): record
            for record in existing_records
            if isinstance(record, dict) and account_identity(record)[0]
        }
        for record in records:
            old = existing_by_identity.get(account_stable_identity(record)) or {}
            for field in ("password", "platform", "serial"):
                if record.get(field) in (None, "") and old.get(field) not in (None, ""):
                    record[field] = old[field]
        if preserve_missing:
            current_identities = {
                account_stable_identity(record)
                for record in records
                if account_identity(record)[0]
            }
            for old in existing_records:
                if not isinstance(old, dict):
                    continue
                identity = account_stable_identity(old)
                if identity[1] and identity not in current_identities:
                    records.append(dict(old))
                    current_identities.add(identity)
        # Prefer the live/current record when legacy display-name variants collapse
        # to the same real game account.
        unique_records: dict[tuple[str, str, str], dict[str, Any]] = {}
        for record in records:
            identity = account_stable_identity(record)
            if identity[1]:
                unique_records.setdefault(identity, record)
        records = list(unique_records.values())
        records.sort(key=lambda x: int(x.get("createdAt") or 0))
        serialized = json.dumps(
            json_safe(records),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        cache_key = f"{ACCOUNT_STATE_DB_FILE.resolve()}\0{serialized}"
        if cache_key == ACCOUNT_RECORDS_LAST_SERIALIZED:
            return
        database_upsert_account_records(records)
        ACCOUNT_RECORDS_LAST_SERIALIZED = cache_key
    except Exception as e:
        print(f"[account-records] 保存失败：{e}")


def remove_account_record(acc: dict[str, Any] | None) -> None:
    identity = account_stable_identity(acc or {})
    if not identity[1]:
        return
    database_delete_account_record(identity)


def merge_account_records(records: list[dict[str, Any]]) -> None:
    """Merge stored account records into ACCOUNTS without overwriting live status/session data."""
    for raw in records or []:
        rec = dict(raw or {})
        migrate_removed_proxy_routes(rec)
        username, server_query = account_identity(rec)
        if not username:
            continue
        sid = str(rec.get("sessionId") or "")
        existing_key = None
        if sid and sid in ACCOUNTS:
            existing_key = sid
        if existing_key is None:
            for k, v in ACCOUNTS.items():
                if account_stable_identity(v) == account_stable_identity(rec):
                    existing_key = k
                    break
        if existing_key is not None:
            acc = ACCOUNTS[existing_key]
            for field in ACCOUNT_RECORD_FIELDS:
                value = rec.get(field)
                if value in (None, ""):
                    continue
                if field == "sessionId":
                    continue
                if field in {"role", "area"}:
                    if not acc.get(field):
                        acc[field] = value
                else:
                    acc[field] = value
            if not acc.get("serverQuery") and server_query:
                acc["serverQuery"] = server_query
            if not acc.get("displayName"):
                acc["displayName"] = f"{username}@{server_query}"
            if not acc.get("stopEvent"):
                acc["stopEvent"] = threading.Event()
            continue
        sid = sid or "local_" + uuid4().hex[:12]
        while sid in ACCOUNTS:
            sid = "local_" + uuid4().hex[:12]
        acc = {k: rec.get(k) for k in ACCOUNT_RECORD_FIELDS if rec.get(k) not in (None, "")}
        acc.update({
            "sessionId": sid,
            "username": username,
            "password": str(rec.get("password") or ""),
            "serverQuery": server_query,
            "platform": platform_display_name(rec.get("platform")),
            "serial": str(rec.get("serial") or "0"),
            "displayName": rec.get("displayName") or f"{username}@{server_query}",
            "role": rec.get("role") or {},
            "area": rec.get("area") or {"areaName": server_query},
            "status": "checking" if sid in SESSIONS else "stopped",
            "started": bool(sid in SESSIONS),
            "localOnly": not bool(sid in SESSIONS),
            "createdAt": int(rec.get("createdAt") or now_ms()),
            "stopEvent": threading.Event(),
        })
        ACCOUNTS[sid] = acc


def restore_account_records() -> None:
    database_records = database_account_records()
    if database_records:
        with ACCOUNT_LOCK:
            merge_account_records(database_records)


RUNTIME_TRANSIENT_SESSION_FIELDS = {
    "lastTargets",
    "lastMineTargets",
    "state8004PayloadHex",
    # 军情是“此刻”的状态，重启后必须重新向服务器确认。
    # 持久化会让旧军情在重启后冒充实时数据。
    "militarySnapshot",
}


def runtime_session_snapshot(sess: dict[str, Any]) -> dict[str, Any]:
    return json_safe({
        key: value
        for key, value in sess.items()
        if key not in RUNTIME_TRANSIENT_SESSION_FIELDS
    })


def _deferred_runtime_state_persist() -> None:
    global RUNTIME_STATE_PERSIST_TIMER
    with STATE_LOCK:
        RUNTIME_STATE_PERSIST_TIMER = None
        dirty = RUNTIME_STATE_DIRTY
    if dirty:
        persist_runtime_state(force=True)


def persist_runtime_state(*, force: bool = False) -> None:
    """Persist runtime metadata, coalescing bursts of high-frequency updates."""
    global RUNTIME_STATE_DIRTY, RUNTIME_STATE_LAST_PERSIST_AT
    global RUNTIME_STATE_PERSIST_TIMER
    with STATE_LOCK:
        RUNTIME_STATE_DIRTY = True
        elapsed = time.monotonic() - RUNTIME_STATE_LAST_PERSIST_AT
        if not force and elapsed < RUNTIME_STATE_PERSIST_INTERVAL_SEC:
            remaining = max(0.05, RUNTIME_STATE_PERSIST_INTERVAL_SEC - elapsed)
            if (
                RUNTIME_STATE_PERSIST_TIMER is None
                or not RUNTIME_STATE_PERSIST_TIMER.is_alive()
            ):
                timer = threading.Timer(
                    remaining,
                    _deferred_runtime_state_persist,
                )
                timer.daemon = True
                RUNTIME_STATE_PERSIST_TIMER = timer
                timer.start()
            return
        pending_timer = RUNTIME_STATE_PERSIST_TIMER
        RUNTIME_STATE_PERSIST_TIMER = None
        if pending_timer is not None and pending_timer is not threading.current_thread():
            pending_timer.cancel()
        with ACCOUNT_LOCK, DAILY_LOCK:
            accounts = []
            for acc in ACCOUNTS.values():
                item = {k: v for k, v in acc.items() if k not in {"thread", "stopEvent"}}
                accounts.append(json_safe(item))
            sessions = [
                runtime_session_snapshot(sess)
                for sess in SESSIONS.values()
            ]
            active_session_ids = set(ACCOUNTS) | set(SESSIONS)
            payload = {
                "time": now_ms(),
                "accounts": accounts,
                "sessions": sessions,
                "savedConfigs": json_safe({
                    sid: config
                    for sid, config in SAVED_CONFIGS.items()
                    if sid in active_session_ids
                }),
                "savedFormationRules": json_safe({
                    sid: rows
                    for sid, rows in SAVED_FORMATION_RULES.items()
                    if sid in active_session_ids
                }),
                "dailyBrushCounts": json_safe(DAILY_BRUSH_COUNTS),
                "dailyDungeonCounts": json_safe(DAILY_DUNGEON_COUNTS),
                "dailyTaskCompletions": json_safe(DAILY_TASK_COMPLETIONS),
            }
        database_save_runtime_snapshot(payload)
        write_account_records_file(accounts)
        RUNTIME_STATE_LAST_PERSIST_AT = time.monotonic()
        RUNTIME_STATE_DIRTY = False


def restore_runtime_state() -> None:
    payload = database_load_runtime_snapshot()
    if not isinstance(payload, dict):
        restore_account_records()
        write_account_records_file()
        return
    with ACCOUNT_LOCK, DAILY_LOCK:
        SESSIONS.clear()
        for sess in payload.get("sessions") or []:
            sid = str(sess.get("sessionId") or "")
            if sid:
                SESSIONS[sid] = dict(sess)
        ACCOUNTS.clear()
        for raw in payload.get("accounts") or []:
            acc = dict(raw or {})
            migrate_removed_proxy_routes(acc)
            sid = str(acc.get("sessionId") or "")
            if not sid:
                continue
            acc["stopEvent"] = threading.Event()
            if acc.get("started"):
                if sid in SESSIONS:
                    acc["status"] = "checking"
                    acc["lastError"] = ""
                else:
                    acc["status"] = "offline"
                    acc["lastError"] = "服务重启后未找到 session，请点击启动重新登录"
            else:
                acc["status"] = "stopped"
                acc["lastHeartbeat"] = {
                    "online": False,
                    "message": str(acc.get("lastError") or "已关闭"),
                    "checkedAt": now_ms(),
                }
            ACCOUNTS[sid] = acc
        SAVED_CONFIGS.clear()
        SAVED_CONFIGS.update(dict(payload.get("savedConfigs") or {}))
        SAVED_FORMATION_RULES.clear()
        for sid, rows in dict(payload.get("savedFormationRules") or {}).items():
            SAVED_FORMATION_RULES[str(sid)] = list(rows or [])
        if not ACCOUNT_STATE_DB_READY:
            DAILY_BRUSH_COUNTS.clear()
            for key, value in dict(payload.get("dailyBrushCounts") or {}).items():
                try:
                    DAILY_BRUSH_COUNTS[str(key)] = int(value)
                except Exception:
                    pass
            DAILY_DUNGEON_COUNTS.clear()
            for key, value in dict(payload.get("dailyDungeonCounts") or {}).items():
                try:
                    DAILY_DUNGEON_COUNTS[str(key)] = int(value)
                except Exception:
                    pass
            DAILY_TASK_COMPLETIONS.clear()
            for key, value in dict(payload.get("dailyTaskCompletions") or {}).items():
                if isinstance(value, dict):
                    DAILY_TASK_COMPLETIONS[str(key)] = {
                        str(task_key): dict(detail or {})
                        for task_key, detail in value.items()
                        if isinstance(detail, dict)
                    }
    if ACCOUNT_STATE_DB_READY:
        load_daily_state_cache_from_database()
    restore_account_records()
    for sess in list(SESSIONS.values()):
        try:
            habits = apply_account_habits_to_session(sess)
            sid = str(sess.get("sessionId") or "")
            # 兼容旧版本：把 runtime_state 里的全局配置迁移成“账号+区服”独立习惯文件。
            if not habits.get("formations") and SAVED_FORMATION_RULES.get(sid):
                save_account_habits(sess, formations=SAVED_FORMATION_RULES.get(sid) or [])
            if not habits.get("config") and SAVED_CONFIGS.get(sid):
                save_account_habits(sess, config=SAVED_CONFIGS.get(sid) or {})
        except Exception as e:
            system_log(f"恢复账号习惯失败：{e}", level="warn", source="runtime", session_id=str(sess.get("sessionId") or ""))
    write_account_records_file()


def reconcile_restored_live_session_reconnect_states() -> list[str]:
    """Clear stale reconnect state when the same account has a live Session.

    A snapshot can be persisted between marking an account for reconnect and
    removing its Session.  Restoring that snapshot otherwise leaves an
    impossible combination: ``SESSIONS`` contains the account, while the game
    request gate rejects every heartbeat because ``reconnectState`` is still
    ``countdown``.  Move only those contradictory records back to ``checking``
    and let the first normal heartbeat validate the restored Session.
    """

    reconciled: list[str] = []
    checked_at = now_ms()
    with ACCOUNT_LOCK:
        for sid, acc in ACCOUNTS.items():
            if (
                not bool(acc.get("started"))
                or sid not in SESSIONS
                or str(acc.get("reconnectState") or "")
                not in {"countdown", "reconnecting"}
            ):
                continue
            acc["status"] = "checking"
            acc["reconnectState"] = ""
            acc["reconnectAt"] = None
            acc["reconnectReason"] = ""
            acc["reconnectGeneration"] = ""
            acc["reconnectFailureKind"] = ""
            acc["reconnectFailureCount"] = 0
            acc["heartbeatNetworkFailureCount"] = 0
            acc["heartbeatUnconfirmedFailureCount"] = 0
            acc["heartbeatNetworkSwitchCount"] = 0
            acc["heartbeatNetworkSwitchAttemptCount"] = 0
            acc["heartbeatNetworkTriedProxyNodes"] = []
            acc["networkDegraded"] = False
            acc["responseUnconfirmed"] = False
            acc["lastNetworkFailure"] = None
            acc["lastError"] = ""
            acc["lastHeartbeat"] = {
                "online": False,
                "checking": True,
                "message": "服务重启后正在验证已恢复会话",
                "checkedAt": checked_at,
            }
            # Also replace a possible in-memory stop signal if this helper is
            # reused by a warm-recovery path in the future.
            acc["stopEvent"] = threading.Event()
            reconciled.append(str(sid))
    for sid in reconciled:
        account_log(
            sid,
            "检测到已恢复会话与重连倒计时冲突，已清除旧倒计时并重新验证会话",
            level="warn",
            source="reconnect",
        )
    return reconciled


def daily_account_key(sess: dict[str, Any], date_key: str | None = None) -> str:
    role = sess.get("role") or {}
    area = sess.get("area") or {}
    return "|".join([
        str(date_key or time.strftime("%Y%m%d")),
        str(sess.get("username") or ""),
        str(area.get("areaId") or area.get("areaName") or ""),
        str(role.get("roleId") or ""),
    ])


def daily_brush_key(sess: dict[str, Any]) -> str:
    return daily_account_key(sess)


def daily_dungeon_key(sess: dict[str, Any]) -> str:
    return daily_account_key(sess)


def get_daily_brush_count(sess: dict[str, Any]) -> int:
    key = daily_brush_key(sess)
    with DAILY_LOCK:
        return int(DAILY_BRUSH_COUNTS.get(key, 0))


def record_daily_brush_success(sess: dict[str, Any]) -> int:
    key = daily_brush_key(sess)
    if ACCOUNT_STATE_DB_READY:
        count = database_increment_daily_counter(key, "brushYellow")
        with DAILY_LOCK:
            DAILY_BRUSH_COUNTS[key] = count
        return count
    with DAILY_LOCK:
        DAILY_BRUSH_COUNTS[key] = int(DAILY_BRUSH_COUNTS.get(key, 0)) + 1
        count = DAILY_BRUSH_COUNTS[key]
    persist_runtime_state()
    return count


