def ensure_military_generals_full_loyalty(
    sess: dict[str, Any],
    selected: list[dict[str, Any]],
    *,
    action_name: str,
    task: dict[str, Any] | None = None,
) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    try:
        plans = shared_plan_generals_full_loyalty(
            selected,
            action_name=action_name,
        )
    except ValueError as exc:
        raise RuntimeError(str(exc)) from exc
    for plan in plans:
        general = selected[int(plan["sourceIndex"])]
        general_id = int(plan["generalId"])
        name = str(plan["name"])
        loyalty = int(plan["loyalty"])
        loyalty_limit = int(plan["loyaltyLimit"])
        if bool(plan.get("skipped")):
            results.append(dict(plan))
            continue
        delta = int(plan["delta"])
        if task:
            task_log(
                task,
                f"{action_name}满忠检查：{name} {loyalty}/{loyalty_limit}，"
                f"需要补{delta}点",
            )
        payload = bytes.fromhex(str(plan["payloadHex"]))
        code, data, packets = post_game(
            sess["gameHttp"],
            [(0x121F, payload)],
            int(sess["dm"]),
            account_id=str(sess.get("sessionId") or ""),
        )
        candidates = [
            parse_821f_loyalty_response(packet["payload"])
            for packet in packets
            if packet.get("opcode") == 0x821F and "payload" in packet
        ]
        parsed = next(
            (item for item in candidates if item.get("success")),
            candidates[0] if candidates else None,
        )
        try:
            confirmed = shared_apply_full_loyalty_receipt(
                plan,
                parsed or {},
                action_name=action_name,
            )
        except ValueError as exc:
            raise RuntimeError(str(exc)) from exc
        new_loyalty = int(confirmed["loyalty"])
        new_limit = int(confirmed["loyaltyLimit"])
        general["loyalty"] = new_loyalty
        general["loyaltyLimit"] = new_limit
        for session_general in sess.get("generals") or []:
            if int(session_general.get("id") or 0) == general_id:
                session_general["loyalty"] = new_loyalty
                session_general["loyaltyLimit"] = new_limit
        role_state = sess.get("roleState")
        if isinstance(role_state, dict):
            role_state["copper"] = confirmed.get("copper")
        result = {
            **confirmed,
            "http": code,
            "responseBytes": len(data),
            "payloadHex": payload.hex(),
            "name": name,
        }
        results.append(result)
        if task:
            task_log(
                task,
                f"{action_name}满忠成功：{name} {new_loyalty}/{new_limit}，"
                f"消耗{int(parsed.get('actualCost') or 0)}铜钱",
            )
    if task:
        summary = "，".join(
            f"{item.get('name')} {item.get('loyalty') or (item.get('generals') or [{}])[0].get('loyalty')}/"
            f"{item.get('loyaltyLimit') or (item.get('generals') or [{}])[0].get('loyaltyLimit')}"
            for item in results
        )
        task_log(task, f"{action_name}满忠完成：{summary}")
    return {"success": True, "generals": results}


