def accelerate_mine_march(
    sess: dict[str, Any],
    battle_id: int,
    remaining_seconds: int,
    *,
    task: dict[str, Any] | None = None,
) -> dict[str, Any]:
    actions: list[dict[str, Any]] = []
    estimated_remaining = max(0, int(remaining_seconds))
    try:
        inventory = refresh_inventory(sess)
    except Exception as exc:
        message = f"智能加速跳过：读取行军符库存失败；{exc}"
        if task:
            task_log(task, message)
        return {"success": False, "skipped": True, "message": message, "actions": actions}

    while estimated_remaining > MINE_SPEED_STOP_BELOW_SECONDS:
        choices = choose_march_speed_items(
            estimated_remaining,
            list(inventory.get("items") or []),
        )
        if not choices:
            message = (
                f"智能加速跳过：剩余行军时间不足"
                f"{MINE_SPEED_STOP_BELOW_SECONDS}秒"
                if estimated_remaining <= MINE_SPEED_STOP_BELOW_SECONDS
                else "智能加速跳过：宝库中没有可用行军符"
            )
            if task:
                task_log(task, message)
            return {
                "success": bool(actions),
                "skipped": not actions,
                "message": message,
                "estimatedRemainingSeconds": estimated_remaining,
                "actions": actions,
            }
        item_id = choices[0]
        item_name = ITEM_NAME_FALLBACK.get(item_id, f"行军符#{item_id}")
        payload = build_mine_speed_payload(battle_id, item_id)
        code, data, packets = post_game(
            sess["gameHttp"],
            [(MINE_SPEED_REQUEST_OPCODE, payload)],
            int(sess["dm"]),
            account_id=str(sess.get("sessionId") or ""),
        )
        candidates = [
            parse_8524_mine_speed_response(packet["payload"])
            for packet in packets
            if packet.get("opcode") == MINE_SPEED_RESPONSE_OPCODE
            and "payload" in packet
        ]
        parsed = next(
            (item for item in candidates if item.get("success")),
            candidates[0] if candidates else {
                "success": False,
                "status": None,
                "message": (
                    f"未收到 0x{MINE_SPEED_RESPONSE_OPCODE:04x} "
                    "行军加速响应"
                ),
            },
        )
        action = {
            **parsed,
            "itemId": item_id,
            "itemName": item_name,
            "http": code,
            "responseBytes": len(data),
            "payloadHex": payload.hex(),
            "packets": summarize_packets(packets),
        }
        actions.append(action)
        if not parsed.get("success"):
            if task:
                task_log(task, f"智能加速停止：{item_name}；{parsed.get('message')}")
            return {
                "success": bool(actions[:-1]),
                "message": str(parsed.get("message") or "行军加速失败"),
                "estimatedRemainingSeconds": estimated_remaining,
                "actions": actions,
            }
        estimated_remaining = max(
            0,
            estimated_remaining - MARCH_SPEED_SECONDS[item_id],
        )
        if task:
            task_log(
                task,
                f"智能加速成功：使用{item_name}，预计剩余{estimated_remaining}秒",
            )
        try:
            inventory = refresh_inventory(sess)
        except Exception as exc:
            if task:
                task_log(task, f"智能加速停止：刷新行军符库存失败；{exc}")
            break
    return {
        "success": bool(actions),
        "message": "智能加速完成" if actions else "无需使用行军符",
        "estimatedRemainingSeconds": estimated_remaining,
        "actions": actions,
    }


def build_raid_fief_list_payload(player_name: str) -> bytes:
    """0x1310 查询指定玩家封地列表：0001 + UTF(playerName)。"""
    return shared_build_raid_fief_list_payload(player_name)


def parse_raid_fief_list(payload: bytes) -> dict[str, Any]:
    """解析 0x8310 玩家封地列表。"""
    return shared_parse_raid_fief_list(payload)


def query_raid_fiefs(sess: dict[str, Any], player_name: str) -> dict[str, Any]:
    payload = build_raid_fief_list_payload(player_name)
    code, data, packets = post_game(
        sess["gameHttp"],
        [(RAID_FIEF_QUERY_OPCODE, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    pkt = next((p for p in packets if p.get("opcode") == RAID_FIEF_QUERY_RESPONSE_OPCODE and "payload" in p), None)
    if not pkt:
        raise RuntimeError(
            f"查询玩家封地列表未返回 0x{RAID_FIEF_QUERY_RESPONSE_OPCODE:04x}："
            + json.dumps(summarize_packets(packets), ensure_ascii=False)[:500]
        )
    parsed = parse_raid_fief_list(pkt["payload"])
    if parsed.get("parseError"):
        raise RuntimeError("玩家封地列表解析失败：" + str(parsed.get("parseError")))
    parsed.update({
        "http": code,
        "opcode": f"0x{RAID_FIEF_QUERY_OPCODE:04x}/0x{RAID_FIEF_QUERY_RESPONSE_OPCODE:04x}",
        "requestPayloadHex": payload.hex(),
        "packets": summarize_packets(packets),
        "queriedPlayerName": str(player_name or "").strip(),
        "updatedAt": now_ms(),
    })
    sess["lastRaidFiefs"] = parsed
    persist_runtime_state()
    return parsed


def recommend_brush_center(
    sess: dict[str, Any],
    general_ids: list[str],
    *,
    enforce_role_level: bool = False,
) -> dict[str, Any]:
    """Delegate the cached-only recommendation to the shared Python core."""
    locations = sess.get("ownedFiefLocations") or {}
    if isinstance(locations, dict):
        primary_fiefs = [
            item
            for item in locations.values()
            if isinstance(item, dict)
        ]
    else:
        primary_fiefs = []
    legacy_fiefs = [
        item
        for item in (sess.get("lastRaidFiefs") or {}).get("fiefs") or []
        if isinstance(item, dict)
    ]
    return shared_local_view(
        "POST",
        "/api/brush/recommended-center",
        {
            "generalIds": list(general_ids or []),
            "generals": list(sess.get("generals") or []),
            "fiefs": [*primary_fiefs, *legacy_fiefs],
            "roleLevel": session_role_level(sess),
            "enforceRoleLevel": bool(enforce_role_level),
        },
    )


def enrich_generals_with_fief_names(sess: dict[str, Any]) -> None:
    locations = sess.get("ownedFiefLocations") or {}
    if not locations:
        cached_fiefs = (sess.get("lastRaidFiefs") or {}).get("fiefs") or []
        locations = {
            str(item.get("targetId")): item
            for item in cached_fiefs
            if int(item.get("targetId") or 0) > 0
        }
        if locations:
            sess["ownedFiefLocations"] = locations
    names = sess.get("ownedFiefNames") or {}
    for general in sess.get("generals") or []:
        fief_id = str(general.get("fiefId") or general.get("placeID") or "")
        location = locations.get(fief_id) if fief_id else None
        if isinstance(location, dict):
            general["fiefName"] = (
                location.get("fiefName")
                or location.get("name")
                or names.get(fief_id)
                or ""
            )
            general["cityName"] = location.get("cityName") or location.get("city") or ""
            general["fiefX"] = location.get("x")
            general["fiefY"] = location.get("y")
        elif fief_id and names.get(fief_id):
            general["fiefName"] = names[fief_id]


def refresh_owned_fief_locations(sess: dict[str, Any]) -> dict[str, dict[str, Any]]:
    """Fetch and cache every owned fief's name/coordinates at account login."""
    role_name = str(
        (sess.get("roleState") or {}).get("roleName")
        or (sess.get("role") or {}).get("roleName")
        or ""
    ).strip()
    if not role_name:
        raise RuntimeError("当前账号没有可识别的角色名称，无法读取封地名称")
    own_fiefs = query_raid_fiefs(sess, role_name)
    locations = {
        str(item.get("targetId")): item
        for item in own_fiefs.get("fiefs") or []
        if int(item.get("targetId") or 0) > 0
    }
    sess["ownedFiefLocations"] = locations
    sess["ownedFiefNames"] = {
        fief_id: str(item.get("fiefName") or item.get("name") or "").strip()
        for fief_id, item in locations.items()
        if str(item.get("fiefName") or item.get("name") or "").strip()
    }
    sess["ownedFiefLocationsUpdatedAt"] = now_ms()
    sess.pop("ownedFiefLocationError", None)
    enrich_generals_with_fief_names(sess)
    account_log(
        str(sess.get("sessionId") or ""),
        f"登录坐标缓存完成：已保存 {len(locations)} 个封地坐标",
        source="server",
    )
    persist_runtime_state()
    return locations


