def execute_mine(
    sess: dict[str, Any],
    opts: dict[str, Any],
    task: dict[str, Any] | None = None,
    *,
    prepared_generals: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    if str(opts.get("confirm") or "") != "mine":
        raise RuntimeError("真实打矿需要 confirm=mine")
    target = opts.get("target")
    if not isinstance(target, dict):
        target_id = str(opts.get("targetId") or "")
        target = next((
            item
            for item in sess.get("lastMineTargets") or []
            if str(item.get("id")) == target_id
            or str(item.get("idHex")) == target_id.lower().removeprefix("0x")
        ), None)
    if not isinstance(target, dict):
        raise RuntimeError("未指定矿场目标，请先搜索资源点")
    if bool(target.get("playerOccupied")):
        raise RuntimeError(
            f"矿点已由玩家{target.get('ownerName') or '未知玩家'}占领，"
            "自动打矿禁止攻击玩家资源点"
        )
    raw_general_ids = opts.get("generalIds")
    if isinstance(raw_general_ids, list):
        general_ids = [
            str(value) for value in raw_general_ids if str(value or "").strip()
        ]
    else:
        general_id = str(opts.get("generalId") or "").strip()
        general_ids = [general_id] if general_id else []
    general_ids = list(dict.fromkeys(general_ids))
    selected = (
        list(prepared_generals)
        if prepared_generals is not None
        else prepare_military_generals(
            sess,
            general_ids,
            "打矿",
            task=task,
        )
    )
    role_state = (
        sess.get("roleState")
        if isinstance(sess.get("roleState"), dict)
        else {}
    )
    resource_current = int(role_state.get("resourcePointCurrent") or 0)
    resource_cap = int(role_state.get("resourcePointCap") or 0)
    if resource_cap > 0 and resource_current >= resource_cap:
        raise RuntimeError(
            f"资源点数量已满({resource_current}/{resource_cap})，无法继续打矿"
        )
    loyalty_result: dict[str, Any] = {"success": True, "skipped": True}
    if bool(opts.get("fullLoyalty")):
        loyalty_result = ensure_mine_generals_full_loyalty(
            sess,
            selected,
            task=task,
        )
    general_hexes = [
        str(general.get("idHex") or f"{int(general['id']):016x}")
        for general in selected
    ]
    prepare_payload, expedition_payload = build_mine_payloads(
        general_hexes,
        int(target["id"]),
    )
    action_results: list[dict[str, Any]] = []
    baseline_updated_at = int((sess.get("militaryIntel") or {}).get("updatedAt") or 0)

    def send_action(phase: str, opcode: int, payload: bytes) -> list[dict[str, Any]]:
        code, data, packets = post_game(
            sess["gameHttp"],
            [(opcode, payload)],
            int(sess["dm"]),
            account_id=str(sess.get("sessionId") or ""),
        )
        action_results.append({
            "phase": phase,
            "http": code,
            "opcode": f"0x{opcode:04x}",
            "payloadHex": payload.hex(),
            "responseBytes": len(data),
            "packets": summarize_packets(packets),
        })
        return packets

    prepare_packets = send_action("prepare", MINE_PREPARE_OPCODE, prepare_payload)
    preview_candidates = [
        parse_8520_mine_preview(packet["payload"])
        for packet in prepare_packets
        if packet.get("opcode") == MINE_PREPARE_RESPONSE_OPCODE and "payload" in packet
    ]
    preview = next(
        (item for item in preview_candidates if item.get("valid")),
        None,
    )
    preview_failure = ""
    if preview is None:
        preview_failure = (
            "；".join(
                str(item.get("error") or "")
                for item in preview_candidates
                if item.get("error")
            )
            or "未收到有效的 0x8520 出征预览，已禁止发送正式出征"
        )
    elif (
        int(preview.get("x") or 0) != int(target.get("x") or 0)
        or int(preview.get("y") or 0) != int(target.get("y") or 0)
    ):
        preview_failure = (
            f"出征预览坐标({preview.get('x')},{preview.get('y')})与目标"
            f"({target.get('x')},{target.get('y')})不一致，已禁止正式出征"
        )
    elif int(preview.get("marchSeconds") or 0) > int(
        opts.get("maxMarchMinutes") or 45
    ) * 60:
        march_minutes = round(int(preview.get("marchSeconds") or 0) / 60, 1)
        preview_failure = (
            f"预计到达目标需要{march_minutes}分钟，超过设定的"
            f"{int(opts.get('maxMarchMinutes') or 45)}分钟，已禁止正式出征"
        )
    if task and preview:
        task_log(
            task,
            f"打矿出征预览：目标({preview.get('x')},{preview.get('y')})，"
            f"胜率={preview.get('winRate')}%，行军={preview.get('marchSeconds')}秒",
        )

    expedition_packets_raw: list[dict[str, Any]] = []
    if not preview_failure:
        time.sleep(0.35)
        expedition_packets_raw = send_action(
            "expedition", MINE_DISPATCH_OPCODE, expedition_payload
        )
    expedition_packets = [
        packet
        for action in action_results
        if action.get("phase") == "expedition"
        for packet in action.get("packets") or []
        if packet.get("opcode") == f"0x{MINE_DISPATCH_RESPONSE_OPCODE:04x}"
    ]
    parsed = [packet.get("dispatch8522") or {} for packet in expedition_packets]
    accepted = next((item for item in parsed if item.get("success")), None)
    failure_reason = preview_failure
    if not accepted and not failure_reason:
        payload_hexes = [
            str(packet.get("payloadHex") or "").lower()
            for packet in expedition_packets
        ]
        status_minus_14 = next(
            (item for item in parsed if int(item.get("status") or 0) == -14),
            None,
        )
        if status_minus_14:
            failure_reason = str(status_minus_14.get("message") or (
                "目标封地的君主等级不足，或使用了免战牌，处于保护状态"
            ))
        elif payload_hexes and all(value == "ff0000" for value in payload_hexes):
            failure_reason = (
                "游戏服拒绝打矿出征(0x8522=ff0000)，"
                "通常是将领状态、体力、配兵或资源点状态不满足"
            )
        else:
            failure_reason = "；".join(
                str(item.get("message") or "")
                for item in parsed
                if item.get("message")
            ) or "未收到可确认成功的 0x8522 打矿响应"
    battle_id = int((accepted or {}).get("battleId") or 0)
    if accepted and battle_id:
        remember_pending_mine_garrison(
            sess,
            battle_id=battle_id,
            general_ids=[
                int(general.get("id") or int(str(general.get("idHex")), 16))
                for general in selected
            ],
            target=target,
            march_seconds=int((preview or {}).get("marchSeconds") or 0),
        )
        # 出征受理即写入角色记录；驻守、召回属于后续闭环，不能让用户等待
        # 十几分钟后才看到这次真实打矿出征。
        record_success_action(
            str(sess.get("sessionId") or ""),
            "打矿",
            f"出征 > {target.get('name') or '资源点'}"
            f"({target.get('x')}，{target.get('y')})",
            detail={"target": target, "battleId": battle_id},
        )
    speed_result: dict[str, Any] = {"success": True, "skipped": True}
    if accepted and mine_speed_enabled(opts.get("speed")):
        speed_result = accelerate_mine_march(
            sess,
            battle_id,
            int((preview or {}).get("marchSeconds") or 0),
            task=task,
        )
    garrison: dict[str, Any] = {}
    recall: dict[str, Any] = {}
    returned: dict[str, Any] = {}
    complete_success = False
    if accepted and bool(opts.get("waitForSettlement", True)):
        natural_wait = int((preview or {}).get("marchSeconds") or 0) + 15 * 60
        max_wait = max(
            120,
            min(
                max(
                    int(opts.get("maxSettlementWaitSec") or 900),
                    natural_wait,
                ),
                4 * 60 * 60,
            ),
        )
        garrison = wait_for_mine_garrison(
            sess,
            general_ids,
            battle_id=battle_id,
            target=target,
            max_wait_sec=max_wait,
            updated_after_ms=baseline_updated_at,
            task=task,
        )
        if garrison.get("confirmed"):
            recall = recall_mine_garrison(sess, battle_id, task=task)
            if recall.get("success"):
                returned = wait_for_mine_generals_idle(
                    sess,
                    general_ids,
                    max_wait_sec=max_wait,
                    updated_after_ms=int(
                        (sess.get("militaryIntel") or {}).get("updatedAt") or 0
                    ),
                    task=task,
                )
                complete_success = bool(returned.get("finished"))
                if complete_success:
                    forget_pending_mine_garrison(sess, battle_id)
                if not complete_success:
                    failure_reason = str(
                        returned.get("reason") or "召回后未确认将领回闲"
                    )
            else:
                failure_reason = str(
                    recall.get("message") or "未确认 0x8526 召回成功"
                )
        else:
            if garrison.get("battleFailed"):
                forget_pending_mine_garrison(sess, battle_id)
            failure_reason = str(
                garrison.get("reason")
                or "战斗结束后未确认将领进入防/驻守状态，未发送召回"
            )
    elif accepted:
        complete_success = True

    report = {
        "time": now_ms(),
        "role": sess.get("role") or {},
        "resourcePointCapacity": {
            "current": resource_current,
            "cap": resource_cap,
            "available": max(0, resource_cap - resource_current) if resource_cap else None,
        },
        "area": sess.get("area") or {},
        "target": target,
        "generals": [{
            "id": general.get("id"),
            "idHex": general.get("idHex"),
            "name": general.get("name"),
            "status": general.get("displayStatus") or general.get("statusText"),
            "soldierTypeCode": general.get("soldierTypeCode"),
            "soldierCount": general.get(
                "soldierCount",
                general.get("currentSoldierCount"),
            ),
            "loyalty": general.get("loyalty"),
            "loyaltyLimit": general.get("loyaltyLimit"),
        } for general in selected],
        "payloads": {
            "prepareOpcode": "0x1520",
            "preparePayloadHex": prepare_payload.hex(),
            "expeditionOpcode": "0x1522",
            "expeditionPayloadHex": expedition_payload.hex(),
            "actionType": 2,
            "dispatchMode": "immediate",
        },
        # success 表示完整闭环，不再把“服务器受理出征”误算作打矿完成。
        "success": bool(complete_success),
        "dispatchAccepted": bool(accepted),
        "successBattleId": battle_id or None,
        "preview": preview or (preview_candidates[0] if preview_candidates else {}),
        "fullLoyalty": loyalty_result,
        "speed": speed_result,
        "garrison": garrison,
        "recall": recall,
        "returned": returned,
        "failureReason": failure_reason,
        "actionResults": action_results,
    }
    report["reportFile"] = ""
    return report


def _selected_general_states(
    sess: dict[str, Any],
    general_ids: list[str],
) -> tuple[list[dict[str, Any]], list[str]]:
    states: list[dict[str, Any]] = []
    missing: list[str] = []
    generals = sess.get("generals") or []
    for raw_id in general_ids:
        gid = str(raw_id or "")
        general = next((
            item
            for item in generals
            if str(item.get("id")) == gid or str(item.get("idHex")) == gid
        ), None)
        if not general:
            missing.append(gid)
            continue
        states.append({
            "id": general.get("id"),
            "idHex": general.get("idHex"),
            "name": general.get("name") or gid,
            "status": (
                general.get("displayStatus")
                or general.get("statusText")
                or general_status_text_from_code(general.get("status"))
            ),
        })
    return states, missing


def mine_general_id_set(
    sess: dict[str, Any],
    general_ids: list[Any],
) -> set[int]:
    aliases: dict[str, int] = {}
    for general in sess.get("generals") or []:
        try:
            gid = int(general.get("id"))
        except (TypeError, ValueError):
            try:
                gid = int(str(general.get("idHex") or ""), 16)
            except (TypeError, ValueError):
                continue
        aliases[str(general.get("id") or "")] = gid
        aliases[str(general.get("idHex") or "").lower()] = gid
        aliases[f"0x{gid:016x}"] = gid
    resolved: set[int] = set()
    for raw in general_ids:
        if isinstance(raw, int):
            resolved.add(raw)
            continue
        value = str(raw or "").strip().lower()
        if not value:
            continue
        if value in aliases:
            resolved.add(aliases[value])
            continue
        try:
            resolved.add(int(value, 16 if value.startswith("0x") else 10))
        except ValueError:
            continue
    return resolved


def remember_pending_mine_garrison(
    sess: dict[str, Any],
    *,
    battle_id: int,
    general_ids: list[Any],
    target: dict[str, Any],
    march_seconds: int = 0,
    adopted: bool = False,
) -> dict[str, Any]:
    pending = [
        dict(item)
        for item in sess.get("pendingMineGarrisons") or []
        if isinstance(item, dict)
        and int(item.get("battleId") or 0) != int(battle_id)
    ]
    record = {
        "battleId": int(battle_id),
        "generalIds": sorted(mine_general_id_set(sess, general_ids)),
        "target": json_safe(dict(target or {})),
        "dispatchAt": now_ms(),
        "marchSeconds": max(0, int(march_seconds or 0)),
        "adoptedFromMilitaryIntel": bool(adopted),
    }
    pending.append(record)
    sess["pendingMineGarrisons"] = pending
    sid = str(sess.get("sessionId") or "")
    if sid and SESSIONS.get(sid) is sess:
        persist_runtime_state()
    return record


def forget_pending_mine_garrison(
    sess: dict[str, Any],
    battle_id: int,
) -> None:
    old_pending = sess.get("pendingMineGarrisons") or []
    pending = [
        item
        for item in old_pending
        if not isinstance(item, dict)
        or int(item.get("battleId") or 0) != int(battle_id)
    ]
    if len(pending) == len(old_pending):
        return
    if pending:
        sess["pendingMineGarrisons"] = pending
    else:
        sess.pop("pendingMineGarrisons", None)
    sid = str(sess.get("sessionId") or "")
    if sid and SESSIONS.get(sid) is sess:
        persist_runtime_state()


def parse_8600_military_events(payload: bytes) -> list[dict[str, Any]]:
    """Parse battle IDs and formations following 0x8600 event UTF fields."""
    return shared_parse_8600_military_events(payload)


# --- 军情快照（0x1600 / 0x8600）---------------------------------------------
#
# 军情页展示的是“此刻正在进行的军事行动”，不是历史事件流。抓包
# （ctf_out/passive_pcap_hotspot_20260714_033644 / _044023 / _125113，
# 三份都带 operator_timeline 口述真值）确认同一次出征在 0x8600 里
# 表现为同一个 battleId 的一条记录，随时间在下列状态之间流转：
#
#   【攻占】…战斗进行中  →  【驻守】…驻守在X  →  【返回】…返回某某的封地
#
# 2026-07-29 的真实来袭样本进一步确认：0x8600 不是“搜到一个【…】文本，
# 紧跟一条行动记录”的平铺结构，而是原版客户端 scriptPages/data/a.B/C
# 读取的三个分区：
#
#   type=1  我方出征/战斗/返回：文本表 + 编队记录表
#   type=2  敌军来袭：来袭玩家、行动类型、目标封地、剩余时间、到达时间
#   type=3  我方驻守：文本表 + 驻守编队记录表
#
# 文本表和记录表按索引关联。旧的 UTF 锚点启发式在同时存在两支编队时会把
# 第一条文本和第二条结构错配，也会完全漏掉 type=2（其完整“【掠夺】…”文案
# 是客户端用分离字段拼出来的，响应里没有带【】的完整文本）。这里严格按原版
# 的读取顺序前向解析；任一边界校验失败就放弃整包，宁可少报也不伪造军情。
#
# 说明：上面的 parse_8600_military_events 是打矿召回链路已验证的专用解析，
# 只认【驻守】。那条链路会据此决定要不要召回真实部队，因此这里另起一个
# 通用解析，不去改动它。

# 真实客户端点击军情刷新时发出的 0x1600 请求体（抓包逐字节一致）。
# The shared-contract assignment near the contract loader replaces this compatibility
# value after module definitions have loaded; keeping the early value avoids a
# forward-reference during import.
MILITARY_INTEL_REQUEST_PAYLOAD = SHARED_MILITARY_INTEL_REQUEST_PAYLOAD

MILITARY_ACTION_TARGET_TYPES = SHARED_MILITARY_ACTION_TARGET_TYPES
MILITARY_ACTION_STATE_BY_TAG = SHARED_MILITARY_ACTION_STATE_BY_TAG
MILITARY_INCOMING_ACTION_TYPES = SHARED_MILITARY_INCOMING_ACTION_TYPES
MILITARY_MARCH_KINDS = SHARED_MILITARY_MARCH_KINDS
MILITARY_OUTBOUND_MARCH_KINDS = SHARED_MILITARY_OUTBOUND_MARCH_KINDS
MILITARY_BATTLE_IN_PROGRESS_MARKER = SHARED_MILITARY_BATTLE_IN_PROGRESS_MARKER
MILITARY_TIMESTAMP_MIN_MS = SHARED_MILITARY_TIMESTAMP_MIN_MS
MILITARY_TIMESTAMP_MAX_MS = SHARED_MILITARY_TIMESTAMP_MAX_MS


