def parse_military_snapshot_from_packets(
    sess: dict[str, Any],
    packets: list[dict[str, Any]],
    http_code: int = 200,
) -> dict[str, Any]:
    """Build the 军情 snapshot shown on the 军情 page from 0x8600 packets."""
    generals = sess.get("generals") or []
    payloads = [
        packet["payload"]
        for packet in packets
        if packet.get("opcode") == MILITARY_SNAPSHOT_RESPONSE_OPCODE
        and "payload" in packet
    ]
    snapshot = shared_build_military_snapshot(
        payloads,
        generals,
        http_code,
        updated_at=now_ms(),
    )
    general_records = {
        int(record.get("id") or 0): dict(record)
        for record in snapshot.get("generalStatusRecords") or []
        if int(record.get("id") or 0) > 0
    }
    if general_records:
        existing_by_id = {
            int(record.get("id") or 0): dict(record)
            for record in (sess.get("generals") or [])
            if int(record.get("id") or 0) > 0
        }
        for general_id, record in general_records.items():
            existing_by_id[general_id] = {
                **existing_by_id.get(general_id, {}),
                **record,
            }
        sess["generals"] = list(existing_by_id.values())
        sess["militaryGeneralStatus"] = list(general_records.values())
    captive_records = list(snapshot.get("captiveGeneralRecords") or [])
    if captive_records:
        sess["capturedGenerals"] = captive_records
    sess["militarySnapshot"] = snapshot
    return snapshot


def refresh_military_snapshot(sess: dict[str, Any]) -> dict[str, Any]:
    """Pull the live 军情 list with the same 0x1600 request the client sends."""
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(MILITARY_SNAPSHOT_REQUEST_OPCODE, MILITARY_INTEL_REQUEST_PAYLOAD)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    snapshot = parse_military_snapshot_from_packets(sess, packets, code)
    persist_runtime_state()
    return snapshot


def wait_for_mine_garrison(
    sess: dict[str, Any],
    general_ids: list[str],
    *,
    battle_id: int,
    target: dict[str, Any] | None = None,
    max_wait_sec: int = 900,
    updated_after_ms: int = 0,
    task: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """等待战斗结束并以 0xa110 的“防”状态确认已经驻守矿点。"""
    started = time.time()
    saw_active = False
    polls = 0
    last_states: list[dict[str, Any]] = []
    while time.time() - started <= max(1, int(max_wait_sec)):
        sid = str(sess.get("sessionId") or "")
        if sid and SESSIONS.get(sid) is not sess:
            return {"confirmed": False, "reason": "账号会话已失效，停止等待驻守"}
        try:
            refresh_military_intel(sess)
        except Exception as exc:
            return {"confirmed": False, "reason": f"刷新将领状态失败：{exc}"}
        polls += 1
        current_update = int((sess.get("militaryIntel") or {}).get("updatedAt") or 0)
        if current_update <= int(updated_after_ms):
            time.sleep(2)
            continue
        last_states, missing = _selected_general_states(sess, general_ids)
        if missing:
            return {
                "confirmed": False,
                "reason": "状态响应中未找到出征将领：" + ",".join(missing),
                "generals": last_states,
            }
        statuses = [str(item.get("status") or "") for item in last_states]
        defending_states = [
            item for item in last_states if str(item.get("status") or "") == "防"
        ]
        battle_settled = bool(defending_states) and all(
            status in {"返", "闲", "防"} for status in statuses
        )
        if battle_settled:
            military_confirmation = query_mine_garrison_intel(
                sess,
                target or {},
                general_ids=general_ids,
                battle_id=battle_id,
            )
            if not military_confirmation.get("confirmed"):
                if task and (polls == 1 or polls % 3 == 0):
                    task_log(
                        task,
                        "将领已显示“防”，但军情尚未确认“驻守”，继续等待",
                    )
                time.sleep(5)
                continue
            if task:
                defending_names = "、".join(
                    str(item.get("name") or item.get("id") or "")
                    for item in defending_states
                )
                task_log(
                    task,
                    f"打矿战斗结束：battleId={battle_id}，"
                    f"军情已确认驻守；驻守将领={defending_names}",
                )
            return {
                "confirmed": True,
                "battleId": battle_id,
                "polls": polls,
                "elapsedSec": int(time.time() - started),
                "generals": last_states,
                "defendingGenerals": defending_states,
                "partialGarrison": len(defending_states) < len(last_states),
                "militaryIntel": military_confirmation,
            }
        if any(status in {"征", "战", "返", "防"} for status in statuses):
            saw_active = True
        if saw_active and statuses and all(status == "闲" for status in statuses):
            return {
                "confirmed": False,
                "battleId": battle_id,
                "battleFailed": True,
                "reason": "将领已回闲但从未进入“防/驻守”，本次战斗未成功占领资源点",
                "polls": polls,
                "generals": last_states,
            }
        if task and (polls == 1 or polls % 6 == 0):
            task_log(
                task,
                "等待打矿战斗/驻守："
                + "，".join(
                    f"{item.get('name')}={item.get('status')}" for item in last_states
                ),
            )
        time.sleep(5)
    return {
        "confirmed": False,
        "timeout": True,
        "battleId": battle_id,
        "reason": f"等待“防/驻守”状态超时({max_wait_sec}秒)，为避免误操作未召回",
        "polls": polls,
        "generals": last_states,
    }


def query_mine_garrison_intel(
    sess: dict[str, Any],
    target: dict[str, Any],
    *,
    general_ids: list[Any] | None = None,
    battle_id: int | None = None,
) -> dict[str, Any]:
    """以抓包确认的 0x1600 军情列表再次确认目标处于“驻守”。"""
    payload = MILITARY_INTEL_REQUEST_PAYLOAD
    code, data, packets = post_game(
        sess["gameHttp"],
        [(MILITARY_SNAPSHOT_REQUEST_OPCODE, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    texts = [
        printable(packet["payload"], 12000)
        for packet in packets
        if packet.get("opcode") == MILITARY_SNAPSHOT_RESPONSE_OPCODE and "payload" in packet
    ]
    events = [
        event
        for packet in packets
        if packet.get("opcode") == MILITARY_SNAPSHOT_RESPONSE_OPCODE and "payload" in packet
        for event in parse_8600_military_events(packet["payload"])
    ]
    text = " | ".join(texts)
    protocol_kind = str(
        target.get("protocolKind") or target.get("kind") or ""
    ).strip()
    if "牧场" in protocol_kind:
        protocol_kind = "牧场"
    coord_text = f"({int(target.get('x') or 0)},{int(target.get('y') or 0)})"
    compact_text = text.replace(" ", "")
    text_confirmed = bool(
        "驻守" in text
        and (not protocol_kind or protocol_kind in text)
        and (
            int(target.get("x") or 0) == 0
            or coord_text in compact_text
        )
    )
    expected_ids = mine_general_id_set(sess, general_ids or [])
    expected_battle_id = int(battle_id or 0)
    matching_events = [
        event
        for event in events
        if (
            not expected_ids
            or (
                set(int(value) for value in event.get("generalIds") or [])
                == expected_ids
            )
            or (
                expected_battle_id > 0
                and bool(event.get("generalIds"))
                and set(int(value) for value in event.get("generalIds") or [])
                < expected_ids
            )
        )
        and (
            expected_battle_id <= 0
            or int(event.get("battleId") or 0) == expected_battle_id
        )
        and (
            not protocol_kind
            or protocol_kind in str(event.get("targetName") or "")
        )
        and (
            int(target.get("x") or 0) == 0
            or (
                int(event.get("x") or 0) == int(target.get("x") or 0)
                and int(event.get("y") or 0) == int(target.get("y") or 0)
            )
        )
    ]
    # Once a formation is supplied, only an exact binary general-ID match is
    # strong enough to authorize recall. Text alone could describe another army.
    confirmed = bool(matching_events) if expected_ids else bool(
        matching_events or text_confirmed
    )
    return {
        "confirmed": confirmed,
        "http": code,
        "opcode": "0x1600/0x8600",
        "targetKind": protocol_kind,
        "targetCoord": [int(target.get("x") or 0), int(target.get("y") or 0)],
        "battleId": expected_battle_id or None,
        "textPreview": text[:1200],
        "events": events,
        "matchingEvents": matching_events,
        "responseBytes": len(data),
    }


def build_mine_recall_payload(battle_id: int) -> bytes:
    return shared_build_mine_recall_payload(battle_id)


def recall_mine_garrison(
    sess: dict[str, Any],
    battle_id: int,
    *,
    task: dict[str, Any] | None = None,
) -> dict[str, Any]:
    pending = next((
        item
        for item in sess.get("pendingMineGarrisons") or []
        if isinstance(item, dict)
        and int(item.get("battleId") or 0) == int(battle_id)
    ), {})
    tracked_general_ids = list(pending.get("generalIds") or [])
    before_states, _missing = _selected_general_states(sess, tracked_general_ids)
    defending_before = {
        int(item.get("id") or 0)
        for item in before_states
        if item.get("status") == "防" and int(item.get("id") or 0) > 0
    }
    payload = build_mine_recall_payload(battle_id)
    code, data, packets = post_game(
        sess["gameHttp"],
        [(MINE_WITHDRAW_REQUEST_OPCODE, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    candidates = [
        parse_8526_recall_response(packet["payload"], battle_id)
        for packet in packets
        if packet.get("opcode") == MINE_WITHDRAW_RESPONSE_OPCODE and "payload" in packet
    ]
    result = next(
        (candidate for candidate in candidates if candidate.get("success")),
        candidates[0] if candidates else {
            "success": False,
            "message": "未收到 0x8526 召回响应",
        },
    )
    if not result.get("success") and candidates and defending_before:
        try:
            refresh_generals(sess)
            after_states, _missing = _selected_general_states(
                sess,
                tracked_general_ids,
            )
            still_defending = {
                int(item.get("id") or 0)
                for item in after_states
                if item.get("status") == "防" and int(item.get("id") or 0) > 0
            }
            if not (defending_before & still_defending):
                result = {
                    **result,
                    "success": True,
                    "message": "召回请求已受理（将领状态已由防转为返/闲）",
                    "successEvidence": "general-status-transition",
                    "generals": after_states,
                }
        except Exception as exc:
            result["statusVerificationError"] = str(exc)
    result.update({
        "http": code,
        "payloadHex": payload.hex(),
        "responseBytes": len(data),
        "packets": summarize_packets(packets),
    })
    if task:
        task_log(
            task,
            (
                f"驻守召回已发送：battleId={battle_id}"
                if result.get("success")
                else f"驻守召回失败：{result.get('message')}"
            ),
        )
    return result


def wait_for_mine_generals_idle(
    sess: dict[str, Any],
    general_ids: list[str],
    *,
    max_wait_sec: int = 900,
    updated_after_ms: int = 0,
    task: dict[str, Any] | None = None,
) -> dict[str, Any]:
    started = time.time()
    polls = 0
    last_states: list[dict[str, Any]] = []
    while time.time() - started <= max(1, int(max_wait_sec)):
        try:
            # 0xa110 can keep reporting the pre-recall "防" code while the
            # authoritative 0x8004 role state has already changed to "返".
            refresh_generals(sess)
        except Exception as exc:
            return {"finished": False, "reason": f"召回后刷新将领状态失败：{exc}"}
        polls += 1
        last_states, missing = _selected_general_states(sess, general_ids)
        if missing:
            return {
                "finished": False,
                "reason": "召回状态响应中未找到将领：" + ",".join(missing),
                "generals": last_states,
            }
        if last_states and all(item.get("status") == "闲" for item in last_states):
            if task:
                task_log(task, "打矿召回完成：出征将领已全部回闲")
            return {
                "finished": True,
                "polls": polls,
                "elapsedSec": int(time.time() - started),
                "generals": last_states,
            }
        if task and (polls == 1 or polls % 6 == 0):
            task_log(
                task,
                "等待打矿将领返回："
                + "，".join(
                    f"{item.get('name')}={item.get('status')}" for item in last_states
                ),
            )
        time.sleep(5)
    return {
        "finished": False,
        "timeout": True,
        "reason": f"等待打矿将领回闲超时({max_wait_sec}秒)",
        "polls": polls,
        "generals": last_states,
    }


def recover_pending_mine_garrisons(
    sess: dict[str, Any],
    rows: list[dict[str, Any]],
    *,
    task: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    """Resume recall for mine formations whose in-memory worker was interrupted."""
    recovered: list[dict[str, Any]] = []
    refresh_military_intel(sess)
    for row_index, row in enumerate(rows):
        general_ids = list(row.get("generalIds") or [])
        expected_ids = mine_general_id_set(sess, general_ids)
        if not expected_ids:
            continue
        states, missing = _selected_general_states(sess, general_ids)
        if missing:
            continue
        statuses = [str(item.get("status") or "") for item in states]
        pending = next((
            item
            for item in sess.get("pendingMineGarrisons") or []
            if isinstance(item, dict)
            and mine_general_id_set(sess, list(item.get("generalIds") or []))
            == expected_ids
        ), None)

        defending_ids = {
            int(item.get("id") or 0)
            for item in states
            if item.get("status") == "防" and int(item.get("id") or 0) > 0
        }
        if pending is None and defending_ids:
            intel = query_mine_garrison_intel(
                sess,
                {},
                # 战斗后可能只有存活将领进入“防”，军情中的编队成员也只
                # 包含这些驻守将领；用当前“防”集合做精确匹配，避免因
                # 原配置5将、实际仅2将驻守而永远无法恢复召回。
                general_ids=list(defending_ids),
            )
            event = next(iter(intel.get("matchingEvents") or []), None)
            if event:
                target_name = str(event.get("targetName") or "")
                pending = remember_pending_mine_garrison(
                    sess,
                    battle_id=int(event["battleId"]),
                    general_ids=list(event.get("generalIds") or []),
                    target={
                        "id": event.get("targetId"),
                        "idHex": event.get("targetIdHex"),
                        "kind": target_name,
                        "protocolKind": (
                            "牧场" if "牧场" in target_name else target_name
                        ),
                        "x": event.get("x"),
                        "y": event.get("y"),
                    },
                    adopted=True,
                )
                record_success_action(
                    str(sess.get("sessionId") or ""),
                    "打矿",
                    f"出征 > {target_name or '资源点'}"
                    f"({event.get('x')}，{event.get('y')})（驻守恢复识别）",
                    detail={
                        "battleId": event.get("battleId"),
                        "recovered": True,
                    },
                )
                if task:
                    task_log(
                        task,
                        f"检测到遗留驻守：第 {row_index + 1} 条编队，"
                        f"当前防守将领 {len(defending_ids)} 名，"
                        f"battleId={event.get('battleId')}，准备自动召回",
                    )
        if pending is None:
            continue

        battle_id = int(pending.get("battleId") or 0)
        if battle_id <= 0:
            continue
        if task:
            task_log(
                task,
                f"恢复打矿闭环：battleId={battle_id}，"
                + "，".join(
                    f"{item.get('name')}={item.get('status')}" for item in states
                ),
            )
        if statuses and all(status == "闲" for status in statuses):
            forget_pending_mine_garrison(sess, battle_id)
            recovered.append({"battleId": battle_id, "alreadyIdle": True})
            continue

        target = (
            pending.get("target")
            if isinstance(pending.get("target"), dict)
            else {}
        )
        if any(status in {"征", "战", "防"} for status in statuses):
            garrison = wait_for_mine_garrison(
                sess,
                general_ids,
                battle_id=battle_id,
                target=target,
                max_wait_sec=4 * 60 * 60,
                task=task,
            )
            if not garrison.get("confirmed"):
                if garrison.get("battleFailed"):
                    forget_pending_mine_garrison(sess, battle_id)
                recovered.append({
                    "battleId": battle_id,
                    "success": False,
                    "reason": garrison.get("reason"),
                })
                continue
            recall = recall_mine_garrison(sess, battle_id, task=task)
            if not recall.get("success"):
                recovered.append({
                    "battleId": battle_id,
                    "success": False,
                    "reason": recall.get("message"),
                })
                continue

        returned = wait_for_mine_generals_idle(
            sess,
            general_ids,
            max_wait_sec=4 * 60 * 60,
            updated_after_ms=int(
                (sess.get("militaryIntel") or {}).get("updatedAt") or 0
            ),
            task=task,
        )
        if returned.get("finished"):
            forget_pending_mine_garrison(sess, battle_id)
        recovered.append({
            "battleId": battle_id,
            "success": bool(returned.get("finished")),
            "reason": returned.get("reason") or "",
        })
    return recovered


def _general_current_troops(general: dict[str, Any]) -> tuple[int | None, int]:
    code = general.get("soldierTypeCode")
    try:
        code_int = int(code) if code is not None else None
    except Exception:
        code_int = None
    try:
        count = int(general.get("soldierCount", general.get("currentSoldierCount", 0)) or 0)
    except Exception:
        count = 0
    return code_int, count


def raid_preflight_generals(
    sess: dict[str, Any],
    general_ids: list[str],
    task: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    return prepare_military_generals(sess, general_ids, "掠夺", task=task)


def normalize_raid_rows(sess: dict[str, Any], body: dict[str, Any]) -> list[dict[str, Any]]:
    planning_body = dict(body or {})
    planning_body["confirm"] = "raid"
    planning_body["knownGenerals"] = list(sess.get("generals") or [])
    plan = shared_settings_write_plan("/api/raid/execute", planning_body)
    return list((plan.get("response") or {}).get("executionRows") or [])


def wait_shared_core_operation(
    operation_id: str,
    *,
    task: dict[str, Any] | None = None,
    timeout_seconds: float = 300.0,
) -> dict[str, Any]:
    """Wait in a background worker for one already-submitted shared operation."""

    deadline = time.monotonic() + max(1.0, float(timeout_seconds))
    cancellation_requested = False
    while time.monotonic() < deadline:
        status_result = SHARED_PYTHON_CORE.operation_status(operation_id)
        operation = status_result.get("operation")
        if not isinstance(operation, dict):
            raise RuntimeError("共享 operation 状态不存在")
        status = str(operation.get("status") or "")
        if status not in {"QUEUED", "RUNNING"}:
            if status == "SUCCEEDED":
                result = operation.get("result")
                if not isinstance(result, dict):
                    raise RuntimeError("共享 operation 未返回结果对象")
                return result
            error = operation.get("error")
            error = error if isinstance(error, dict) else {}
            raise RuntimeError(
                str(error.get("message") or f"共享 operation 结束：{status}")
            )
        stop_event = task.get("stopEvent") if isinstance(task, dict) else None
        if (
            stop_event is not None
            and stop_event.is_set()
            and not bool(operation.get("requestSent"))
            and not cancellation_requested
        ):
            SHARED_PYTHON_CORE.cancel_operation(operation_id)
            cancellation_requested = True
        if stop_event is not None:
            stop_event.wait(0.05)
        else:
            time.sleep(0.05)
    raise RuntimeError("共享 operation 等待超过 300 秒")


def sync_shared_resident_automation(
    sess: dict[str, Any],
    *,
    started: bool | None = None,
) -> dict[str, Any]:
    """Hydrate the shared resident plan from the existing desktop habit store."""

    session_id = str(sess.get("sessionId") or "").strip()
    if not session_id:
        raise RuntimeError("同步共享常驻配置缺少账号")
    _desktop_sync_shared_account(session_id)
    configured = SHARED_PYTHON_CORE.configure_resident_automation_from_habits(
        session_id,
        load_account_habits(sess),
    )
    active_keys = _desktop_active_shared_resident_keys(session_id)
    activation = SHARED_PYTHON_CORE.set_resident_automation_activation(
        session_id,
        bool(sess.get("savedTasksStarted")) if started is None else bool(started),
        active_keys,
    )
    return {**configured, "activation": activation}


def _desktop_active_shared_resident_keys(session_id: str) -> list[str]:
    tasks = globals().get("AUTO_TASKS") or {}
    lock = globals().get("TASK_LOCK")

    def snapshot() -> list[dict[str, Any]]:
        return [
            dict(task)
            for task in tasks.values()
            if str(task.get("sessionId") or (task.get("config") or {}).get("sessionId") or "")
            == str(session_id)
            and str(task.get("status") or "")
            in {"starting", "running", "stopping"}
            and not bool(
                task.get("stopEvent") is not None
                and task["stopEvent"].is_set()
            )
        ]

    if lock is not None:
        with lock:
            active = snapshot()
    else:
        active = snapshot()
    keys = set()
    for task in active:
        task_type = str(task.get("type") or "")
        if task_type in {"auto-brush-yellow", "brush-yellow"}:
            keys.add("brushYellow")
        if task_type == "auto-mine":
            keys.add("mine")
        if task_type == "raid":
            keys.add("raid")
        if task_type == "lossless":
            keys.add("lossless")
        if task_type == "dungeon":
            keys.add("dungeon")
        if task_type == "auto-general":
            keys.add("general")
        if task_type == "auto-ministry":
            keys.add("ministry")
        if task_type == "auto-captives":
            keys.add("captives")
        if task_type in {"auto-domestic", "auto-technology"}:
            keys.add("domestic")
        if task_type == "auto-inventory":
            keys.add("inventory")
        if task_type == "auto-alarm":
            keys.add("alarm")
    return sorted(keys)


def desktop_shared_allowed_features(active_keys: list[str]) -> list[str]:
    """Translate active display rows into the core's execution allow-list."""

    output: list[str] = []
    for raw in active_keys:
        value = "brush" if str(raw) == "brushYellow" else str(raw)
        if value and value not in output:
            output.append(value)
    # Daily work shares the account lane but has no resident display row.
    if "daily" not in output:
        output.append("daily")
    return output


def try_sync_shared_resident_automation(
    sess: dict[str, Any],
) -> dict[str, Any]:
    try:
        return sync_shared_resident_automation(sess)
    except Exception as error:
        return {
            "ok": False,
            "changed": False,
            "error": str(error) or error.__class__.__name__,
        }


def _shared_resident_pending(session_id: str) -> bool:
    try:
        account = json.loads(
            SHARED_PYTHON_CORE.account_record_json(str(session_id))
        ).get("account") or {}
        public = ((account.get("session") or {}).get("publicState") or {})
        for field in (
            "minePendingGarrisonJson",
            "losslessPendingBattleJson",
            "brushPendingRecoveryJson",
            "raidPendingReturnJson",
            "dungeonPendingRunJson",
            "generalMaintenancePendingJson",
            "ministryPendingPlantJson",
            "captivesPendingActionJson",
            "domesticPendingActionJson",
            "inventoryPendingActionJson",
            "alarmPendingEventsJson",
        ):
            value = json.loads(str(public.get(field) or "{}"))
            if isinstance(value, dict) and value:
                return True
    except Exception:
        return False
    return False


def _shared_resident_pending_features(
    session_id: str,
    *,
    strict: bool = False,
) -> list[str]:
    """Return feature identities for every durable resident ledger."""

    fields = (
        ("alarmPendingEventsJson", "alarm"),
        ("minePendingGarrisonJson", "mine"),
        ("losslessPendingBattleJson", "lossless"),
        ("brushPendingRecoveryJson", "brush"),
        ("raidPendingReturnJson", "raid"),
        ("dungeonPendingRunJson", "dungeon"),
        ("generalMaintenancePendingJson", "general"),
        ("ministryPendingPlantJson", "ministry"),
        ("captivesPendingActionJson", "captives"),
        ("domesticPendingActionJson", "domestic"),
        ("inventoryPendingActionJson", "inventory"),
    )
    try:
        account = json.loads(
            SHARED_PYTHON_CORE.account_record_json(str(session_id))
        ).get("account") or {}
        public = ((account.get("session") or {}).get("publicState") or {})
        features = []
        for field, feature in fields:
            value = json.loads(str(public.get(field) or "{}"))
            if isinstance(value, dict) and value and feature not in features:
                features.append(feature)
        return features
    except Exception:
        if strict:
            raise
        return []


def _shared_brush_mine_pending(session_id: str) -> bool:
    """Compatibility alias for older desktop tests and dead workers."""

    return _shared_resident_pending(session_id)


def execute_shared_resident_automation_tick(
    sess: dict[str, Any],
    *,
    task: dict[str, Any] | None = None,
    configured_execution_allowed: bool = True,
    allowed_features: list[str] | None = None,
    daily_allowed_keys: list[str] | None = None,
    operator_reconcile_features: list[str] | None = None,
) -> dict[str, Any]:
    """Submit/wait one Python-owned resident tick."""

    session_id = str(sess.get("sessionId") or "").strip()
    if not session_id:
        raise RuntimeError("共享常驻 tick 缺少账号")
    _desktop_sync_shared_account(session_id)
    tick_at = now_ms()
    request_context: dict[str, Any] = {
        "requestId": f"desktop-resident-{session_id}-{tick_at}",
        "source": "desktop-resident-scheduler",
        "platform": "desktop",
        "allowedFeatures": list(
            allowed_features
            if allowed_features is not None
            else [
                "mine", "lossless", "brush", "raid", "dungeon",
                "general", "ministry", "captives", "domestic", "inventory",
                "alarm", "daily",
            ]
        ),
        "configuredExecutionAllowed": bool(configured_execution_allowed),
    }
    if daily_allowed_keys is not None:
        request_context["dailyAllowedKeys"] = list(daily_allowed_keys)
    if operator_reconcile_features is not None:
        request_context["operatorReconcileFeatures"] = list(
            operator_reconcile_features
        )
    submitted = SHARED_PYTHON_CORE.submit_automation_recovery_tick(
        session_id,
        tick_key=(
            f"desktop-resident-{session_id}-{tick_at}-{threading.get_ident()}"
        ),
        request_context=request_context,
    )
    result = wait_shared_core_operation(
        str(submitted["operationId"]),
        task=task,
        timeout_seconds=900.0,
    )
    if not isinstance(result, dict):
        raise RuntimeError("共享常驻 tick 未返回结果对象")
    return dict(result)


OPERATOR_RECONCILIATION_CONFIRM = "reconcile-uncertain-expeditions"
