def dungeon_generals_are_idle(sess: dict[str, Any], general_ids: list[str]) -> bool:
    ids = [str(x or "").strip() for x in general_ids if str(x or "").strip()]
    if not ids:
        return False
    generals = sess.get("generals") or []
    selected = []
    for gid in ids:
        general = next((
            item for item in generals
            if str(item.get("id")) == gid or str(item.get("idHex")) == gid
        ), None)
        if not general:
            return False
        selected.append(general)
    return bool(selected) and all(
        (general.get("displayStatus") or general.get("statusText")) == "闲"
        for general in selected
    )


