def update_military_intel_from_packets(sess: dict[str, Any], packets: list[dict[str, Any]], http_code: int = 200, persist: bool = False) -> dict[str, Any]:
    generals = sess.get("generals") or []
    merged = {"sourceOpcode": "0x3110/0xa110", "events": [], "statusByName": {}, "statusById": {}, "generalStatusRecords": [], "updatedAt": now_ms(), "http": http_code}
    for pkt in packets:
        if pkt.get("opcode") != 0xA110 or "payload" not in pkt:
            continue
        parsed = parse_military_intel_from_a110(pkt["payload"], generals)
        for event in parsed.get("events") or []:
            merged["events"].append(event)
        for name, state in (parsed.get("statusByName") or {}).items():
            merged["statusByName"][name] = state
        for gid, state in (parsed.get("statusById") or {}).items():
            merged["statusById"][gid] = state
        for record in parsed.get("generalStatusRecords") or []:
            merged["generalStatusRecords"].append(record)
    sess["militaryIntel"] = merged
    apply_military_status_to_generals(sess)
    if persist:
        persist_runtime_state()
    return merged


def apply_military_status_to_generals(sess: dict[str, Any]) -> None:
    intel = sess.get("militaryIntel") or {}
    intel_updated_at = int(intel.get("updatedAt") or 0)
    status_by_name = intel.get("statusByName") or {}
    status_by_id = intel.get("statusById") or {}
    records_by_id = {}
    for record in intel.get("generalStatusRecords") or []:
        if record.get("id") is not None:
            records_by_id[str(record.get("id"))] = record
        if record.get("idHex"):
            records_by_id[str(record.get("idHex"))] = record
    generals = sess.get("generals") or []
    for g in generals:
        name = str(g.get("name") or "")
        gid = str(g.get("id") or "")
        gid_hex = str(g.get("idHex") or "")
        state = status_by_id.get(gid) or status_by_id.get(gid_hex) or status_by_name.get(name)
        record = records_by_id.get(gid) or records_by_id.get(gid_hex) or {}
        role_state_updated_at = int(g.get("roleStateStatusUpdatedAt") or 0)
        role_state = (
            str(g.get("roleStateStatusText") or "")
            or general_status_text_from_code(g.get("roleStateStatusCode", g.get("status")))
        )
        if state:
            g["a110StatusKnown"] = True
            g["a110StatusCode"] = record.get("statusCode")
            g["a110StatusText"] = state
            g["a110StatusUpdatedAt"] = intel_updated_at
            g["a110StatusSource"] = record.get("source") or "0x3110/0xa110-general-status"
        else:
            g["a110StatusKnown"] = False
            g.pop("a110StatusCode", None)
            g.pop("a110StatusText", None)
            g.pop("a110StatusUpdatedAt", None)
            g.pop("a110StatusSource", None)

        # 0x8004 是一次完整快照；只有真正更新的 0xa110 才能覆盖它。
        # 不能再把旧心跳缓存写回刚刷新的完整状态。
        use_a110 = bool(state) and intel_updated_at > role_state_updated_at
        effective_state = str(state) if use_a110 else role_state
        g["displayStatus"] = effective_state
        g["statusText"] = effective_state
        g["busy"] = effective_state != "闲"
        g["effectiveStatusSource"] = "0xa110" if use_a110 else "0x8004"
        g["effectiveStatusUpdatedAt"] = (
            intel_updated_at if use_a110 else role_state_updated_at
        )
        if use_a110 and record.get("statusCode") is not None:
            g["status"] = record.get("statusCode")
            g["heroStatusCode"] = record.get("statusCode")
            g["stateCode56"] = record.get("statusCode")
        if use_a110 and record.get("rawStatus58") is not None:
            g["rawStatus58"] = record.get("rawStatus58")
            g["status58"] = record.get("status58")
        g.pop("a110TaskA", None)
        g.pop("a110TaskB", None)
    with GENERAL_STATE_CONDITION:
        GENERAL_STATE_CONDITION.notify_all()


def refresh_military_intel(sess: dict[str, Any]) -> dict[str, Any]:
    code, data, packets = post_game(sess["gameHttp"], [(0x3110, b"\x01\x00")], int(sess["dm"]), account_id=str(sess.get("sessionId") or ""))
    return update_military_intel_from_packets(sess, packets, code, persist=True)


