def item_names_by_id() -> dict[int, str]:
    global ITEM_NAMES_BY_ID
    if ITEM_NAMES_BY_ID is not None:
        return ITEM_NAMES_BY_ID
    names = dict(ITEM_NAME_FALLBACK)
    try:
        data = json.loads(ITEM_MAPPING_FILE.read_text(encoding="utf-8-sig"))
        for row in data if isinstance(data, list) else []:
            item_id = int(row.get("item_id"))
            name = str(row.get("name") or "").strip()
            if name:
                names[item_id] = name
    except Exception:
        pass
    ITEM_NAMES_BY_ID = names
    return names


def equipment_templates_by_id() -> dict[int, dict[str, Any]]:
    global EQUIPMENT_TEMPLATES_BY_ID
    if EQUIPMENT_TEMPLATES_BY_ID is not None:
        return EQUIPMENT_TEMPLATES_BY_ID
    templates: dict[int, dict[str, Any]] = {}
    try:
        with EQUIPMENT_MAPPING_FILE.open("r", encoding="utf-8-sig", newline="") as handle:
            for row in csv.DictReader(handle):
                template_id = int(row.get("template_id_In") or -1)
                if template_id < 0:
                    continue
                templates[template_id] = {
                    "templateId": template_id,
                    "name": str(row.get("name_Mn") or f"装备#{template_id}").strip(),
                    "level": int(row.get("level_Kn") or 0),
                    "typeCode": int(row.get("stat_type_Nn") or -1),
                    "famous": bool(int(row.get("famous_flag_Jn") or 0)),
                    "description": str(row.get("description_On") or "").strip(),
                }
    except Exception:
        pass
    EQUIPMENT_TEMPLATES_BY_ID = templates
    return templates


