def execute_food_to_copper(sess: dict[str, Any], food_amount: int, *, confirm: str = "") -> dict[str, Any]:
    if confirm != "food-to-copper":
        raise RuntimeError("真实粮食转铜需要 confirm=food-to-copper")
    payload = build_resource_exchange_payload(1, int(food_amount))
    code, data, packets = post_game(
        sess["gameHttp"],
        [(0x1152, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p["payload"] for p in packets if p.get("opcode") == 0x8152 and "payload" in p), None)
    parsed = parse_resource_exchange_response(response) if response is not None else {
        "success": False,
        "message": "未收到 0x8152 粮食转铜响应",
    }
    if parsed.get("success"):
        role_state = sess.setdefault("roleState", {})
        if parsed.get("copper") is not None:
            role_state["copper"] = parsed["copper"]
        if parsed.get("food") is not None:
            role_state["food"] = parsed["food"]
    return {
        **parsed,
        "direction": "food-to-copper",
        "foodAmount": int(food_amount),
        "expectedCopper": int(food_amount) * 3 // 10,
        "http": code,
        "payloadHex": payload.hex(),
    }


