def fetch_passport_area_list(
    username: str,
    password: str,
    platform: Any = None,
) -> tuple[str, str, list[dict[str, str]]]:
    profile = platform_profile(platform)
    params: dict[str, Any] = {
        "username": username,
        "password": password,
        "channelId": profile["channel"],
        "source": SOURCE,
        "cType": CTYPE,
        "cVersion": VERSION,
        "gameKey": GAME_KEY,
        "target": TARGETS,
    }
    if profile.get("auth") == "downjoy_sdk":
        sdk_login = downjoy_sdk_login(username, password)
        # Exact DangleYAPI callback data flow:
        # P=umid, Q=urlEncode(LoginInfo.userName), O=token. The bundled
        # Downjoy SDK constructs successful LoginInfo with userName="".
        params.update({
            "session": sdk_login["token"],
            "username": sdk_login["umid"],
            "password": sdk_login["callbackUsername"],
            "imei": "",
            "macId": "",
        })
    text = http_get(
        str(profile["passport"]) + "common/area/list.action",
        params,
    )
    return parse_passport_area_list(text)


def area_catalog_signature(areas: list[dict[str, Any]]) -> str:
    return shared_area_catalog_signature(areas)


def read_area_catalog(platform: Any = None) -> dict[str, Any]:
    if not ACCOUNT_STATE_DB_READY:
        return {"areas": [], "updatedAt": None, "count": 0}
    platform_key = normalize_platform_key(platform)
    with AREA_CATALOG_LOCK, ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(
            """
            SELECT target, area_id, area_name, server_url, server_key, updated_at
            FROM area_catalog
            WHERE platform=?
            ORDER BY server_key, area_id, area_name
            """,
            (platform_key,),
        ).fetchall()
    areas = [{
        "target": str(row["target"] or ""),
        "areaId": str(row["area_id"] or ""),
        "areaName": str(row["area_name"] or ""),
        "serverUrl": str(row["server_url"] or ""),
        "serverKey": str(row["server_key"] or ""),
    } for row in rows]
    return {
        "areas": areas,
        "updatedAt": max((int(row["updated_at"]) for row in rows), default=None),
        "count": len(areas),
        "platform": platform_display_name(platform_key),
        "platformKey": platform_key,
    }


def sync_area_catalog_to_cloud(catalog: dict[str, Any]) -> None:
    """Publish the complete public snapshot without blocking the local UI."""

    try:
        SHARED_PYTHON_CORE._schedule_cloud_directory_sync(  # noqa: SLF001
            str(catalog.get("platformKey") or catalog.get("platform") or ""),
            list(catalog.get("areas") or []),
        )
    except Exception as error:
        system_log(
            f"共享区服目录同步未启动：{error}",
            level="warning",
            source="area-catalog",
        )


def update_area_catalog_if_changed(
    areas: list[dict[str, Any]],
    platform: Any = None,
) -> bool:
    platform_key = normalize_platform_key(platform)
    clean_areas: list[dict[str, str]] = []
    by_identity: dict[tuple[str, str, str], dict[str, str]] = {}
    for area in areas:
        area_name = str(area.get("areaName") or "").strip()
        if not area_name:
            continue
        area_id = str(area.get("areaId") or "")
        server_key = str(area.get("serverKey") or "")
        identity = (server_key, area_id, area_name)
        target = str(area.get("target") or "")
        existing = by_identity.get(identity)
        if existing:
            targets = [x for x in existing.get("target", "").split(",") if x]
            if target and target not in targets:
                existing["target"] = ",".join([*targets, target])
            continue
        item = {
            "target": target,
            "areaId": area_id,
            "areaName": area_name,
            "serverUrl": str(area.get("serverUrl") or ""),
            "serverKey": server_key,
        }
        by_identity[identity] = item
        clean_areas.append(item)
    with AREA_CATALOG_LOCK:
        current = read_area_catalog(platform_key)
        if area_catalog_signature(current.get("areas") or []) == area_catalog_signature(clean_areas):
            return False
        updated_at = now_ms()
        with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            try:
                connection.execute(
                    "DELETE FROM area_catalog WHERE platform=?",
                    (platform_key,),
                )
                connection.executemany(
                    """
                    INSERT INTO area_catalog
                        (platform, server_key, area_id, area_name, target, server_url, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?)
                    """,
                    [(
                        platform_key,
                        area["serverKey"], area["areaId"], area["areaName"],
                        area["target"], area["serverUrl"], updated_at,
                    ) for area in clean_areas],
                )
                connection.execute("COMMIT")
            except Exception:
                connection.execute("ROLLBACK")
                raise
    system_log(
        f"{platform_display_name(platform_key)}区服目录已更新：共 {len(clean_areas)} 个区服",
        source="area-catalog",
    )
    sync_area_catalog_to_cloud(read_area_catalog(platform_key))
    return True


def find_login_area(areas: list[dict[str, str]], server_query: str) -> dict[str, str] | None:
    return shared_find_login_area(areas, server_query)


def fresh_login(
    username: str,
    password: str,
    server_query: str = "",
    account_id: str | None = None,
    *,
    allow_reconnecting: bool = False,
    create_role_if_missing: bool = False,
    platform: Any = None,
) -> dict[str, Any]:
    profile = platform_profile(platform)
    platform_key = str(profile["key"])
    server_query = str(server_query or default_server_query(platform_key)).strip()
    session, user_id, areas = fetch_passport_area_list(
        username,
        password,
        platform_key,
    )
    update_area_catalog_if_changed(areas, platform_key)
    area = find_login_area(areas, server_query)
    if not area:
        raise RuntimeError("未找到区服：" + server_query)
    enter = http_get(
        str(profile["passport"]) + "common/area/enter.action",
        dict(session=session, areaKey=area["serverKey"]),
    ).strip()
    if enter != "1":
        raise RuntimeError("进入区服失败：" + enter)
    game_http = area["serverUrl"].rstrip("/") + "/kingWapServer/HttpClient"
    code, data, packets = post_game(
        game_http,
        [(0x1003, utf(user_id) + utf(session) + utf(str(profile["channel"])))],
        0,
        account_id=account_id,
        allow_reconnecting=allow_reconnecting,
        platform=platform_key,
    )
    p8003 = next((p for p in packets if p.get("opcode") == 0x8003), None)
    if not p8003:
        raise GameProtocolResponseError(
            "0x1003 未返回 0x8003，且未发现已确认的登录拒绝帧："
            + json.dumps(summarize_packets(packets), ensure_ascii=False)
        )
    info = parse8003(p8003["payload"])
    if (
        info["status"] != 0
        and create_role_if_missing
        and "角色" in str(info.get("message") or "")
    ):
        # 已有无痕抓包确认：0x1007 body=UTF角色名+i16头像(7)+i64阵营(1)，
        # 成功返回0x8007 status=0/“角色创建成功”。仅起号模式允许进入此分支。
        seed = int(hashlib.sha256(f"{platform_key}:{username}:{server_query}".encode()).hexdigest()[:12], 16)
        family = "赵钱孙李周吴郑王冯陈褚卫蒋沈韩杨朱秦许何吕施张孔曹严华金魏陶姜"
        given = "天宇文武明杰浩然俊豪志远博雅承安景行修远星河云舟"
        create_errors: list[str] = []
        for attempt in range(8):
            value = seed + attempt * 7919
            role_name = (
                family[value % len(family)]
                + given[(value // len(family)) % len(given)]
                + given[(value // (len(family) * len(given))) % len(given)]
            )
            _create_code, _create_data, create_packets = post_game(
                game_http,
                [(0x1007, utf(role_name) + struct.pack(">hq", 7, 1))],
                int(info["dm"]),
                account_id=account_id,
                allow_reconnecting=allow_reconnecting,
                platform=platform_key,
            )
            p8007 = next((p for p in create_packets if p.get("opcode") == 0x8007), None)
            parsed_create = (
                parse_status_message_payload(p8007.get("payload") or b"")
                if p8007 else
                {"success": False, "message": "未收到0x8007"}
            )
            if parsed_create.get("success"):
                system_log(
                    f"起号账号 {username}@{server_query} 自动创建角色成功：{role_name}",
                    source="starter",
                )
                code, data, packets = post_game(
                    game_http,
                    [(0x1003, utf(user_id) + utf(session) + utf(str(profile["channel"])))],
                    0,
                    account_id=account_id,
                    allow_reconnecting=allow_reconnecting,
                    platform=platform_key,
                )
                p8003 = next((p for p in packets if p.get("opcode") == 0x8003), None)
                if not p8003:
                    raise GameProtocolResponseError("创建角色后重新登录未收到0x8003")
                info = parse8003(p8003["payload"])
                break
            create_errors.append(str(parsed_create.get("message") or "创建失败"))
        else:
            raise RuntimeError("自动创建角色失败：" + "；".join(create_errors[-3:]))
    if info["status"] != 0:
        raise GameServerRejected(
            f"游戏服登录失败：0x8003 status={info['status']}；{info.get('message', '')}"
        )
    role = info["roles"][max(0, int(info["selected"]))] if info["roles"] else None
    if not role:
        raise RuntimeError("账号在该区服无角色")
    post_game(
        game_http,
        [(0x1004, struct.pack(">q", -1))],
        int(info["dm"]),
        account_id=account_id,
        allow_reconnecting=allow_reconnecting,
        platform=platform_key,
    )
    code2, data2, packets2 = post_game(
        game_http,
        [(0x1016, struct.pack(">q", int(role["roleId"])))],
        int(info["dm"]),
        account_id=account_id,
        allow_reconnecting=allow_reconnecting,
        platform=platform_key,
    )
    p8004 = next((p for p in packets2 if p.get("opcode") == 0x8004), None)
    if not p8004:
        raise GameProtocolResponseError(
            "0x1016 未返回 0x8004 角色状态，且未发现0x8016或已抓包确认的拒绝帧："
            + json.dumps(summarize_packets(packets2), ensure_ascii=False)
        )
    state8004 = p8004["payload"].hex() if p8004 else ""
    role_state = parse_8004_head(p8004["payload"], "0x1016/0x8004") if p8004 else {}
    generals = recover_generals_from_8004(state8004) if state8004 else []
    army_state = parse_idle_army_from_8004(state8004, generals) if state8004 else []
    if role_state is not None:
        role_state["idleArmy"] = army_state
    inventory_state = {"items": []}
    try:
        _code_inv, _data_inv, packets_inv = post_game(
            game_http,
            [(0x1104, b"\x00")],
            int(info["dm"]),
            account_id=account_id,
            allow_reconnecting=allow_reconnecting,
            platform=platform_key,
        )
        p8104 = next((p for p in packets_inv if p.get("opcode") == 0x8104), None)
        if p8104:
            inventory_state = parse_8104_inventory(p8104["payload"], "0x1104/0x8104")
    except (GameServerRejected, GameServerThrottled):
        raise
    except Exception as e:
        inventory_state = {"items": [], "parseError": str(e), "sourceOpcode": "0x1104/0x8104"}
    sid = uuid4().hex
    sess = {
        "sessionId": sid,
        "username": username,
        "platform": str(profile["name"]),
        "platformKey": platform_key,
        "gameHttp": game_http,
        "dm": int(info["dm"]),
        "role": role,
        "roleState": role_state,
        "inventory": inventory_state,
        "area": area,
        "passportSession": session,
        "userId": user_id,
        "state8004PayloadHex": state8004,
        "generals": generals,
        "army": army_state,
        "createdAt": now_ms(),
        "lastTargets": [],
    }
    SESSIONS[sid] = sess
    ensure_account_for_session(sess)
    # The account record is migrated from the temporary/local session id only
    # after fresh_login returns. Querying own fiefs here would be rejected by
    # the account request gate. start_account performs this query immediately
    # after that migration instead.
    try:
        refresh_daily_activity(sess)
    except Exception:
        pass
    apply_account_habits_to_session(sess)
    sess["savedCommonTasksStarted"] = False
    sess["savedTasksStarted"] = False
    sess["savedTasksStartedAt"] = None
    account_log(sid, "真实登录成功并已加载该账号保存习惯", source="server")
    persist_runtime_state()
    return sess


def get_session(sid: str) -> dict[str, Any]:
    sess = SESSIONS.get(sid)
    if not sess:
        raise RuntimeError("session 不存在或已过期，请重新登录")
    return sess


def get_local_settings_context(sid: str) -> tuple[dict[str, Any], bool]:
    """Resolve local persistence identity without requiring a live game session."""

    session_id = str(sid or "").strip()
    if not session_id:
        raise RuntimeError("缺少 sessionId")
    live = SESSIONS.get(session_id)
    if isinstance(live, dict):
        return live, True
    with ACCOUNT_LOCK:
        account = dict(ACCOUNTS.get(session_id) or {})
    if not account:
        raise RuntimeError("账号不存在")
    return {
        "sessionId": session_id,
        "username": account.get("username"),
        "area": deepcopy(account.get("area") or {}),
        "serverQuery": account.get("serverQuery"),
        "platform": account.get("platform"),
        "role": deepcopy(account.get("role") or {}),
        "roleState": {},
        "generals": [],
    }, False


