def query_national_cities(
    sess: dict[str, Any],
    categories: tuple[int, ...] | list[int] | None = None,
) -> list[dict[str, Any]]:
    selected_categories = tuple(dict.fromkeys(
        int(category) for category in (categories or DAILY_NATIONAL_CATEGORIES)
    ))
    if any(int(category) not in DAILY_NATIONAL_CATEGORIES for category in selected_categories):
        raise ValueError("国家城池查询禁止包含小城分类4")
    cities_by_name: dict[str, dict[str, Any]] = {}
    for category in selected_categories:
        page = 1
        total_pages = 1
        while page <= total_pages and page <= DAILY_NATIONAL_MAX_PAGES:
            payload = build_national_city_list_payload(int(category), page)
            code, _data, packets = post_game(
                sess["gameHttp"],
        [(DAILY_NATIONAL_LIST_OPCODE, payload)],
                int(sess["dm"]),
                account_id=str(sess.get("sessionId") or ""),
            )
            response = next((p for p in packets if p.get("opcode") == DAILY_NATIONAL_LIST_RESPONSE_OPCODE), None)
            if response is None:
                raise GameProtocolResponseError(
                    f"国家城池列表未收到0x8404：category={category} page={page} http={code}"
                )
            parsed = parse_national_city_page(response.get("payload") or b"", int(category))
            if int(parsed.get("status") or 0) != 0:
                raise GameApplicationResponseError(
                    f"国家城池列表被服务器拒绝：category={category} status={parsed.get('status')}"
                )
            total_pages = max(1, int(parsed.get("totalPages") or 1))
            for city in parsed.get("cities") or []:
                name = str(city.get("name") or "").strip()
                kind = str(city.get("kind") or "unknown")
                if not name or kind not in {"state", "commandery", "county"}:
                    continue
                city["queryCategory"] = int(category)
                cities_by_name.setdefault(name, city)
            if not parsed.get("cities") and page >= total_pages:
                break
            page += 1
    return list(cities_by_name.values())


def _daily_city_name(city: dict[str, Any] | str) -> str:
    if isinstance(city, dict):
        # 0x8310 owned-fief records expose both a display fief name (for
        # example “广成关封地”) and the actual city name (“广成关”).  The
        # collection endpoints accept the latter.  National-city records
        # populate both fields with the same value, so preferring cityName is
        # safe for both callers and prevents城主征收 from submitting a fief
        # label that the game cannot resolve as a city.
        return str(city.get("cityName") or city.get("city") or city.get("name") or "").strip()
    return str(city or "").strip()


def query_national_collect_status(sess: dict[str, Any], city: dict[str, Any] | str) -> dict[str, Any]:
    city_name = _daily_city_name(city)
    payload = build_national_city_status_payload(city_name)
    code, _data, packets = post_game(
        sess["gameHttp"],
        [(DAILY_NATIONAL_STATUS_OPCODE, payload)],
        int(sess["dm"]),
        account_id=str(sess.get("sessionId") or ""),
    )
    response = next((p for p in packets if p.get("opcode") == DAILY_NATIONAL_STATUS_RESPONSE_OPCODE), None)
    if response is None:
        raise GameProtocolResponseError(f"{city_name}征收状态未收到0x8332：http={code}")
    parsed = parse_national_collect_status(response.get("payload") or b"")
    parsed["city"] = city_name
    return parsed


def collect_national_city(sess: dict[str, Any], city: dict[str, Any] | str) -> dict[str, Any]:
    city_name = _daily_city_name(city)
