def brush_cached_general_wait_state(
    sess: dict[str, Any],
    brush_rules: list[dict[str, Any]],
) -> tuple[bool, list[str], str]:
    """Describe whether cached role state blocks every configured brush formation."""
    general_ids = list(dict.fromkeys(
        str(general_id)
        for rule in brush_rules
        for general_id in rule.get("generalIds") or []
        if str(general_id or "").strip()
    ))
    states = cached_general_states(sess, general_ids)
    waiting = (
        len(states) != len(general_ids)
        or any(
            not item.get("found") or item.get("status") != "闲"
            for item in states
        )
    )
    summary = "，".join(
        f"{item.get('name')}={item.get('status')}"
        for item in states
    ) or "未取得将领状态"
    return waiting, general_ids, summary


def execute_assign_troops(
    sess: dict[str, Any],
    general_id: str,
    soldier_type: Any,
    soldier_count: int,
    *,
    group: int = 0,
    confirm: str = "",
    precheck: bool = True,
) -> dict[str, Any]:
    if confirm != "assign-troops":
        raise RuntimeError("真实配兵需要 confirm=assign-troops")
    try:
        generals = refresh_generals(sess)
    except Exception:
        generals = sess.get("generals") or []
    general = next((g for g in generals if str(g.get("id")) == str(general_id) or str(g.get("idHex")) == str(general_id)), None)
    if not general:
        raise RuntimeError(f"未找到配兵将领：{general_id}")
    requested_count = int(soldier_count)
    try:
        troop_limit = int(general.get("troopLimit") or general.get("daiBingLimit") or 0)
    except Exception:
        troop_limit = 0
    soldier_count = min(requested_count, troop_limit) if troop_limit > 0 and requested_count > 0 else requested_count
    if requested_count != soldier_count:
        account_log(
            str(sess.get("sessionId") or ""),
            f"{general.get('name') or general_id} 配兵配置为 {requested_count}，当前统兵上限 {troop_limit}，自动按 {soldier_count} 配兵",
            source="troops",
        )
    if precheck:
        unsafe_reason = troop_assignment_precheck(sess, general, soldier_type, int(soldier_count))
        if unsafe_reason:
            raise RuntimeError(unsafe_reason)
    payload = build_assign_troops_payload(general.get("idHex") or f"{int(general['id']):016x}", soldier_type, soldier_count, group=group)
    code, data, packets = post_game(sess["gameHttp"], [(FORMATION_ASSIGN_REQUEST_OPCODE, payload)], int(sess["dm"]), account_id=str(sess.get("sessionId") or ""))
    response_payloads = [p["payload"] for p in packets if p.get("opcode") == FORMATION_ASSIGN_RESPONSE_OPCODE and "payload" in p]
    parsed = parse_assign_troops_response(response_payloads[0]) if response_payloads else {"success": False, "message": "未收到 0x8226 配兵响应"}
    target_code = soldier_type_code(soldier_type)
    target_count = int(soldier_count)
    protocol_success = bool(parsed.get("success"))
    semantic_success = protocol_success
    semantic_message = parsed.get("message") or parsed.get("textPreview") or ""
    if protocol_success and target_count > 0:
        actual_code = parsed.get("assignedSoldierTypeCode")
        actual_count = parsed.get("assignedSoldierCount")
        try:
            actual_code_int = int(actual_code)
            actual_count_int = int(actual_count)
        except Exception:
            actual_code_int = None
            actual_count_int = None
        if actual_code_int != target_code or actual_count_int != target_count:
            semantic_success = False
            inv = parsed.get("soldierInventory") or []
            inv_desc = "、".join(
                f"{soldier_type_name(x.get('soldierTypeCode', x.get('soldierType')))}={x.get('amount')}"
                for x in inv
            )
            inventory_suffix = f"；当前可用闲兵：{inv_desc}" if inv_desc else ""
            actual_desc = (
                f"{actual_count_int if actual_count_int is not None else '未知'}"
                f"{soldier_type_name(actual_code_int) if actual_code_int is not None else '未知兵种'}"
            )
            semantic_message = (
                f"配兵未达到目标：请求 {target_count}{soldier_type_name(target_code)}，"
                f"服务器实际返回 {actual_desc}{inventory_suffix}"
            )
            parsed["protocolSuccess"] = True
            parsed["semanticSuccess"] = False
            parsed["success"] = False
            parsed["message"] = semantic_message
    report = {
        "time": now_ms(),
        "role": sess["role"],
        "area": sess["area"],
        "general": {"id": general.get("id"), "idHex": general.get("idHex"), "name": general.get("name")},
        "opcode": "0x1226",
        "payloadHex": payload.hex(),
        "requested": {"soldierType": soldier_type, "soldierTypeCode": target_code, "soldierCount": target_count, "group": int(group)},
        "http": code,
        "responseBytes": len(data),
        "packets": summarize_packets(packets),
        "parsed": parsed,
        "success": bool(semantic_success),
        "protocolSuccess": protocol_success,
        "message": semantic_message,
    }
    report["reportFile"] = ""
    if protocol_success:
        try:
            refresh_generals(sess)
        except Exception:
            pass
    return report


def unassign_all_idle_generals(sess: dict[str, Any], *, task: dict[str, Any] | None = None) -> dict[str, Any]:
    """逐个卸下所有空闲将领的兵，忙碌将领安全跳过。"""
    generals = refresh_generals(sess)
    cleared = 0
    skipped = 0
    results: list[dict[str, Any]] = []
    for general in list(generals or []):
        gid = str(general.get("id") or general.get("idHex") or "")
        code, count = _general_current_troops(general)
        status = general.get("displayStatus") or general.get("statusText") or "未知"
        if not gid or code is None or code < 0 or count <= 0:
            continue
        if status != "闲":
            skipped += 1
            results.append({"generalId": gid, "name": general.get("name"), "success": False, "skipped": True, "reason": f"状态={status}"})
            continue
        result = execute_assign_troops(
            sess, gid, code, 0, confirm="assign-troops", precheck=False,
        )
        success = bool(result.get("success"))
        cleared += int(success)
        results.append({"generalId": gid, "name": general.get("name"), "success": success, "message": result.get("message") or ""})
        if task:
            task_log(task, f"卸兵{'完成' if success else '失败'}：{general.get('name') or gid}，原带兵 {count}{soldier_type_name(code)}")
    generals = refresh_generals(sess)
    try:
        refresh_military_intel(sess)
    except Exception:
        pass
    return {"clearedCount": cleared, "skippedCount": skipped, "results": results, "generals": generals}


def execute_heal_wounded(
    sess: dict[str, Any],
    formation: dict[str, Any],
    *,
    confirm: str = "",
    allow_all_if_count_unknown: bool = True,
    _copper_shortage_retry: bool = True,
) -> dict[str, Any]:
    if confirm != "heal-wounded":
        raise RuntimeError("真实治疗伤兵需要 confirm=heal-wounded")
    copper_check = (
        ensure_account_copper_floor(sess, context="治疗伤兵前")
        if _copper_shortage_retry
        else {"ok": True, "exchanged": False, "reason": "铜钱不足恢复后的单次治疗重试"}
    )
    if not copper_check.get("ok"):
        return {
            "success": False,
            "message": copper_check.get("message") or "治疗伤兵前粮食转铜失败",
            "copperCheck": copper_check,
        }
    plan = prepare_heal_wounded(sess, formation, allow_all_if_count_unknown=allow_all_if_count_unknown)
    if not plan.get("ready"):
        return {"success": False, "skipped": True, "message": plan.get("reason") or "治疗条件不足", "plan": plan}
    fief_id = int(plan["fiefId"])
    soldier_type_code = int(plan["soldierTypeCode"])
    count = int(plan["woundedCount"])
    group = int(plan.get("soldierGroup", 2))
    if plan.get("healAll"):
        pre_payload, heal_payload = build_heal_all_payloads(fief_id)
    else:
        pre_payload = build_heal_preinfo_payload(fief_id, soldier_type_code, count)
        heal_payload = build_heal_payload(fief_id, group, soldier_type_code, count, use_gold=False)

    pre_code, pre_data, pre_packets = post_game(sess["gameHttp"], [(0x1231, pre_payload)], int(sess["dm"]), account_id=str(sess.get("sessionId") or ""))
    pre_payloads = [p["payload"] for p in pre_packets if p.get("opcode") == 0x8231 and "payload" in p]
    pre_parsed = parse_heal_preinfo_response(pre_payloads[0]) if pre_payloads else {"success": False, "message": "未收到 0x8231 治疗预估响应"}
    if not pre_parsed.get("success"):
        pre_message = str(pre_parsed.get("message") or "")
        if _copper_shortage_retry and "铜钱不足" in pre_message:
            return retry_heal_after_fixed_copper_exchange(
                sess,
                formation,
                confirm=confirm,
                allow_all_if_count_unknown=allow_all_if_count_unknown,
                original_message=pre_message,
            )
        report = {
            "time": now_ms(),
            "role": sess["role"],
            "area": sess["area"],
            "plan": plan,
            "success": False,
            "message": pre_parsed.get("message") or "治疗预估失败，未发送 0x1230",
            "preInfo": {"opcode": "0x1231", "payloadHex": pre_payload.hex(), "http": pre_code, "packets": summarize_packets(pre_packets), "parsed": pre_parsed},
        }
        report["reportFile"] = ""
        return report

    heal_code, heal_data, heal_packets = post_game(sess["gameHttp"], [(0x1230, heal_payload)], int(sess["dm"]), account_id=str(sess.get("sessionId") or ""))
    heal_payloads = [p["payload"] for p in heal_packets if p.get("opcode") == 0x8230 and "payload" in p]
    heal_parsed = parse_heal_response(heal_payloads[0]) if heal_payloads else {"success": False, "message": "未收到 0x8230 治疗响应"}
    heal_message = str(heal_parsed.get("message") or heal_parsed.get("textPreview") or "")
    if (
        not heal_parsed.get("success")
        and _copper_shortage_retry
        and "铜钱不足" in heal_message
    ):
        return retry_heal_after_fixed_copper_exchange(
            sess,
            formation,
            confirm=confirm,
            allow_all_if_count_unknown=allow_all_if_count_unknown,
            original_message=heal_message,
        )
    report = {
        "time": now_ms(),
        "role": sess["role"],
        "area": sess["area"],
        "plan": plan,
        "preInfo": {"opcode": "0x1231", "payloadHex": pre_payload.hex(), "http": pre_code, "packets": summarize_packets(pre_packets), "parsed": pre_parsed},
        "heal": {"opcode": "0x1230", "payloadHex": heal_payload.hex(), "http": heal_code, "packets": summarize_packets(heal_packets), "parsed": heal_parsed},
        "success": bool(heal_parsed.get("success")),
        "message": heal_parsed.get("message") or heal_parsed.get("textPreview") or "",
    }
    report["reportFile"] = ""
    return report


def retry_heal_after_fixed_copper_exchange(
    sess: dict[str, Any],
    formation: dict[str, Any],
    *,
    confirm: str,
    allow_all_if_count_unknown: bool,
    original_message: str,
) -> dict[str, Any]:
    """治疗明确返回铜钱不足时，固定兑换一次10万粮，再重试治疗一次。"""
    sid = str(sess.get("sessionId") or "")
    food_amount = 100_000
    copper_amount = 30_000
    known_food = int((sess.get("roleState") or {}).get("food") or 0)
    if 0 < known_food < food_amount:
        message = (
            "治疗伤兵铜钱不足；固定兑换需要100000粮食，"
            f"当前只有{known_food}，等待资源或任务奖励恢复"
        )
        account_log(sid, message, level="warning", source="heal-copper-recovery")
        return {
            "success": False,
            "message": message,
            "originalHealMessage": original_message,
            "copperRecovery": {
                "attempted": False,
                "deferredForFood": True,
                "foodAmount": food_amount,
                "currentFood": known_food,
                "copperAmount": copper_amount,
                "success": False,
            },
        }
    try:
        exchange = execute_food_to_copper(
            sess,
            food_amount,
            confirm="food-to-copper",
        )
    except Exception as exc:
        message = f"治疗伤兵铜钱不足；固定粮食转铜失败：{exc}"
        account_log(sid, message, level="error", source="heal-copper-recovery")
        return {
            "success": False,
            "message": message,
            "originalHealMessage": original_message,
            "copperRecovery": {
                "attempted": True,
                "foodAmount": food_amount,
                "copperAmount": copper_amount,
                "success": False,
            },
        }
    if not exchange.get("success"):
        message = (
            "治疗伤兵铜钱不足；固定粮食转铜失败："
            f"{exchange.get('message') or '游戏服未确认成功'}"
        )
        account_log(sid, message, level="error", source="heal-copper-recovery")
        return {
            "success": False,
            "message": message,
            "originalHealMessage": original_message,
            "copperRecovery": {
                "attempted": True,
                "foodAmount": food_amount,
                "copperAmount": copper_amount,
                "success": False,
                "exchange": exchange,
            },
        }
    exchange_message = (
        f"治疗伤兵铜钱不足，已固定触发一次粮食转铜："
        f"消耗{food_amount}粮食，兑换{copper_amount}铜"
    )
    account_log(
        sid,
        exchange_message,
        source="heal-copper-recovery",
        detail=exchange,
    )
    retried = execute_heal_wounded(
        sess,
        formation,
        confirm=confirm,
        allow_all_if_count_unknown=allow_all_if_count_unknown,
        _copper_shortage_retry=False,
    )
    return {
        **retried,
        "message": (
            f"{exchange_message}；治疗重试成功"
            if retried.get("success")
            else f"{exchange_message}；治疗重试失败：{retried.get('message') or '无提示'}"
        ),
        "originalHealMessage": original_message,
        "copperRecovery": {
            "attempted": True,
            "foodAmount": food_amount,
            "copperAmount": copper_amount,
            "success": True,
            "exchange": exchange,
        },
    }


def prepare_heal_wounded(sess: dict[str, Any], formation: dict[str, Any], *, allow_all_if_count_unknown: bool = True) -> dict[str, Any]:
    """准备治疗伤兵 payload；只有 fiefId + woundedCount 都明确时才允许真实发送。

    目前 0x1230/0x1231 字段已恢复，但“当前伤兵数量”还需要从 8004/战报/伤兵列表进一步稳定解析。
    因此自动刷黄循环默认只生成可审计 payload，不盲发可能错误的治疗请求。
    """
    return shared_plan_heal_wounded(
        sess.get("generals") or [],
        formation,
        allow_all_if_count_unknown=allow_all_if_count_unknown,
    )


TASK_NOTICE_DISPLAY = {
    "auto-brush-yellow": ("brushYellow", "刷黄"),
    "brush-yellow": ("brushYellow", "刷黄"),
    "mine": ("mine", "打矿"),
    "auto-mine": ("mine", "打矿"),
    "attack-mine": ("mine", "打矿"),
    "lossless": ("lossless", "无损"),
    "dungeon": ("dungeon", "副本"),
    "raid": ("raid", "掠夺"),
    "auto-general": ("general", "将领维护"),
    "auto-ministry": ("ministry", "六部"),
    "auto-captives": ("captives", "俘虏营"),
    "apply-formations": ("formations", "配兵"),
    "auto-domestic": ("autoDomestic", "自动内政"),
    "auto-technology": ("autoTechnology", "升级科技"),
    "auto-inventory": ("inventory", "背包整理"),
    "auto-alarm": ("alarm", "军情警报"),
}


def task_notice_identity(task: dict[str, Any]) -> tuple[str, str]:
    raw_type = str(task.get("type") or "task")
    key, name = TASK_NOTICE_DISPLAY.get(raw_type, (raw_type, raw_type or "后台任务"))
    if (
        raw_type == "dungeon"
        and normalize_dungeon_mode((task.get("config") or {}).get("mode"))
        == DUNGEON_MODE_CLEAR
    ):
        name = "打通副本"
    return f"task:{key}", name


def sync_task_important_notice(
    task: dict[str, Any],
    message: str,
    session_id: str,
) -> None:
    account_key = account_storage_key(session_id=session_id)
    notice_key, task_name = task_notice_identity(task)
    status = str(task.get("status") or "")
    text = str(task.get("error") or task.get("stopReason") or message or "").strip()
    if status == "error":
        database_upsert_important_notice(
            account_key,
            notice_key,
            severity="error",
            title=f"{task_name}已中止",
            message=text,
            source="task",
        )
        return
    if (
        status in ACTIVE_TASK_STATUSES
        and notice_key in {"task:dungeon", "task:lossless"}
        and "state=waiting-resources" in str(message or "")
    ):
        database_upsert_important_notice(
            account_key,
            notice_key,
            severity="warning",
            title=f"{task_name}等待资源",
            message=text,
            source="automation",
        )
        return
    abnormal_stop = bool(task.get("stopReason")) or any(
        marker in str(message or "")
        for marker in ("账号连接中断", "未取得指挥中心出征权", "异常，已中断")
    )
    if status == "stopped" and abnormal_stop:
        database_upsert_important_notice(
            account_key,
            notice_key,
            severity="warning",
            title=f"{task_name}已停止",
            message=text,
            source="task",
        )
        return
    if status in ACTIVE_TASK_STATUSES and any(
        marker in str(message or "")
        for marker in (
            "启动", "恢复运行", "重新开始",
            "已接入账号共享常驻调度",
            "state=completed", "state=dispatched", "state=fighting",
            "state=settled", "state=chest-opened",
            "state=settlement-recovered", "state=reconciled",
            "state=waiting",
        )
    ):
        database_resolve_important_notice(account_key, notice_key)


def task_log(task: dict[str, Any], message: str) -> None:
    line = f"[{time.strftime('%H:%M:%S')}] {message}"
    status = str(task.get("status") or "")
    repeat_key = (status, str(message))
    written_at = time.monotonic()
    with TASK_LOCK:
        if (
            task.get("_lastLogKey") == repeat_key
            and written_at - float(task.get("_lastLogAt") or 0.0)
            < TASK_LOG_REPEAT_INTERVAL_SEC
        ):
            task["_suppressedLogCount"] = int(
                task.get("_suppressedLogCount") or 0
            ) + 1
            return
        task["_lastLogKey"] = repeat_key
        task["_lastLogAt"] = written_at
        task["_suppressedLogCount"] = 0
        task["updatedAt"] = now_ms()
        task.setdefault("logs", []).append(line)
        task["logs"] = task["logs"][-120:]
        sid = str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "")
        detail = {"taskId": task.get("taskId"), "type": task.get("type"), "status": task.get("status"), "cycle": task.get("cycle")}
    if sid:
        account_log(sid, message, source="task", detail=detail)
        # A transient account-network pause is intentionally represented by
        # the account-level warning.  Logging the lifecycle transition is
        # still useful, but it must not create a terminal notice for every
        # feature row (those rows did not fail independently).
        if not bool(task.get("_suppressImportantNotice")):
            sync_task_important_notice(task, message, sid)
    else:
        system_log(message, source="task", detail=detail)
    if os.environ.get("DWPM_VERBOSE_TASK_LOGS", "").lower() in {
        "1", "true", "yes",
    }:
        print(f"[auto-task] {task.get('taskId')} {message}")
    if status in {"finished", "stopped", "error"}:
        prune_auto_tasks()


def stop_tasks_for_session_invalid(
    session_id: str,
    reason: str,
    *,
    transient: bool = False,
    operator_maintenance: bool = False,
) -> list[str]:
    """Stop active account tasks at one explicit lifecycle boundary.

    Operator maintenance is deliberately separate from a transient network
    pause: its notice-suppression marker must be installed before the stop
    event is signalled.  Otherwise the waiting worker can observe CANCELLED
    and publish a false terminal feature notice in that small hand-off window.
    """
    sid = str(session_id or "")
    stopped: list[dict[str, Any]] = []
    with TASK_LOCK:
        for task in AUTO_TASKS.values():
            task_sid = str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "")
            if task_sid != sid or str(task.get("status") or "") not in {
                "queued", "starting", "running", "stopping"
            }:
                continue
            if operator_maintenance:
                # Set this before stopEvent.  A worker awakened by set() can
                # immediately log a cancelled shared operation.
                task["_suppressImportantNotice"] = True
                task["_operatorMaintenancePause"] = True
                task.pop("_transientNetworkPause", None)
            if task.get("stopEvent"):
                task["stopEvent"].set()
            task["status"] = "stopped"
            task["stopReason"] = (
                f"本地人工维护已暂停后台任务：{reason}"
                if operator_maintenance
                else (
                    f"网络暂时不可用，已暂停后台任务并等待心跳恢复：{reason}"
                    if transient
                    else f"账号连接中断，已停止后台任务：{reason}"
                )
            )
            task.pop("error", None)
            task["schedulerState"] = "stopped"
            task["schedulerRunnable"] = False
            task["schedulerMessage"] = (
                "本地人工维护中，任务已暂停"
                if operator_maintenance
                else (
                    "网络暂时不可用，等待心跳恢复"
                    if transient
                    else "账号掉线，等待倒计时重连"
                )
            )
            if transient:
                task["_transientNetworkPause"] = True
            task["updatedAt"] = now_ms()
            stopped.append(task)
    with COMMAND_CENTER_CONDITION:
        COMMAND_CENTER_CLAIMS.pop(sid, None)
        COMMAND_CENTER_CONDITION.notify_all()
    for task in stopped:
        temporary_suppression = transient and not operator_maintenance
        if temporary_suppression:
            task["_suppressImportantNotice"] = True
        try:
            task_log(
                task,
                task.get("stopReason")
                or f"账号连接中断，已停止后台任务：{reason}",
            )
        finally:
            if temporary_suppression:
                task.pop("_suppressImportantNotice", None)
    if stopped:
        system_log(
            (
                f"本地人工维护已暂停 {len(stopped)} 个后台任务：{reason}"
                if operator_maintenance
                else (
                    f"账号网络暂时不可用，已暂停 {len(stopped)} 个后台任务：{reason}"
                    if transient
                    else f"账号连接中断，已停止 {len(stopped)} 个后台任务：{reason}"
                )
            ),
            level="info",
            source="session",
            session_id=sid,
            detail={"stoppedTaskIds": [t.get("taskId") for t in stopped]},
        )
    return [str(t.get("taskId") or "") for t in stopped]


def state_machine_stop(task: dict[str, Any], reason: str) -> None:
    task["status"] = "error"
    task["error"] = f"状态机阻止刷黄：{reason}"
    task_log(task, task["error"])


def load_general_for_state_machine(task: dict[str, Any], sess: dict[str, Any], general_id: str, stage: str) -> dict[str, Any] | None:
    """Refresh live 0x8004 + 0xa110 before making a decision."""
    try:
        general = refresh_general_with_a110_status(sess, general_id)
    except Exception as e:
        msg = str(e)
        mark_account_offline_if_session_invalid(str(sess.get("sessionId") or ""), msg)
        state_machine_stop(task, f"{stage}失败：账号/角色状态刷新失败，无法确认将领状态；{msg}")
        return None
    if not general:
        state_machine_stop(task, f"{stage}失败：0x8004 未找到刷黄页指定将领 {general_id}，请重新同步角色/将领信息")
        return None
    return general


def general_energy_policy(
    sess: dict[str, Any],
    task: dict[str, Any] | None = None,
) -> tuple[bool, int]:
    """Return the current account-wide auto-energy policy.

    The common-page setting is authoritative even for an already-running
    resident task. A task snapshot is only a fallback for compatibility with
    older saved brush tasks and focused unit tests.
    """
    task_config = dict((task or {}).get("config") or {})
    sid = str(sess.get("sessionId") or task_config.get("sessionId") or "")
    saved_config = SAVED_CONFIGS.get(sid)
    if not isinstance(saved_config, dict) and sid:
        habits = load_account_habits(sess)
        saved_config = habits.get("config") if isinstance(habits.get("config"), dict) else None
    config = dict(task_config)
    if isinstance(saved_config, dict):
        for key in ("autoEnergy", "energyThreshold"):
            if key in saved_config:
                config[key] = saved_config[key]

    raw_enabled = config.get("autoEnergy", True)
    if isinstance(raw_enabled, str):
        enabled = raw_enabled.strip().lower() not in {"", "0", "false", "no", "off"}
    else:
        enabled = bool(raw_enabled)
    try:
        threshold = int(config.get("energyThreshold") or 20)
    except (TypeError, ValueError):
        threshold = 20
    return enabled, max(20, min(threshold, 100))


def general_energy_action_lock(
    sess: dict[str, Any],
    general_id: str,
) -> threading.RLock:
    sid = str(sess.get("sessionId") or f"memory:{id(sess)}")
    key = (sid, str(general_id))
    with GENERAL_ENERGY_ACTION_LOCKS_LOCK:
        return GENERAL_ENERGY_ACTION_LOCKS.setdefault(key, threading.RLock())


def ensure_general_energy_for_check(
    sess: dict[str, Any],
    general: dict[str, Any],
    action_name: str,
    *,
    task: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Apply the common auto-energy policy before any ordinary dispatch check.

    One check consumes at most one energy item for one general. The confirmed
    0x8218 response means one item adds 50 energy; a later task check may use
    another item if the general is still below the configured threshold.
    """
    enabled, threshold = general_energy_policy(sess, task)
    current_raw = general.get("tili")
    if not general.get("energyReliable") or current_raw is None:
        return general
    try:
        current = int(current_raw)
    except (TypeError, ValueError):
        return general
    if current >= threshold or not enabled:
        return general

    general_id = str(general.get("id") or general.get("idHex") or "").strip()
    name = str(general.get("name") or general_id or "未知将领")
    if not general_id:
        raise RuntimeError(
            f"{action_name}检查到{name}体力={current}，低于自动加体阈值{threshold}，"
            "但缺少有效将领 ID"
        )

    with general_energy_action_lock(sess, general_id):
        # A concurrent task may have completed the same action while this task
        # was waiting for the per-general lock. Reuse the newest cached value.
        latest = next((
            item for item in sess.get("generals") or []
            if str(item.get("id")) == general_id or str(item.get("idHex")) == general_id
        ), None)
        if latest and latest.get("energyReliable") and latest.get("tili") is not None:
            try:
                latest_energy = int(latest.get("tili"))
            except (TypeError, ValueError):
                latest_energy = current
            if latest_energy >= threshold:
                general["tili"] = latest_energy
                return general
            current = latest_energy

        try:
            inventory = refresh_inventory(sess)
        except Exception as exc:
            raise RuntimeError(
                f"{action_name}检查到{name}体力={current}，低于自动加体阈值{threshold}；"
                f"使用活血丹前读取宝库失败：{exc}"
            ) from exc
        planning_general = dict(latest or general)
        planning_general["tili"] = current
        planning_general["energyReliable"] = True
        try:
            energy_plan = shared_plan_general_energy_use(
                planning_general,
                inventory,
                enabled=enabled,
                threshold=threshold,
                action_name=action_name,
            )
        except ValueError as exc:
            raise RuntimeError(str(exc)) from exc
        if not energy_plan.get("actionRequired"):
            general["tili"] = int(energy_plan.get("after") or current)
            return general
        try:
            result = execute_use_energy_item(
                sess,
                general_id,
                confirm="use-energy-item",
            )
        except Exception as exc:
            raise RuntimeError(
                f"{action_name}检查到{name}体力={current}，低于自动加体阈值{threshold}；"
                f"活血丹使用失败：{exc}"
            ) from exc
        try:
            confirmed = shared_apply_general_energy_receipt(
                energy_plan,
                result,
                action_name=action_name,
            )
        except ValueError as exc:
            raise RuntimeError(str(exc)) from exc
        updated = int(confirmed["after"])
        general["tili"] = updated
        if latest is not None:
            latest["tili"] = updated
        message = str(confirmed["message"])
        if task is not None:
            task_log(task, message)
        else:
            account_log(
                str(sess.get("sessionId") or ""),
                message,
                source="general-energy",
                detail={
                    "generalId": general_id,
                    "generalName": name,
                    "before": current,
                    "after": updated,
                    "threshold": threshold,
                    "action": action_name,
                },
            )
        return general


def dispatch_block_reason(general: dict[str, Any], formation: dict[str, Any]) -> str | None:
    """Return a user-facing preflight reason when dispatch would be rejected by the game server.

    The game often returns only 0x8522=ff0000 for invalid dispatches.  Surface the obvious
    local state first so the UI does not look like it silently did nothing.
    """
    if not general:
        return "未找到出征将领"
    status = general.get("displayStatus") or general.get("statusText")
    if status != "闲":
        return f"将领当前不是空闲状态(状态={status or '未知'}，必须=闲)"
    tili = general.get("tili")
    if not general.get("energyReliable") or tili is None:
        return "无法确认将领体力值（0x8004 未解析到可靠体力），已停止避免误操作"
    try:
        tili_int = int(tili)
    except Exception:
        return f"无法确认将领体力值(tili={tili})，已停止避免误操作"
    if tili_int <= 20:
        return f"将领体力不足：需要 >20，当前体力={tili}"
    return None


def formation_match_reason(general: dict[str, Any] | None, formation: dict[str, Any]) -> str | None:
    """Return None only when troop type and count exactly match the saved formation rule."""
    if not general:
        return "未找到将领，无法确认当前配兵"
    soldier_type = formation.get("soldierType") or "轻骑兵"
    soldier_count = int(formation.get("soldierCount") or 0)
    if soldier_count <= 0:
        return None
    target_code = soldier_type_code(soldier_type)
    current_code = general.get("soldierTypeCode")
    current_count = general.get("soldierCount", general.get("currentSoldierCount"))
    if current_code is None or current_count is None:
        return f"无法解析当前带兵：兵种={current_code if current_code is not None else '未知'} 数量={current_count if current_count is not None else '未知'}"
    if int(current_code) != target_code:
        return f"兵种不符合：当前 {soldier_type_name(current_code)}(code={current_code})，需要 {soldier_type}(code={target_code})"
    if int(current_count) != soldier_count:
        return f"兵力数量不符合：当前 {current_count}，需要 ={soldier_count} {soldier_type}"
    return None


def formation_exact_match_reason(general: dict[str, Any] | None, formation: dict[str, Any]) -> str | None:
    """Backward-compatible alias for the now universally exact formation check."""
    return formation_match_reason(general, formation)


def saved_formation_for_general(sess: dict[str, Any], general_id: str) -> dict[str, Any] | None:
    sid = str(sess.get("sessionId") or "")
    rules = list(SAVED_FORMATION_RULES.get(sid) or [])
    if not rules:
        habits = load_account_habits(sess)
        raw_rules = list(habits.get("formations") or [])
        if raw_rules:
            rules = normalize_formation_rules(
                sess,
                raw_rules,
                require_known=False,
            )
            SAVED_FORMATION_RULES[sid] = rules
    return next((
        dict(rule)
        for rule in rules
        if str(rule.get("generalId") or "") == str(general_id)
    ), None)


def heal_all_wounded_before_military_prepare(
    sess: dict[str, Any],
    action_name: str,
    *,
    task: dict[str, Any] | None = None,
    force: bool = False,
) -> dict[str, Any]:
    """Heal every known fief before checking whether saved formations can be met."""
    sid = str(sess.get("sessionId") or "")
    saved_config = SAVED_CONFIGS.get(sid) or load_account_habits(sess).get("config") or {}
    if not force and not bool(saved_config.get("healWounded", True)):
        return {
            "success": True,
            "skipped": True,
            "message": "未启用出征前治疗",
            "results": [],
        }
    try:
        refresh_generals(sess)
    except Exception as exc:
        raise RuntimeError(f"{action_name}出征前治疗失败：无法刷新封地伤兵状态；{exc}") from exc
    fief_ids: list[int] = []
    for general in sess.get("generals") or []:
        raw_fief_id = general.get("fiefId") or general.get("placeID")
        try:
            fief_id = int(raw_fief_id or 0)
        except Exception:
            continue
        if fief_id > 0 and fief_id not in fief_ids:
            fief_ids.append(fief_id)
    results: list[dict[str, Any]] = []
    treated_count = 0
    skipped_count = 0
    for fief_id in fief_ids:
        result = execute_heal_wounded(
            sess,
            {"fiefId": fief_id},
            confirm="heal-wounded",
            allow_all_if_count_unknown=True,
        )
        results.append({
            "fiefId": fief_id,
            "success": bool(result.get("success")),
            "skipped": bool(result.get("skipped")),
            "message": result.get("message") or "",
            "plan": result.get("plan") or {},
        })
        if result.get("success"):
            treated_count += 1
            if task:
                task_log(task, f"{action_name}出征前治疗完成：封地 {fief_id} 已治疗全部伤兵")
            continue
        if result.get("skipped"):
            skipped_count += 1
            if task:
                task_log(task, f"{action_name}出征前治疗跳过：封地 {fief_id}；{result.get('message') or '当前无伤兵'}")
            continue
        raise RuntimeError(
            f"{action_name}出征前治疗失败：封地 {fief_id}；"
            f"{result.get('message') or '游戏服未确认成功'}"
        )
    try:
        refresh_generals(sess)
    except Exception as exc:
        raise RuntimeError(f"{action_name}治疗后刷新兵力失败：{exc}") from exc
    return {
        "success": True,
        "message": (
            f"{action_name}出征前治疗检查完成："
            f"治疗{treated_count}个封地，跳过{skipped_count}个封地"
        ),
        "fiefCount": len(fief_ids),
        "treatedFiefCount": treated_count,
        "skippedFiefCount": skipped_count,
        "results": results,
    }


def prepare_military_generals(
    sess: dict[str, Any],
    general_ids: list[str],
    action_name: str,
    *,
    task: dict[str, Any] | None = None,
    allow_existing_troops: bool = False,
    force_heal: bool = False,
) -> list[dict[str, Any]]:
    """Check state/energy/formation and repair formation before a real dispatch."""
    heal_all_wounded_before_military_prepare(
        sess,
        action_name,
        task=task,
        force=force_heal,
    )
    selected: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw_gid in general_ids:
        gid = str(raw_gid or "").strip()
        if not gid or gid in seen:
            continue
        seen.add(gid)
        try:
            general = refresh_general_with_a110_status(sess, gid)
        except Exception as e:
            msg = str(e)
            mark_account_offline_if_session_invalid(str(sess.get("sessionId") or ""), msg)
            raise RuntimeError(f"{action_name}出征前刷新将领状态失败：{gid}；{msg}") from e
        if not general:
            raise RuntimeError(f"{action_name}出征前检查未找到将领：{gid}")
        name = str(general.get("name") or gid)
        current_code, current_count = _general_current_troops(general)
        current_troops = (
            "无配兵"
            if current_code is None or current_code < 0 or current_count <= 0
            else f"{current_count}{soldier_type_name(current_code)}"
        )
        if task:
            task_log(
                task,
                f"{action_name}出征前检查：{name} 状态={general.get('displayStatus') or general.get('statusText') or '未知'}，"
                f"体力={general.get('tili') if general.get('tili') is not None else '未知'}，当前配兵={current_troops}",
            )
        general = ensure_general_energy_for_check(
            sess,
            general,
            action_name,
            task=task,
        )
        block = dispatch_block_reason(general, {})
        if block:
            raise RuntimeError(f"{action_name}出征前检查未通过：{name}；{block}")
        formation = saved_formation_for_general(sess, gid)
        if not formation:
            if allow_existing_troops:
                selected.append(general)
                continue
            raise RuntimeError(
                f"{action_name}出征前检查未通过：{name} 没有保存的配兵规则；"
                "请先到“军事-配兵”页为该将领保存兵种和数量"
            )
        target_type = str(formation.get("soldierType") or "轻骑兵")
        target_count = int(formation.get("soldierCount") or 0)
        try:
            troop_limit = int(general.get("troopLimit") or general.get("daiBingLimit") or 0)
        except Exception:
            troop_limit = 0
        effective_count = min(target_count, troop_limit) if troop_limit > 0 and target_count > 0 else target_count
        effective_formation = {**formation, "soldierCount": effective_count}
        mismatch = formation_match_reason(general, effective_formation)
        if mismatch:
            if task:
                task_log(
                    task,
                    f"{action_name}出征前配兵不符合：{name}；{mismatch}；"
                    f"开始按保存规则配兵 {effective_count}{target_type}"
                    + (f"（配置 {target_count}，当前统兵上限 {troop_limit}）" if effective_count != target_count else ""),
                )
            try:
                assigned = execute_assign_troops(
                    sess,
                    gid,
                    target_type,
                    effective_count,
                    confirm="assign-troops",
                )
            except Exception as e:
                msg = str(e)
                if is_troop_shortage_message(msg):
                    if task:
                        task_log(task, f"{action_name}闲兵不足，开始治疗后释放全部空闲将领兵力并重试")
                    heal_all_wounded_before_military_prepare(sess, action_name, task=task)
                    unassign_all_idle_generals(sess, task=task)
                    try:
                        assigned = execute_assign_troops(
                            sess, gid, target_type, effective_count,
                            confirm="assign-troops",
                        )
                    except Exception as retry_error:
                        msg = str(retry_error)
                    else:
                        if assigned.get("success"):
                            msg = ""
                if not msg and assigned.get("success"):
                    pass
                else:
                    mark_account_offline_if_session_invalid(str(sess.get("sessionId") or ""), msg)
                    raise RuntimeError(f"{action_name}出征前配兵失败：{name}；{msg}") from e
            if not assigned.get("success"):
                raise RuntimeError(
                    f"{action_name}出征前配兵失败：{name} → {effective_count}{target_type}；"
                    f"{assigned.get('message') or '游戏服未确认成功'}"
                )
            if task:
                task_log(task, f"{action_name}出征前配兵完成：{name} → {effective_count}{target_type}")
            general = refresh_general_with_a110_status(sess, gid)
            if not general:
                raise RuntimeError(f"{action_name}配兵后无法重新读取将领：{name}")
            block = dispatch_block_reason(general, formation)
            if block:
                raise RuntimeError(f"{action_name}配兵后检查未通过：{name}；{block}")
            mismatch = formation_match_reason(general, formation)
            if mismatch:
                raise RuntimeError(f"{action_name}配兵后校验未通过：{name}；{mismatch}")
        elif task:
            task_log(
                task,
                f"{action_name}出征前配兵检查通过：{name} 当前 {current_troops}，"
                f"与保存规则完全一致：{target_count}{target_type}",
            )
        selected.append(general)
    if not selected:
        raise RuntimeError(f"{action_name}至少需要选择 1 个出征将领")
    return selected


def brush_general_state_preflight(sess: dict[str, Any], general_id: str, action_name: str, *, require_saved_formation: bool = True) -> dict[str, Any]:
    """Manual brush endpoints use the same state machine: live 0x8004, 0xa110 idle, energy, and formation."""
    if not general_id:
        raise RuntimeError(f"状态机阻止{action_name}：缺少出征将领")
    if action_name == "出征" and require_saved_formation:
        return prepare_military_generals(sess, [general_id], "刷黄")[0]
    try:
        general = refresh_general_with_a110_status(sess, general_id)
    except Exception as e:
        msg = str(e)
        mark_account_offline_if_session_invalid(str(sess.get("sessionId") or ""), msg)
        raise RuntimeError(f"状态机阻止{action_name}：账号/角色状态刷新失败，无法确认将领状态；{msg}") from e
    if not general:
        raise RuntimeError(f"状态机阻止{action_name}：0x8004 未找到出征将领 {general_id}")
    block = dispatch_block_reason(general, {})
    if block:
        raise RuntimeError(f"状态机阻止{action_name}：{block}")
    formation = next((f for f in SAVED_FORMATION_RULES.get(str(sess.get("sessionId") or ""), []) if str(f.get("generalId")) == str(general_id)), None)
    if require_saved_formation and not formation:
        raise RuntimeError(f"状态机阻止{action_name}：将领 {general.get('name') or general_id} 没有保存过配兵规则，请先到“军事-配兵”页保存")
    if formation:
        reason = formation_match_reason(general, formation)
        if reason:
            raise RuntimeError(f"状态机阻止{action_name}：将领配兵状态不满足保存规则：{reason}")
    return general


def formation_general_ids(row: Any) -> list[str]:
    """Return the stable IDs referenced by one saved formation row."""
    if not isinstance(row, dict):
        return []
    raw_ids = row.get("generalIds")
    if isinstance(raw_ids, list):
        ids = [str(value).strip() for value in raw_ids if str(value or "").strip()]
    else:
        fallback = str(row.get("generalId") or "").strip()
        ids = [fallback] if fallback else []
    return list(dict.fromkeys(ids))


def known_general_ids(sess: dict[str, Any]) -> set[str]:
    return {
        str(value)
        for general in sess.get("generals", [])
        if isinstance(general, dict)
        for value in (general.get("id"), general.get("idHex"))
        if value not in (None, "")
    }


def general_name_snapshots(sess: dict[str, Any]) -> dict[str, str]:
    names: dict[str, str] = {}
    for general in sess.get("generals", []):
        if not isinstance(general, dict):
            continue
        name = str(general.get("name") or "").strip()
        if not name:
            continue
        for value in (general.get("id"), general.get("idHex")):
            if value not in (None, ""):
                names[str(value)] = name
    return names


def unresolved_formation_general_ids(
    sess: dict[str, Any],
    rows: list[dict[str, Any]] | None,
) -> list[str]:
    """Find configured IDs absent from the latest live snapshot.

    An empty live snapshot means "not synchronized yet", not "all generals
    were deleted", so it deliberately produces no unresolved IDs.
    """
    known_ids = known_general_ids(sess)
    if not known_ids:
        return []
    unresolved: list[str] = []
    seen: set[str] = set()
    for row in rows or []:
        if not isinstance(row, dict) or not bool(row.get("enabled", True)):
            continue
        for general_id in formation_general_ids(row):
            if general_id not in known_ids and general_id not in seen:
                seen.add(general_id)
                unresolved.append(general_id)
    return unresolved


def unresolved_saved_general_ids(
    sess: dict[str, Any],
    habits: dict[str, Any] | None,
) -> list[str]:
    """Include formation and brush references in the diagnostic warning."""
    payload = habits if isinstance(habits, dict) else {}
    rows: list[dict[str, Any]] = [
        row for row in payload.get("formations") or [] if isinstance(row, dict)
    ]
    config = payload.get("config")
    if isinstance(config, dict):
        rows.extend(
            row for row in config.get("formations") or []
            if isinstance(row, dict)
        )
        brush = config.get("brush")
        if isinstance(brush, dict):
            rows.extend(
                row for row in brush.get("rows") or []
                if isinstance(row, dict)
            )
            if brush.get("generalId") or brush.get("generalIds"):
                rows.append(brush)
    return unresolved_formation_general_ids(sess, rows)


def normalize_formation_rules(
    sess: dict[str, Any],
    rows: list[dict[str, Any]],
    *,
    require_known: bool = True,
) -> list[dict[str, Any]]:
    out = []
    known_ids = known_general_ids(sess)
    seen_generals: set[str] = set()
    for idx, row in enumerate(rows):
        f = dict(row or {})
        if not f.get("enabled", True):
            continue
        gids = formation_general_ids(f)
        if not gids:
            continue
        count = int(f.get("soldierCount") or 0)
        if count <= 0:
            raise RuntimeError(f"第 {idx + 1} 条配兵规则兵力数量必须大于 0")
        for gid in gids:
            if require_known and known_ids and gid not in known_ids:
                raise RuntimeError(f"第 {idx + 1} 条配兵规则的将领不在当前账号将领列表中：{gid}")
            if gid in seen_generals:
                raise RuntimeError(f"将领 {gid} 被重复配置，请只在一个配兵规则里选择它")
            seen_generals.add(gid)
            normalized = {
                "enabled": True,
                "generalId": gid,
                "generalIds": [gid],
                "soldierType": str(f.get("soldierType") or "轻骑兵"),
                "soldierCount": count,
                "sourceRowIndex": idx,
            }
            # Keep the last known label as presentation metadata only.  The
            # ID above remains the sole identity used by execution.
            snapshots = f.get("generalNameSnapshots")
            if isinstance(snapshots, dict):
                normalized_snapshots = {
                    str(key): str(value)
                    for key, value in snapshots.items()
                    if str(key or "").strip() and str(value or "").strip()
                }
                if normalized_snapshots:
                    normalized["generalNameSnapshots"] = normalized_snapshots
            out.append(normalized)
    if not out:
        raise RuntimeError("至少需要保存一条启用的配兵规则")
    return out


def sanitize_formation_rows(
    sess: dict[str, Any],
    rows: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], bool]:
    """Normalize row shape without deleting unresolved ID references.

    The boolean result means that at least one enabled row references an ID
    absent from the current snapshot.  A missing ID can be caused by a
    transient/partial protocol parse (or a rename), so it must remain in the
    persisted configuration until the user explicitly removes it.
    """
    cleaned: list[dict[str, Any]] = []
    live_names = general_name_snapshots(sess)
    for row in rows:
        source = dict(row or {})
        ids = formation_general_ids(source)
        source["generalIds"] = ids
        source["generalId"] = ids[0] if ids else ""
        snapshots = (
            dict(source.get("generalNameSnapshots") or {})
            if isinstance(source.get("generalNameSnapshots"), dict)
            else {}
        )
        for general_id in ids:
            if live_names.get(general_id):
                snapshots[general_id] = live_names[general_id]
        if snapshots:
            source["generalNameSnapshots"] = snapshots
        cleaned.append(source)
    return cleaned, bool(unresolved_formation_general_ids(sess, cleaned))


def heal_saved_formation_rules(sess: dict[str, Any]) -> list[dict[str, Any]]:
    """Load saved formation rules without destructively healing them.

    Historically this function rewrote rows whose IDs were absent from one
    snapshot.  That made a parser hiccup or a just-renamed general permanently
    erase a user's configuration.  Validation is now deferred to the action
    that actually needs a live general; the original rows stay in SQLite.
    """
    sid = str(sess.get("sessionId") or "")
    habits = load_account_habits(sess)
    persisted_rows = list(habits.get("formations") or [])
    runtime_rows = list(SAVED_FORMATION_RULES.get(sid) or [])
    source_rows = persisted_rows if persisted_rows else runtime_rows
    cleaned_rows, _has_unresolved = sanitize_formation_rows(sess, source_rows)
    has_enabled_row = any(
        bool(row.get("enabled", True)) and bool(
            row.get("generalIds") or row.get("generalId")
        )
        for row in cleaned_rows
        if isinstance(row, dict)
    )
    normalized = (
        normalize_formation_rules(sess, cleaned_rows, require_known=False)
        if has_enabled_row else []
    )
    SAVED_FORMATION_RULES[sid] = normalized
    sess["unresolvedFormationGeneralIds"] = unresolved_formation_general_ids(
        sess, cleaned_rows,
    )
    return normalized


def parse_composition_code(code: str) -> dict[str, int] | None:
    return shared_parse_composition_code(code)


def normalize_general_visit_ids(value: Any) -> list[str]:
    return shared_normalize_general_visit_ids(value)


SETTINGS_SCOPE_FIELDS = {
    "common.frequent": {
        "dailyLimit",
        "healWounded",
        "autoEnergy",
        "energyThreshold",
        "foodToCopper",
        "copperFloorWan",
        "domestic",
    },
    "common.daily": {"dailyTasks", "generalVisitGeneralIds"},
    "common.items": {
        "cleanInventory",
        "discardItemNames",
        "discardEquipment",
        "maxEquipmentQuality",
        "discardEquipmentQualities",
        "maxEquipmentLevel",
        "autoOpenItemNames",
        "autoOpenEnabled",
    },
    "common.chain": {"chainInventory"},
    "common.alarm": {"alarm"},
    "brush": {
        "autoStart",
        "reconnectDelayMinutes",
        "startHour",
        "dailyLimit",
        "cycleDelaySec",
        "returnWaitSec",
        "replenishTroops",
        "foodToCopper",
        "copperFloorWan",
        "cleanMail",
        "brush",
    },
}

SETTINGS_SCOPE_NESTED_FIELDS = {
    ("common.frequent", "domestic"): {
        "enabled",
        "emptyBuildingType",
        "upgradeBuildings",
        "upgradeTechnology",
        "technologyId",
        "technologyIds",
        "technologyTargetLevel",
    },
    ("common.daily", "dailyTasks"): set(DAILY_TASK_NAMES),
    ("common.chain", "chainInventory"): {
        "enabled",
        "keepItemName",
        "keepCount",
        "autoOpenEnabled",
        "autoOpenItemNames",
    },
    ("common.alarm", "alarm"): {
        "incomingEnabled",
        "incomingMode",
        "militaryEnabled",
        "militaryMode",
        "errorEnabled",
    },
}


def merge_settings_scope_patch(
    old_config: dict[str, Any] | None,
    scope: str,
    patch: dict[str, Any] | None,
) -> dict[str, Any]:
    """Merge one settings subpage into the persisted config.

    The server owns the field whitelist so a buggy/stale frontend cannot
    overwrite settings that belong to another subpage.
    """
    if scope not in SETTINGS_SCOPE_FIELDS:
        raise RuntimeError(f"未知设置保存范围：{scope}")
    if not isinstance(patch, dict):
        raise RuntimeError("设置 patch 必须是对象")

    merged = deepcopy(old_config) if isinstance(old_config, dict) else {}
    # A first-time common-page save must not implicitly turn on brush tasks.
    if not merged and scope.startswith("common."):
        merged["autoStart"] = False

    for key in SETTINGS_SCOPE_FIELDS[scope]:
        if key not in patch:
            continue
        value = deepcopy(patch[key])
        nested_fields = SETTINGS_SCOPE_NESTED_FIELDS.get((scope, key))
        if nested_fields is not None:
            source = value if isinstance(value, dict) else {}
            current = merged.get(key) if isinstance(merged.get(key), dict) else {}
            next_value = deepcopy(current)
            for nested_key in nested_fields:
                if nested_key in source:
                    next_value[nested_key] = deepcopy(source[nested_key])
            merged[key] = next_value
        else:
            merged[key] = value
    return merged


def normalize_auto_config(
    sess: dict[str, Any],
    body: dict[str, Any],
    *,
    resolve_brush_formations: bool = True,
) -> dict[str, Any]:
    cfg = dict(body.get("config") or body)
    brush = dict(cfg.get("brush") or {})
    brush_rows = brush.get("rows") or cfg.get("rows") or []
    if not isinstance(brush_rows, list):
        brush_rows = []
    auto_start = bool(cfg.get("autoStart", True))
    if brush_rows and not any(bool(row.get("enabled")) for row in brush_rows if isinstance(row, dict)):
        auto_start = False
    enabled_formations = (
        heal_saved_formation_rules(sess)
        if resolve_brush_formations
        else []
    )
    if auto_start and not enabled_formations:
        raise RuntimeError("请先到“军事-配兵”页保存配兵规则；刷黄页只保存刷黄规则，不会创建/修改配兵规则")
    active_brush_rows = [
        dict(row)
        for row in brush_rows
        if isinstance(row, dict) and bool(row.get("enabled"))
    ]
    if auto_start and not active_brush_rows:
        active_brush_rows = [dict(brush)]
    known_general_ids = {
        str(value)
        for general in sess.get("generals", [])
        for value in (general.get("id"), general.get("idHex"))
        if value not in (None, "")
    }
    formation_by_general = {
        str(formation.get("generalId")): formation
        for formation in enabled_formations
    }
    brush_rules: list[dict[str, Any]] = []
    selected_formations: list[dict[str, Any]] = []
    selected_formation_ids: set[str] = set()
    for row_index, row in enumerate(active_brush_rows):
        raw_general_ids = row.get("generalIds")
        if isinstance(raw_general_ids, list):
            general_ids = [str(value) for value in raw_general_ids if str(value or "").strip()]
        else:
            fallback_id = row.get("generalId") or brush.get("generalId") or cfg.get("generalId")
            general_ids = [str(fallback_id)] if str(fallback_id or "").strip() else []
        general_ids = list(dict.fromkeys(general_ids))
        if not general_ids:
            raise RuntimeError(f"第 {row_index + 1} 条已勾选刷黄规则没有选择出征将领")
        if len(general_ids) > BRUSH_MAX_GENERALS_PER_FORMATION:
            raise RuntimeError(
                f"第 {row_index + 1} 条刷黄规则最多选择"
                f"{BRUSH_MAX_GENERALS_PER_FORMATION}名出征将领"
            )
        rule_formations = []
        for general_id in general_ids:
            if known_general_ids and general_id not in known_general_ids:
                raise RuntimeError(
                    f"第 {row_index + 1} 条刷黄规则的将领不在当前账号将领列表中：{general_id}；"
                    "原配置已保留，请先刷新角色状态/重新同步将领后再执行"
                )
            formation = formation_by_general.get(general_id)
            if not formation:
                raise RuntimeError(
                    f"刷黄将领 {general_id} 没有保存过配兵规则；"
                    "请先到“军事-配兵”页为该将领保存兵种和数量"
                )
            rule_formations.append(formation)
            if general_id not in selected_formation_ids:
                selected_formation_ids.add(general_id)
                selected_formations.append(formation)
        rule_comp = dict(brush.get("compositionFilter") or {})
        if isinstance(row.get("compositionFilter"), dict):
            rule_comp.update(row["compositionFilter"])
        by_code = parse_composition_code(
            row.get("compositionCode")
            or brush.get("compositionCode")
            or cfg.get("compositionCode")
            or ""
        )
        if by_code:
            rule_comp.update(by_code)
        for key, default in [("maxFoot", 0), ("maxBow", 5), ("maxCavalry", 0), ("maxChariot", 0)]:
            rule_comp[key] = int(rule_comp.get(key, default))
        rule_comp["requireFoot"] = bool(rule_comp.get("requireFoot", False))
        rule_drops = normalize_drop_keywords(
            row.get("drop") or brush.get("drop") or cfg.get("drop"),
            row.get("drops") or brush.get("drops") or cfg.get("drops"),
        )
        if not rule_drops:
            rule_drops = list(DEFAULT_BRUSH_DROPS)
        rule_levels = normalize_brush_levels(
            row.get("levels"),
            row.get("level", brush.get("level", 1)),
        ) or [1]
        brush_rules.append({
            "enabled": True,
            "sourceRowIndex": int(row.get("idx", row_index)),
            "generalIds": general_ids,
            "generalId": general_ids[0],
            "levels": rule_levels,
            "level": rule_levels[0],
            "drops": rule_drops,
            "drop": (rule_drops or list(DEFAULT_BRUSH_DROPS))[0],
            "compositionCode": (
                f"{rule_comp['maxFoot']}{rule_comp['maxBow']}"
                f"{rule_comp['maxCavalry']}{rule_comp['maxChariot']}"
            ),
            "compositionFilter": rule_comp,
            "formations": rule_formations,
        })
    general_id = str(brush_rules[0].get("generalId") or "") if brush_rules else ""
    comp = dict((brush_rules[0] if brush_rules else {}).get("compositionFilter") or {})
    if not comp:
        comp = dict(brush.get("compositionFilter") or {})
        by_code = parse_composition_code(brush.get("compositionCode") or cfg.get("compositionCode") or "")
        if by_code:
            comp.update(by_code)
        for key, default in [("maxFoot", 0), ("maxBow", 5), ("maxCavalry", 0), ("maxChariot", 0)]:
            comp[key] = int(comp.get(key, default))
        comp["requireFoot"] = bool(comp.get("requireFoot", False))
    daily_limit = max(1, min(int(cfg.get("dailyLimit") or brush.get("dailyLimit") or 500), 500))
    max_equipment_quality = str(cfg.get("maxEquipmentQuality") or brush.get("maxEquipmentQuality") or "良好")
    if max_equipment_quality not in EQUIPMENT_QUALITY_NAMES:
        max_equipment_quality = "良好"
    # Qualities are chosen as a set on the page; the ceiling is kept as the
    # highest selected so older readers see the same limit.  A record without
    # the set expands the ceiling to "that and below", its long-standing meaning.
    raw_discard_qualities = cfg.get("discardEquipmentQualities", brush.get("discardEquipmentQualities"))
    if isinstance(raw_discard_qualities, (list, tuple, set)):
        wanted_qualities = {str(name or "").strip() for name in raw_discard_qualities}
        discard_equipment_qualities = [name for name in EQUIPMENT_QUALITY_NAMES if name in wanted_qualities]
        if discard_equipment_qualities:
            max_equipment_quality = discard_equipment_qualities[-1]
    else:
        discard_equipment_qualities = list(
            EQUIPMENT_QUALITY_NAMES[: EQUIPMENT_QUALITY_NAMES.index(max_equipment_quality) + 1]
        )
    raw_auto_open_names = cfg.get("autoOpenItemNames", brush.get("autoOpenItemNames", []))
    if isinstance(raw_auto_open_names, list):
        auto_open_names = [str(name or "").strip() for name in raw_auto_open_names]
    else:
        auto_open_names = [
            name.strip()
            for name in re.split(r"[,，;；|]+", str(raw_auto_open_names or ""))
        ]
    auto_open_names = list(dict.fromkeys(
        name for name in auto_open_names if name in AUTO_OPEN_ITEM_NAMES
    ))
    copper_floor_raw = cfg["copperFloorWan"] if "copperFloorWan" in cfg else brush.get("copperFloorWan", 1)
    try:
        copper_floor_wan = int(copper_floor_raw)
    except (TypeError, ValueError):
        copper_floor_wan = 1
    if copper_floor_wan not in (1, 10, 20, 50):
        copper_floor_wan = 1
    try:
        reconnect_delay_minutes = int(
            cfg.get("reconnectDelayMinutes", brush.get(
                "reconnectDelayMinutes", DEFAULT_RECONNECT_DELAY_MINUTES
            ))
        )
    except (TypeError, ValueError):
        reconnect_delay_minutes = DEFAULT_RECONNECT_DELAY_MINUTES
    top_brush_levels = normalize_brush_levels(
        brush.get("levels"),
        brush.get("level"),
    )
    if not top_brush_levels and brush_rules:
        top_brush_levels = list(brush_rules[0].get("levels") or [])
    if not top_brush_levels:
        top_brush_levels = [1]
    raw_chain_inventory = (
        dict(cfg.get("chainInventory"))
        if isinstance(cfg.get("chainInventory"), dict)
        else {}
    )
    try:
        chain_keep_count = int(raw_chain_inventory.get("keepCount", 3))
    except (TypeError, ValueError):
        chain_keep_count = 3
    raw_alarm = dict(cfg.get("alarm")) if isinstance(cfg.get("alarm"), dict) else {}
    incoming_mode = str(raw_alarm.get("incomingMode") or "声音+日志")
    if incoming_mode not in {"声音+日志", "仅日志", "关闭"}:
        incoming_mode = "声音+日志"
    military_mode = str(raw_alarm.get("militaryMode") or "出征/返回")
    if military_mode not in {"出征/返回", "仅来袭", "全部"}:
        military_mode = "出征/返回"
    return {
        "sessionId": sess["sessionId"],
        "autoStart": auto_start,
        "reconnectDelayMinutes": max(1, min(reconnect_delay_minutes, 24 * 60)),
        "startHour": max(0, min(int(cfg.get("startHour") or brush.get("startHour") or 0), 23)),
        "dailyLimit": daily_limit,
        "cycleDelaySec": max(1, min(int(cfg.get("cycleDelaySec") or brush.get("cycleDelaySec") or 10), 3600)),
        "returnWaitSec": max(0, min(int(cfg.get("returnWaitSec") or brush.get("returnWaitSec") or 0), 3600)),
        "maxReturnWaitSec": max(30, min(int(cfg.get("maxReturnWaitSec") or brush.get("maxReturnWaitSec") or 300), 7200)),
        "maxDispatchFailures": max(1, min(int(cfg.get("maxDispatchFailures") or brush.get("maxDispatchFailures") or 1), 10)),
        "healWounded": bool(cfg.get("healWounded", True)),
        "healAllIfCountUnknown": bool(cfg.get("healAllIfCountUnknown", True)),
        "replenishTroops": bool(cfg.get("replenishTroops", False)),
        "autoEnergy": bool(cfg.get("autoEnergy", brush.get("autoEnergy", True))),
        "energyThreshold": max(20, min(int(cfg.get("energyThreshold") or brush.get("energyThreshold") or 20), 100)),
        "foodToCopper": bool(cfg.get("foodToCopper", brush.get("foodToCopper", True))),
        "copperFloorWan": copper_floor_wan,
        "cleanMail": bool(cfg.get("cleanMail", brush.get("cleanMail", False))),
        "cleanInventory": bool(cfg.get("cleanInventory", brush.get("cleanInventory", False))),
        "discardItemNames": str(cfg.get("discardItemNames") or brush.get("discardItemNames") or "").strip(),
        "keepItemCount": 0,
        "discardEquipment": bool(cfg.get("discardEquipment", brush.get("discardEquipment", False))),
        "maxEquipmentQuality": max_equipment_quality,
        "discardEquipmentQualities": discard_equipment_qualities,
        "maxEquipmentLevel": max(1, min(int(cfg.get("maxEquipmentLevel") or brush.get("maxEquipmentLevel") or 20), 100)),
        "autoOpenItemNames": auto_open_names,
        "autoOpenEnabled": bool(cfg.get("autoOpenEnabled", brush.get("autoOpenEnabled", False))),
        "chainInventory": {
            "enabled": bool(raw_chain_inventory.get("enabled", False)),
            "keepItemName": str(raw_chain_inventory.get("keepItemName", "青铜钥匙")).strip()[:80],
            "keepCount": max(0, min(chain_keep_count, 9999)),
            "autoOpenEnabled": bool(raw_chain_inventory.get("autoOpenEnabled", False)),
            "autoOpenItemNames": str(raw_chain_inventory.get("autoOpenItemNames", "50两银票")).strip()[:300],
        },
        "alarm": {
            "incomingEnabled": bool(raw_alarm.get("incomingEnabled", True)) and incoming_mode != "关闭",
            "incomingMode": incoming_mode,
            "militaryEnabled": bool(raw_alarm.get("militaryEnabled", True)),
            "militaryMode": military_mode,
            "errorEnabled": bool(raw_alarm.get("errorEnabled", True)),
        },
        "domestic": {
            "enabled": bool((cfg.get("domestic") or {}).get("enabled", False)),
            "emptyBuildingType": int((cfg.get("domestic") or {}).get("emptyBuildingType", 1)),
            "upgradeBuildings": bool((cfg.get("domestic") or {}).get("upgradeBuildings", True)),
            "upgradeTechnology": bool((cfg.get("domestic") or {}).get("upgradeTechnology", False)),
            "technologyId": int((cfg.get("domestic") or {}).get("technologyId", 5)),
            "technologyIds": [
                int(value) for value in (cfg.get("domestic") or {}).get(
                    "technologyIds",
                    [(cfg.get("domestic") or {}).get("technologyId", 5)],
                )
                if str(value).lstrip("-").isdigit() and int(value) in TECHNOLOGY_NAMES
            ],
            "technologyTargetLevel": max(1, min(int((cfg.get("domestic") or {}).get("technologyTargetLevel", 2)), 10)),
            "acceleration": "none",
        },
        "dailyTasks": {
            key: bool((cfg.get("dailyTasks") or brush.get("dailyTasks") or {}).get(key, False))
            for key in DAILY_TASK_NAMES
        },
        "generalVisitGeneralIds": normalize_general_visit_ids(
            cfg.get("generalVisitGeneralIds", brush.get("generalVisitGeneralIds", []))
        ),
        "formations": selected_formations,
        "brush": {
            "startX": int(brush.get("startX", 0)),
            "startY": int(brush.get("startY", 0)),
            "scanLimit": max(1, min(int(brush.get("scanLimit", 80)), 384)),
            "targetKind": str(brush.get("targetKind") or "山贼"),
            "levels": top_brush_levels,
            "level": top_brush_levels[0],
            "drops": normalize_drop_keywords(brush.get("drop") or cfg.get("drop"), brush.get("drops") or cfg.get("drops")) or list(DEFAULT_BRUSH_DROPS),
            "drop": (normalize_drop_keywords(brush.get("drop") or cfg.get("drop"), brush.get("drops") or cfg.get("drops")) or list(DEFAULT_BRUSH_DROPS))[0],
            "generalId": general_id,
            "rows": brush_rows,
            "rules": brush_rules,
            "compositionCode": f"{comp['maxFoot']}{comp['maxBow']}{comp['maxCavalry']}{comp['maxChariot']}",
            "compositionFilter": comp,
        },
    }


def normalize_settings_scope_patch(
    sess: dict[str, Any],
    old_config: dict[str, Any] | None,
    scope: str,
    patch: dict[str, Any] | None,
) -> dict[str, Any]:
    """Normalize one settings page without touching unrelated saved settings."""
    merged = merge_settings_scope_patch(old_config, scope, patch)
    if scope == "brush":
        return normalize_auto_config(sess, {"config": merged})

    # Common-page saves must not heal or validate historical brush selections.
    normalization_source = deepcopy(merged)
    normalization_source["autoStart"] = False
    safe_brush = (
        deepcopy(normalization_source.get("brush"))
        if isinstance(normalization_source.get("brush"), dict)
        else {}
    )
    for key in ("rows", "rules", "generalId"):
        safe_brush.pop(key, None)
    normalization_source["brush"] = safe_brush
    normalization_source.pop("rows", None)
    normalization_source.pop("generalId", None)
    normalized = normalize_auto_config(
        sess,
        {"config": normalization_source},
        resolve_brush_formations=False,
    )

    scoped_fields = SETTINGS_SCOPE_FIELDS[scope]
    for key, value in (old_config or {}).items():
        if key not in scoped_fields:
            normalized[key] = deepcopy(value)
    if scope == "common.daily":
        visit_ids = normalize_general_visit_ids(
            normalized.get("generalVisitGeneralIds")
        )
        normalized["generalVisitGeneralIds"] = visit_ids
        daily_tasks = (
            dict(normalized.get("dailyTasks"))
            if isinstance(normalized.get("dailyTasks"), dict)
            else {}
        )
        # Invalid visit setup affects only this feature.  Keep the other daily
        # switches exactly as submitted and leave general visit disabled until
        # at least one ordered candidate has been selected.  A 国民 role is an
        # intentional terminal skip, so it does not need a candidate ID.
        if (
            daily_tasks.get("generalVisit")
            and not visit_ids
            and not role_is_national_citizen(sess)
        ):
            daily_tasks["generalVisit"] = False
        normalized["dailyTasks"] = daily_tasks
    normalized["sessionId"] = sess["sessionId"]
    return normalized


def settings_change_summary(
    sess: dict[str, Any],
    old_config: dict[str, Any] | None,
    new_config: dict[str, Any],
) -> str:
    old = old_config if isinstance(old_config, dict) else {}
    names = {}
    for general in sess.get("generals") or []:
        name = str(general.get("name") or "").strip()
        for value in (general.get("id"), general.get("idHex")):
            if value not in (None, ""):
                names[str(value)] = name or str(value)

    def rules_by_row(config: dict[str, Any]) -> dict[int, dict[str, Any]]:
        rules = ((config.get("brush") or {}).get("rules") or []) if isinstance(config, dict) else []
        return {
            int(rule.get("sourceRowIndex", index)): rule
            for index, rule in enumerate(rules)
            if isinstance(rule, dict) and bool(rule.get("enabled", True))
        }

    def rule_text(action: str, row: int, rule: dict[str, Any]) -> str:
        general_names = [
            names.get(str(general_id), str(general_id))
            for general_id in rule.get("generalIds") or []
        ]
        levels = brush_levels_text(rule.get("levels"), rule.get("level"))
        composition = str(rule.get("compositionCode") or "不限")
        drops = [str(value) for value in rule.get("drops") or [] if str(value).strip()]
        drop_text = f"掉落{'、'.join(drops)}皆可" if drops else "掉落不限"
        return (
            f"{action}刷黄-第{row + 1}编队-"
            f"{'、'.join('将领' + name for name in general_names) or '未选择将领'}｜"
            f"目标{levels}级山贼{composition}{drop_text}"
        )

    changes: list[str] = []
    old_rules = rules_by_row(old)
    new_rules = rules_by_row(new_config)
    for row in sorted(set(old_rules) | set(new_rules)):
        before = old_rules.get(row)
        after = new_rules.get(row)
        if before is None and after is not None:
            changes.append(rule_text("开启", row, after))
        elif before is not None and after is None:
            changes.append(f"关闭刷黄-第{row + 1}编队")
        elif before != after and after is not None:
            changes.append(rule_text("修改", row, after))

    old_domestic = bool((old.get("domestic") or {}).get("enabled"))
    new_domestic = bool((new_config.get("domestic") or {}).get("enabled"))
    if old_domestic != new_domestic:
        changes.append(f"{'开启' if new_domestic else '关闭'}自动内政")
    old_technology = bool((old.get("domestic") or {}).get("upgradeTechnology"))
    new_technology = bool((new_config.get("domestic") or {}).get("upgradeTechnology"))
    if old_technology != new_technology:
        changes.append(f"{'开启' if new_technology else '关闭'}升级科技")
    old_reconnect = int(old.get("reconnectDelayMinutes") or DEFAULT_RECONNECT_DELAY_MINUTES)
    new_reconnect = int(new_config.get("reconnectDelayMinutes") or DEFAULT_RECONNECT_DELAY_MINUTES)
    if old_reconnect != new_reconnect:
        changes.append(f"掉线重连倒计时改为{new_reconnect}分钟")

    toggle_labels = {
        "healWounded": "治疗伤兵",
        "replenishTroops": "自动补兵",
        "autoEnergy": "自动加体",
        "foodToCopper": "粮食转铜",
        "cleanMail": "清理邮件",
        "cleanInventory": "清理宝库",
        "discardEquipment": "丢弃装备",
        "autoOpenEnabled": "自动开箱",
    }
    for key, label in toggle_labels.items():
        if bool(old.get(key)) != bool(new_config.get(key)):
            changes.append(f"{'开启' if new_config.get(key) else '关闭'}{label}")

    daily_labels = {
        "autoSignIn": "自动签到",
        "arenaCoins": "领竞技币",
        "autoDonate": "自动捐献",
        "salary": "领取俸禄",
        "nationalCollect": "国家征收",
        "cityLordCollect": "城主征收",
        "generalVisit": "名将拜访",
    }
    old_daily = old.get("dailyTasks") if isinstance(old.get("dailyTasks"), dict) else {}
    new_daily = new_config.get("dailyTasks") if isinstance(new_config.get("dailyTasks"), dict) else {}
    for key, label in daily_labels.items():
        if bool(old_daily.get(key)) != bool(new_daily.get(key)):
            changes.append(f"{'开启' if new_daily.get(key) else '关闭'}{label}")
    old_visit_ids = normalize_general_visit_ids(old.get("generalVisitGeneralIds"))
    new_visit_ids = normalize_general_visit_ids(new_config.get("generalVisitGeneralIds"))
    if old_visit_ids != new_visit_ids:
        changes.append(f"名将拜访优先级改为{','.join(new_visit_ids) if new_visit_ids else '未选择'}")

    return "保存设置：" + ("！".join(changes) + "！" if changes else "配置无变化")


def task_public(task: dict[str, Any]) -> dict[str, Any]:
    with TASK_LOCK:
        return {
            k: v
            for k, v in task.items()
            if k not in {"thread", "stopEvent"} and not str(k).startswith("_")
        }


def task_status_public(task: dict[str, Any]) -> dict[str, Any]:
    """Compact task payload for the frequent status poll."""
    fields = (
        "taskId", "type", "sessionId", "status", "createdAt", "updatedAt",
        "startedAt", "finishedAt", "cycle", "logs", "error", "stopReason",
        "schedulerState", "schedulerRunnable", "schedulerMessage",
        "dungeonMode", "currentDungeonStage", "lastDungeonClearSelection",
        "lastClearedDungeonStage", "clearCompletedCount",
        "lastDungeonDefeat", "defeatConfirmed", "completed",
    )
    with TASK_LOCK:
        payload = {
            key: json_safe(task.get(key))
            for key in fields
            if task.get(key) is not None
        }
    if isinstance(payload.get("logs"), list):
        payload["logs"] = payload["logs"][-TASK_STATUS_LOG_LINES:]
    return payload


def prune_auto_tasks() -> None:
    """Keep active tasks and only a small recent terminal history per account."""
    with TASK_LOCK:
        inactive_by_session: dict[str, list[dict[str, Any]]] = {}
        for task in AUTO_TASKS.values():
            if str(task.get("status") or "") in ACTIVE_TASK_STATUSES:
                continue
            sid = str(
                task.get("sessionId")
                or task.get("config", {}).get("sessionId")
                or ""
            )
            inactive_by_session.setdefault(sid, []).append(task)
        remove_ids: list[str] = []
        for tasks in inactive_by_session.values():
            tasks.sort(
                key=lambda item: int(
                    item.get("updatedAt") or item.get("createdAt") or 0
                ),
                reverse=True,
            )
            remove_ids.extend(
                str(task.get("taskId") or "")
                for task in tasks[TASK_HISTORY_PER_SESSION:]
            )
        for task_id in remove_ids:
            if task_id:
                AUTO_TASKS.pop(task_id, None)


