def resident_task_key(task: dict[str, Any]) -> str:
    return str(AUTO_TASK_OVERVIEW_KEYS.get(str(task.get("type") or "")) or task.get("type") or "")


def resident_task_priority(task: dict[str, Any]) -> int:
    return int(RESIDENT_TASK_PRIORITIES.get(resident_task_key(task), 0))


def cached_general_states(sess: dict[str, Any], general_ids: list[str]) -> list[dict[str, Any]]:
    states = []
    generals = list(sess.get("generals") or [])
    for raw_id in general_ids:
        general_id = str(raw_id or "").strip()
        if not general_id:
            continue
        general = next((
            item
            for item in generals
            if str(item.get("id")) == general_id or str(item.get("idHex")) == general_id
        ), None)
        states.append({
            "id": general_id,
            "name": (general or {}).get("name") or general_id,
            "status": (general or {}).get("displayStatus") or (general or {}).get("statusText") or "未知",
            "found": bool(general),
        })
    return states


def command_center_set_state(
    task: dict[str, Any],
    state: str,
    *,
    general_ids: list[str] | None = None,
    runnable: bool = False,
    message: str = "",
    next_check_at: int | None = None,
) -> None:
    previous = (
        str(task.get("schedulerState") or ""),
        bool(task.get("schedulerRunnable")),
        tuple(str(item) for item in task.get("schedulerGeneralIds") or []),
        str(task.get("schedulerMessage") or ""),
        task.get("schedulerNextCheckAt"),
    )
    task["schedulerState"] = str(state or "unknown")
    task["schedulerRunnable"] = bool(runnable)
    task["schedulerPriority"] = resident_task_priority(task)
    if general_ids is not None:
        task["schedulerGeneralIds"] = list(dict.fromkeys(
            str(item or "").strip() for item in general_ids if str(item or "").strip()
        ))
    if message:
        task["schedulerMessage"] = str(message)
    elif "schedulerMessage" not in task:
        task["schedulerMessage"] = ""
    if next_check_at is not None:
        task["schedulerNextCheckAt"] = int(next_check_at)
    elif state not in {"cooldown", "daily_done"}:
        task.pop("schedulerNextCheckAt", None)
    current = (
        str(task.get("schedulerState") or ""),
        bool(task.get("schedulerRunnable")),
        tuple(str(item) for item in task.get("schedulerGeneralIds") or []),
        str(task.get("schedulerMessage") or ""),
        task.get("schedulerNextCheckAt"),
    )
    if current == previous:
        return
    task["schedulerUpdatedAt"] = now_ms()
    with COMMAND_CENTER_CONDITION:
        COMMAND_CENTER_CONDITION.notify_all()


def _command_center_claims_for_session(session_id: str) -> dict[str, dict[str, Any]]:
    return COMMAND_CENTER_CLAIMS.setdefault(str(session_id or ""), {})


def _command_center_blockers(task: dict[str, Any], general_ids: list[str]) -> list[dict[str, Any]]:
    sid = str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "")
    task_id = str(task.get("taskId") or "")
    ids = set(str(item or "").strip() for item in general_ids if str(item or "").strip())
    blockers: list[dict[str, Any]] = []
    for claim_task_id, claim in _command_center_claims_for_session(sid).items():
        if claim_task_id == task_id:
            continue
        claim_ids = set(str(item) for item in claim.get("generalIds") or [])
        if ids & claim_ids:
            blockers.append({
                "taskId": claim_task_id,
                "taskKey": claim.get("taskKey"),
                "priority": claim.get("priority"),
                "state": "dispatch-claim",
                "generalIds": sorted(ids & claim_ids),
            })
    priority = resident_task_priority(task)
    sess = SESSIONS.get(sid)
    for other in list(AUTO_TASKS.values()):
        other_id = str(other.get("taskId") or "")
        other_sid = str(other.get("sessionId") or other.get("config", {}).get("sessionId") or "")
        if other_id == task_id or other_sid != sid:
            continue
        if str(other.get("status") or "") not in ACTIVE_TASK_STATUSES:
            continue
        other_priority = resident_task_priority(other)
        if other_priority <= priority:
            continue
        other_ids = set(str(item) for item in other.get("schedulerGeneralIds") or [])
        shared = ids & other_ids
        if not shared:
            continue
        other_state = str(other.get("schedulerState") or "checking")
        blocks = bool(other.get("schedulerRunnable")) or other_state in {
            "checking",
            "ready",
            "dispatching",
            "fighting",
        }
        if other_state == "waiting_generals" and sess:
            required_states = cached_general_states(sess, sorted(other_ids))
            blocks = (
                len(required_states) == len(other_ids)
                and all(
                    item.get("found") and item.get("status") == "闲"
                    for item in required_states
                )
            )
        if blocks:
            blockers.append({
                "taskId": other_id,
                "taskKey": resident_task_key(other),
                "priority": other_priority,
                "state": other_state,
                "generalIds": sorted(shared),
            })
    blockers.sort(key=lambda item: (-int(item.get("priority") or 0), str(item.get("taskId") or "")))
    return blockers


def command_center_acquire(task: dict[str, Any], general_ids: list[str]) -> bool:
    sid = str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "")
    task_id = str(task.get("taskId") or "")
    normalized_ids = list(dict.fromkeys(
        str(item or "").strip() for item in general_ids if str(item or "").strip()
    ))
    if not sid or not task_id or not normalized_ids:
        return False
    command_center_set_state(
        task,
        "ready",
        general_ids=normalized_ids,
        runnable=True,
        message="已满足本任务条件，等待指挥中心下发出征权",
    )
    last_blocker_signature = ""
    last_busy_signature = ""
    while not task.get("stopEvent").is_set():
        with COMMAND_CENTER_CONDITION:
            sess = SESSIONS.get(sid)
            states = cached_general_states(sess, normalized_ids) if sess else []
            if (
                states
                and (
                    len(states) != len(normalized_ids)
                    or not all(
                        item.get("found") and item.get("status") == "闲"
                        for item in states
                    )
                )
            ):
                task["schedulerState"] = "waiting_generals"
                task["schedulerRunnable"] = False
                task["schedulerMessage"] = "等待出征将领回闲后再申请出征权"
                task["schedulerUpdatedAt"] = now_ms()
                busy_signature = json.dumps(states, ensure_ascii=False, sort_keys=True)
                if busy_signature != last_busy_signature:
                    last_busy_signature = busy_signature
                    summary = "，".join(
                        f"{item.get('name')}={item.get('status')}"
                        for item in states
                    )
                    task_log(
                        task,
                        f"指挥中心：将领尚未回闲，暂不占用出征权；"
                        f"{summary or '状态未知'}",
                    )
                COMMAND_CENTER_CONDITION.wait(timeout=2.0)
                continue
            blockers = _command_center_blockers(task, normalized_ids)
            if not blockers:
                _command_center_claims_for_session(sid)[task_id] = {
                    "taskId": task_id,
                    "taskKey": resident_task_key(task),
                    "priority": resident_task_priority(task),
                    "generalIds": normalized_ids,
                    "claimedAt": now_ms(),
                }
                task["schedulerState"] = "dispatching"
                task["schedulerRunnable"] = True
                task["schedulerMessage"] = "指挥中心已下发出征权"
                task["schedulerUpdatedAt"] = now_ms()
                task["schedulerBlockers"] = []
                COMMAND_CENTER_CONDITION.notify_all()
                break
            task["schedulerState"] = "waiting_priority"
            task["schedulerRunnable"] = True
            task["schedulerMessage"] = "等待更高优先级共享将领任务"
            task["schedulerBlockers"] = blockers
            task["schedulerUpdatedAt"] = now_ms()
            signature = json.dumps(blockers, ensure_ascii=False, sort_keys=True)
            if signature != last_blocker_signature:
                last_blocker_signature = signature
                names = "、".join(
                    f"{item.get('taskKey')}({item.get('state')})"
                    for item in blockers
                )
                task_log(task, f"指挥中心：共享将领暂让位给更高优先级任务 {names}")
            COMMAND_CENTER_CONDITION.wait(timeout=2.0)
    else:
        return False
    task_log(
        task,
        f"指挥中心：已取得出征权，任务={resident_task_key(task)}，"
        f"优先级={resident_task_priority(task)}，将领={','.join(normalized_ids)}",
    )
    return True


def select_dispatchable_brush_rule_index(
    task: dict[str, Any],
    sess: dict[str, Any],
    brush_rules: list[dict[str, Any]],
    start_index: int,
) -> int | None:
    """Choose an idle formation; prepared formations wait for a real target."""
    if not brush_rules:
        return None
    prepared_rules = task.setdefault("brushPreparedRules", {})
    in_flight_general_ids = {
        str(general_id)
        for flight in (task.get("brushInFlight") or {}).values()
        if isinstance(flight, dict)
        for general_id in flight.get("generalIds") or []
    }
    for offset in range(len(brush_rules)):
        rule_index = (int(start_index) + offset) % len(brush_rules)
        retry_at = int(
            (task.get("brushRuleRetryAt") or {}).get(str(rule_index)) or 0
        )
        if retry_at > now_ms():
            continue
        general_ids = list(dict.fromkeys(
            str(general_id)
            for general_id in brush_rules[rule_index].get("generalIds") or []
            if str(general_id or "").strip()
        ))
        if not general_ids:
            continue
        if in_flight_general_ids.intersection(general_ids):
            prepared_rules.pop(str(rule_index), None)
            continue
        states = cached_general_states(sess, general_ids)
        if (
            len(states) != len(general_ids)
            or not all(
                item.get("found") and item.get("status") == "闲"
                for item in states
            )
        ):
            prepared_rules.pop(str(rule_index), None)
            continue
        if _command_center_blockers(task, general_ids):
            continue
        if (
            prepared_rules.get(str(rule_index))
            and not brush_rule_has_prepared_target(
                task,
                sess,
                brush_rules[rule_index],
            )
        ):
            continue
        return rule_index
    return None


def command_center_release(
    task: dict[str, Any],
    *,
    state: str = "checking",
    runnable: bool = False,
    message: str = "",
) -> None:
    sid = str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "")
    task_id = str(task.get("taskId") or "")
    with COMMAND_CENTER_CONDITION:
        claims = COMMAND_CENTER_CLAIMS.get(sid) or {}
        claims.pop(task_id, None)
        if not claims:
            COMMAND_CENTER_CLAIMS.pop(sid, None)
        COMMAND_CENTER_CONDITION.notify_all()
    command_center_set_state(task, state, runnable=runnable, message=message)


def command_center_wait_generals_idle(
    task: dict[str, Any],
    sess: dict[str, Any],
    general_ids: list[str],
    action_name: str,
) -> bool:
    normalized_ids = list(dict.fromkeys(
        str(item or "").strip() for item in general_ids if str(item or "").strip()
    ))
    last_signature = ""
    while not task.get("stopEvent").is_set():
        states = cached_general_states(sess, normalized_ids)
        if states and len(states) == len(normalized_ids) and all(item.get("status") == "闲" for item in states):
            command_center_set_state(
                task,
                "checking",
                general_ids=normalized_ids,
                runnable=True,
                message=f"{action_name}将领均为空闲，检查其他条件",
            )
            return True
        command_center_set_state(
            task,
            "waiting_generals",
            general_ids=normalized_ids,
            runnable=False,
            message=f"{action_name}等待出征将领回闲",
        )
        signature = json.dumps(states, ensure_ascii=False, sort_keys=True)
        if signature != last_signature:
            last_signature = signature
            summary = "，".join(f"{item.get('name')}={item.get('status')}" for item in states)
            task_log(task, f"指挥中心：{action_name}暂不可执行，等待将领回闲；{summary or '状态未知'}")
        with GENERAL_STATE_CONDITION:
            GENERAL_STATE_CONDITION.wait(timeout=CLIENT_HEARTBEAT_INTERVAL_SEC + 2)
    return False


def command_center_snapshot(session_id: str) -> dict[str, Any]:
    sid = str(session_id or "")
    tasks = []
    for task in list(AUTO_TASKS.values()):
        task_sid = str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "")
        if task_sid != sid or resident_task_priority(task) <= 0:
            continue
        if str(task.get("status") or "") not in ACTIVE_TASK_STATUSES:
            continue
        tasks.append({
            "taskId": task.get("taskId"),
            "key": resident_task_key(task),
            "priority": resident_task_priority(task),
            "state": task.get("schedulerState") or "checking",
            "runnable": bool(task.get("schedulerRunnable")),
            "message": task.get("schedulerMessage") or "",
            "generalIds": list(task.get("schedulerGeneralIds") or []),
            "updatedAt": task.get("schedulerUpdatedAt") or task.get("updatedAt"),
            "nextCheckAt": task.get("schedulerNextCheckAt"),
        })
    tasks.sort(key=lambda item: (-int(item.get("priority") or 0), int(item.get("updatedAt") or 0)))
    with COMMAND_CENTER_CONDITION:
        claims = [
            dict(claim)
            for claim in (COMMAND_CENTER_CLAIMS.get(sid) or {}).values()
        ]
    claims.sort(key=lambda item: (-int(item.get("priority") or 0), int(item.get("claimedAt") or 0)))
    return {
        "enabled": True,
        "policy": ["打矿", "无损", "刷黄", "副本"],
        "priorities": dict(RESIDENT_TASK_PRIORITIES),
        "tasks": tasks,
        "claims": claims,
        "updatedAt": now_ms(),
    }


def active_tasks_for_session(session_id: str) -> list[dict[str, Any]]:
    sid = str(session_id or "")
    with TASK_LOCK:
        return _active_tasks_for_session_locked(sid)


def _active_tasks_for_session_locked(session_id: str) -> list[dict[str, Any]]:
    """Return active tasks while the caller owns TASK_LOCK."""
    sid = str(session_id or "")
    out = []
    for task in AUTO_TASKS.values():
        task_sid = str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "")
        if task_sid == sid and str(task.get("status") or "") in ACTIVE_TASK_STATUSES:
            out.append({k: v for k, v in task.items() if k not in {"thread", "stopEvent"}})
    return out


def request_stop_tasks_for_session_type(session_id: str, task_type: str, reason: str) -> list[str]:
    sid = str(session_id or "")
    requested: list[dict[str, Any]] = []
    with TASK_LOCK:
        for task in AUTO_TASKS.values():
            task_sid = str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "")
            if task_sid != sid or str(task.get("type") or "") != str(task_type or ""):
                continue
            if str(task.get("status") or "") not in ACTIVE_TASK_STATUSES:
                continue
            stop_event = task.get("stopEvent")
            if stop_event:
                stop_event.set()
            task["status"] = "stopping"
            task["updatedAt"] = now_ms()
            requested.append(task)
    for task in requested:
        task_log(task, reason)
    if requested:
        persist_runtime_state()
    return [str(task.get("taskId") or "") for task in requested]


def user_task_stack_message(task: dict[str, Any], state: str) -> str:
    """Translate scheduler wording into concise user-facing activity text."""
    message = str(task.get("schedulerMessage") or "")
    if not message:
        logs = list(task.get("logs") or [])
        message = re.sub(r"^\[\d\d:\d\d:\d\d\]\s*", "", str(logs[-1])) if logs else ""
    message = message.replace("已满足本任务条件，等待指挥中心下发出征权", "条件已满足，等待执行")
    message = message.replace("指挥中心已下发出征权", "正在执行")
    message = message.replace("等待指挥中心安排", "等待执行")
    message = re.sub(r"[；;，,]?\s*指挥中心(?:优先级|现在允许)[^；;。]*", "", message)
    message = re.sub(r"指挥中心[：:]\s*", "", message)
    message = message.replace("指挥中心", "后台")
    if message:
        return message
    return {
        "checking": "正在检查执行条件",
        "ready": "等待执行",
        "dispatching": "正在下发任务",
        "fighting": "正在执行",
        "cooldown": "冷却中",
        "waiting_account": "等待账号恢复在线",
        "waiting_generals": "等待将领回闲",
        "waiting_priority": "等待前序任务完成",
        "waiting_target": "等待可用目标",
        "capacity_done": "资源点额度已满",
        "daily_done": "今日已完成",
        "starting": "正在启动",
        "queued": "排队中",
        "running": "正在执行",
        "stopping": "正在停止",
        "stopped": "已停止",
        "error": "执行异常",
    }.get(state, "等待执行")


def task_stack_for_session(session_id: str, tasks: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Build a user-facing queue from real active backend instructions."""
    sid = str(session_id or "")
    with COMMAND_CENTER_CONDITION:
        claimed_ids = set((COMMAND_CENTER_CLAIMS.get(sid) or {}).keys())
    stack: list[dict[str, Any]] = []
    for task in tasks:
        raw_type = str(task.get("type") or "")
        default_key = AUTO_TASK_OVERVIEW_KEYS.get(raw_type) or raw_type or "task"
        key, name, category = TASK_STACK_TYPE_META.get(
            raw_type,
            (default_key, default_key or "后台任务", "other"),
        )
        if (
            raw_type == "dungeon"
            and normalize_dungeon_mode((task.get("config") or {}).get("mode"))
            == DUNGEON_MODE_CLEAR
        ):
            name = "打通副本"
        state = str(task.get("schedulerState") or task.get("status") or "queued")
        task_id = str(task.get("taskId") or "")
        current = task_id in claimed_ids or state in {"dispatching", "fighting"}
        message = user_task_stack_message(task, state)
        cooldown_until = None
        remaining_attempts = None
        if key == "lossless":
            lossless_status = task.get("lastLosslessStatus") if isinstance(task.get("lastLosslessStatus"), dict) else {}
            remaining_attempts = task.get("losslessRemainingAttempts")
            if remaining_attempts is None:
                remaining_attempts = lossless_status.get("remainingAttempts")
            if state == "cooldown":
                cooldown_until = task.get("schedulerNextCheckAt")
                if not cooldown_until:
                    status_updated_at = int(lossless_status.get("updatedAt") or 0)
                    cooldown_sec = int(lossless_status.get("cooldownSec") or 0)
                    if status_updated_at > 0 and cooldown_sec > 0:
                        cooldown_until = status_updated_at + cooldown_sec * 1000
        stack.append({
            "taskId": task_id,
            "taskType": raw_type,
            "key": key,
            "name": name,
            "category": category,
            "status": str(task.get("status") or "queued"),
            "state": state,
            "message": message,
            "current": current,
            "runnable": bool(task.get("schedulerRunnable")),
            "cycle": int(task.get("cycle") or 0),
            "cooldownUntil": int(cooldown_until) if cooldown_until else None,
            "remainingAttempts": int(remaining_attempts) if remaining_attempts is not None else None,
            "createdAt": int(task.get("createdAt") or 0),
            "updatedAt": int(task.get("schedulerUpdatedAt") or task.get("updatedAt") or 0),
        })

    def stack_order(item: dict[str, Any]) -> tuple[int, int, int]:
        state = str(item.get("state") or "")
        if item.get("current"):
            bucket = 0
        elif state in {"checking", "ready", "running", "queued", "starting"}:
            bucket = 1
        elif state in {"waiting_account", "waiting_generals", "waiting_priority"}:
            bucket = 2
        elif state == "waiting_target":
            bucket = 3
        elif state == "cooldown":
            bucket = 4
        elif state == "daily_done":
            bucket = 5
        else:
            bucket = 6
        priority = int(RESIDENT_TASK_PRIORITIES.get(str(item.get("key") or ""), 0))
        return bucket, -priority, int(item.get("createdAt") or 0)

    stack.sort(key=stack_order)
    for index, item in enumerate(stack, start=1):
        item["position"] = index
    return stack


def sync_recent_important_notices_from_logs(account_key: str) -> None:
    """Seed the notice center from recent durable logs once per server run."""
    key = str(account_key or "")
    if not key or key in IMPORTANT_NOTICE_LOGS_MIGRATED_KEYS or not ACCOUNT_STATE_DB_READY:
        return
    with ACCOUNT_STATE_DB_LOCK, _account_state_db_connect() as connection:
        rows = connection.execute(
            """
            SELECT time, message FROM account_logs
            WHERE account_key=?
            ORDER BY time DESC, id DESC LIMIT 100
            """,
            (key,),
        ).fetchall()
    task_patterns = [
        ("状态机阻止刷黄", "task:brushYellow", "刷黄已中止"),
        ("打矿任务异常，已中断", "task:mine", "打矿已中止"),
        ("无损任务失败", "task:lossless", "无损已中止"),
        ("副本循环任务失败", "task:dungeon", "副本已中止"),
        ("打通副本暂停", "task:dungeon", "打通副本已暂停"),
        ("掠夺循环任务失败", "task:raid", "掠夺已中止"),
        ("配兵任务失败", "task:formations", "配兵已中止"),
    ]
    recovery_patterns = [
        ("自动刷黄启动", "task:brushYellow"),
        ("打矿常驻任务启动", "task:mine"),
        ("无损常驻任务启动", "task:lossless"),
        ("副本循环任务启动", "task:dungeon"),
        ("掠夺循环任务启动", "task:raid"),
        ("配兵任务启动", "task:formations"),
    ]
    for row in reversed(rows):
        timestamp = int(row["time"] or now_ms())
        message = str(row["message"] or "")
        for marker, notice_key, title in task_patterns:
            if marker in message:
                database_upsert_important_notice(
                    key,
                    notice_key,
                    severity="error",
                    title=title,
                    message=message,
                    source="task-history",
                    at_ms=timestamp,
                )
        for marker, notice_key in recovery_patterns:
            if marker in message:
                database_resolve_important_notice(key, notice_key, at_ms=timestamp)
        if message.startswith("自动签到失败"):
            upsert_daily_feature_important_notice(
                key,
                "autoSignIn",
                "自动签到",
                message=message,
                source="automation-history",
                at_ms=timestamp,
            )
        elif message.startswith(("自动签到完成", "自动签到重复")):
            database_resolve_important_notice(key, "daily:autoSignIn", at_ms=timestamp)
        if message.startswith("领竞技币失败"):
            database_upsert_important_notice(
                key, "daily:arenaCoins", severity="warning",
                title="领取竞技币未完成", message=message,
                source="automation-history", at_ms=timestamp,
            )
        elif message.startswith(("领竞技币完成", "领竞技币重复")):
            database_resolve_important_notice(key, "daily:arenaCoins", at_ms=timestamp)
        daily_history_prefixes = {
            "自动捐献失败": ("daily:autoDonate", "自动捐献未完成"),
            "自动捐献：": ("daily:autoDonate", "自动捐献未完成"),
            "领取俸禄失败": ("daily:salary", "领取俸禄未完成"),
            "国家征收失败": ("daily:nationalCollect", "国家征收未完成"),
            "城主征收失败": ("daily:cityLordCollect", "城主征收未完成"),
            "名将拜访失败": ("daily:generalVisit", "名将拜访未完成"),
        }
        for marker, (notice_key, title) in daily_history_prefixes.items():
            if message.startswith(marker):
                database_upsert_important_notice(
                    key, notice_key, severity="warning", title=title,
                    message=message, source="automation-history", at_ms=timestamp,
                )
        daily_success_prefixes = {
            "自动捐献完成": "daily:autoDonate",
            "领取俸禄完成": "daily:salary",
            "国家征收完成": "daily:nationalCollect",
            "城主征收完成": "daily:cityLordCollect",
            "名将拜访成功": "daily:generalVisit",
        }
        for marker, notice_key in daily_success_prefixes.items():
            if message.startswith(marker):
                database_resolve_important_notice(key, notice_key, at_ms=timestamp)
    IMPORTANT_NOTICE_LOGS_MIGRATED_KEYS.add(key)


def important_notice_advice(notice_key: str) -> str:
    key = str(notice_key or "")
    if key == "account:connection":
        return "检查当前IP、VPN和网络；连接恢复后提示会自动消失。"
    if key == "account:network":
        return "检查当前IP、VPN和网络；心跳确认恢复后，暂停的常驻任务会自动恢复。"
    if key == "account:proxy":
        return "刷新节点检测或更换可用IP后重新启动相关任务。"
    if key.startswith("task:brushYellow:troopShortage:"):
        return "到“军事-配兵”检查该编队所需兵种和数量；闲兵补足或配置修正后，提示会自动消失。"
    if key.startswith(BRUSH_HIGH_LEVEL_TROOPS_NOTICE_PREFIX):
        return "到“军事-配兵”将该刷黄编队内每名将领的配兵改为至少1000；保存刷黄设置或高等级出征成功后，提示会自动消失。"
    if key.startswith("task:brushYellow"):
        return "根据中止原因检查IP、将领状态、体力、闲兵和刷黄编队，修正后重新启动刷黄。"
    if key == "task:general":
        return "检查将领伤兵、体力、忠诚和对应补给品；条件恢复后重新启动将领维护。"
    if key == "task:inventory":
        return "检查宝库容量、物品或装备识别结果及背包整理配置；该任务不依赖将领体力。"
    if key == "task:alarm":
        return "检查账号在线状态、军情读取和警报配置；该任务不依赖将领体力。"
    if key in {
        "task:mine", "task:raid", "task:lossless", "task:dungeon",
        "task:formations", "task:ministry", "task:captives",
        "task:autoDomestic", "task:autoTechnology",
    }:
        return "根据原因检查将领状态、配兵和任务配置，修正后重新启动该任务。"
    if key.startswith("daily:"):
        return "确认账号在线后手动重试；成功或确认已经领取后，提示会自动消失。"
    return "请根据提示原因处理，任务恢复正常后该提示会自动消失。"


def important_notice_summary(notice: dict[str, Any]) -> str:
    title = str(notice.get("title") or "重要提示").strip()
    message = re.sub(r"\s+", " ", str(notice.get("message") or "")).strip()
    troop_shortage = re.search(
        r"配兵中止：目标\s*(\d+)\s*([^，；]+?)[，；].*?可用([^=，；]+)=(\d+)",
        message,
    )
    if troop_shortage:
        target_count, _target_type, available_type, available_count = troop_shortage.groups()
        return f"{title}：{available_type}闲兵不足（需要{target_count}，当前{available_count}）"
    ip_failure = re.search(r"手动选择的IP\s+(.+?)\s+无法连接游戏服", message)
    if ip_failure:
        return f"{title}：IP节点“{ip_failure.group(1)}”无法连接游戏服"
    for prefix in (
        "状态机阻止刷黄：", "打矿任务异常，已中断：",
        "自动签到失败：", "领竞技币失败：",
    ):
        if message.startswith(prefix):
            message = message[len(prefix):].strip()
            break
    reason = re.split(r"[；。]", message, maxsplit=1)[0].strip()
    if not reason:
        return title
    summary = reason if reason.startswith(title) else f"{title}：{reason}"
    return summary if len(summary) <= 72 else summary[:69] + "..."


def _shared_result_notice_is_misattributed(notice: dict[str, Any]) -> bool:
    """Reject legacy task notices whose feature identity contradicts text.

    Before the shared wake-owner fix, a result with no active matching row was
    written to the owner's fallback row.  The durable notice table therefore
    contains a few cross-feature records (for example a dungeon message under
    ``task:autoDomestic``).  These records are presentation corruption, not
    evidence that the displayed task failed.  Keep the check deliberately
    narrow so unrelated historical task messages remain visible.
    """

    key = str(notice.get("key") or "")
    message = str(notice.get("message") or "")
    message_lower = message.lower()
    if not key.startswith("task:"):
        return False
    if message.startswith((
        "网络暂时不可用，已暂停后台任务",
        "账号连接中断，已停止后台任务",
    )):
        # These are account-lifecycle transitions.  A former wake-owner row
        # is not evidence that inventory, alarm, domestic, or any other one
        # feature failed.  The account-level connection/network notice is the
        # sole owner of this condition.
        return True
    if "无法连接游戏服" in message and (
        "ip" in message_lower or "网络" in message or "http" in message_lower
    ):
        # Transport state is account-scoped; it must never be represented as
        # a feature-specific terminal failure.
        return True
    if "副本前置操作已开始" in message:
        return key != "task:dungeon"
    if "无损前置操作已开始" in message:
        return key != "task:lossless"
    if "刷黄战后步骤" in message or "刷黄战后新维护步骤" in message:
        return key != "task:brushYellow"
    if "将领维护" in message:
        # General healing/energy/loyalty is an independent resident feature.
        # Inventory cleanup and military-intel polling neither select nor use
        # a general, so an old wake-owner notice such as
        # ``task:inventory -> 将领维护检查到...体力...`` is impossible evidence
        # for those rows.  Keep the real general notice, but retire every
        # cross-feature copy produced by the legacy fallback router.
        return key != "task:general"
    return False


def current_important_notices(sess: dict[str, Any]) -> list[dict[str, Any]]:
    sid = str(sess.get("sessionId") or "")
    account_key = account_storage_key(sess=sess)
    sync_recent_important_notices_from_logs(account_key)
    notices = database_read_active_important_notices(account_key)
    # Hide and resolve records produced by the old fallback routing bug.  This
    # also repairs accounts that were already running before the code fix; no
    # separate manual database cleanup is required after the new server code
    # is deployed.
    filtered_notices: list[dict[str, Any]] = []
    for notice in notices:
        if _shared_result_notice_is_misattributed(notice):
            database_resolve_important_notice(
                account_key,
                str(notice.get("key") or ""),
            )
            continue
        filtered_notices.append(notice)
    notices = filtered_notices
    with ACCOUNT_LOCK:
        acc = dict(ACCOUNTS.get(sid) or {})
    status = str(acc.get("status") or "")
    reconnect_state = str(acc.get("reconnectState") or "")
    if status in {"offline", "error"} or reconnect_state in {"countdown", "reconnecting"}:
        reason = str(
            acc.get("lastError")
            or acc.get("reconnectReason")
            or "账号当前不在线"
        )
        dismissed = database_read_important_notice_record(
            account_key,
            "account:connection",
        )
        if not (
            dismissed
            and not dismissed.get("active")
            and dismissed.get("source") == "user-dismiss"
            and dismissed.get("message") == reason
        ):
            notices.append({
                "id": "dynamic-account-connection",
                "key": "account:connection",
                "severity": "critical",
                "title": "账号连接异常",
                "message": reason,
                "source": "account",
                "createdAt": int(acc.get("sessionInvalidatedAt") or acc.get("reconnectAt") or now_ms()),
                "updatedAt": now_ms(),
                "active": True,
            })
    # A transient request timeout keeps the account online while workers are
    # paused.  Surface one account-level warning instead of manufacturing a
    # separate "task aborted" notice for every resident row.
    if (
        status not in {"offline", "error"}
        and reconnect_state not in {"countdown", "reconnecting"}
        and (acc.get("networkDegraded") or acc.get("responseUnconfirmed"))
    ):
        network_notice_key = "account:network"
        network_reason = str(
            acc.get("lastError")
            or (
                "游戏服响应未确认，已暂停自动操作，等待心跳复核"
                if acc.get("responseUnconfirmed")
                else "当前网络请求失败，已暂停自动操作，等待心跳恢复"
            )
        )
        dismissed = database_read_important_notice_record(
            account_key,
            network_notice_key,
        )
        if not (
            dismissed
            and not dismissed.get("active")
            and dismissed.get("source") == "user-dismiss"
            and dismissed.get("message") == network_reason
        ):
            network_checked_at = (
                (acc.get("lastNetworkFailure") or {}).get("checkedAt")
                if isinstance(acc.get("lastNetworkFailure"), dict)
                else None
            )
            if not network_checked_at and isinstance(
                acc.get("lastHeartbeat"), dict
            ):
                network_checked_at = (
                    acc.get("lastHeartbeat") or {}
                ).get("checkedAt")
            notices.append({
                "id": "dynamic-account-network",
                "key": network_notice_key,
                "severity": "warning",
                "title": (
                    "账号响应未确认"
                    if acc.get("responseUnconfirmed")
                    else "账号网络异常"
                ),
                "message": network_reason,
                "source": "account",
                "createdAt": int(network_checked_at or now_ms()),
                "updatedAt": now_ms(),
                "active": True,
            })
    if str(acc.get("proxyStatus") or "") == "error" or str(acc.get("proxyError") or ""):
        proxy_reason = str(acc.get("proxyError") or "当前IP节点检测失败")
        dismissed = database_read_important_notice_record(
            account_key,
            "account:proxy",
        )
        if not (
            dismissed
            and not dismissed.get("active")
            and dismissed.get("source") == "user-dismiss"
            and dismissed.get("message") == proxy_reason
        ):
            notices.append({
                "id": "dynamic-account-proxy",
                "key": "account:proxy",
                "severity": "warning",
                "title": "当前IP节点异常",
                "message": proxy_reason,
                "source": "proxy",
                "createdAt": int(acc.get("proxyCheckedAt") or now_ms()),
                "updatedAt": int(acc.get("proxyCheckedAt") or now_ms()),
                "active": True,
            })
    deduped: dict[str, dict[str, Any]] = {}
    severity_rank = {"critical": 0, "error": 1, "warning": 2, "info": 3}
    for notice in notices:
        notice_key = str(notice.get("key") or notice.get("id") or "")
        notice["message"] = str(notice.get("message") or "")[:800]
        notice["advice"] = (
            "无需手动重启；系统已跳过本轮任务并继续执行其他任务，"
            "5分钟后会自动重新检查体力和活血丹。"
            if notice_key in {"task:dungeon", "task:lossless"}
            and str(notice.get("title") or "") in {
                "副本等待资源", "无损等待资源",
            }
            else (
                "请先清理宝库空位，再手动重试签到；签到成功或服务器确认"
                "本日已签到后，提示会自动消失。"
                if notice_key == "daily:autoSignIn"
                and "宝库空间不足" in notice["message"]
                else important_notice_advice(notice_key)
            )
        )
        notice["summary"] = important_notice_summary(notice)
        existing = deduped.get(notice_key)
        if existing is None or int(notice.get("updatedAt") or 0) >= int(existing.get("updatedAt") or 0):
            deduped[notice_key] = notice
    return sorted(
        deduped.values(),
        key=lambda item: (
            severity_rank.get(str(item.get("severity") or "warning"), 3),
            -int(item.get("updatedAt") or 0),
        ),
    )


def dismiss_important_notice(sess: dict[str, Any], notice_key: str) -> bool:
    key = str(notice_key or "").strip()
    if not key or len(key) > 120:
        raise RuntimeError("提示标识无效")
    notices = current_important_notices(sess)
    notice = next((item for item in notices if str(item.get("key") or "") == key), None)
    if notice is None:
        return False
    database_dismiss_important_notice(
        account_storage_key(sess=sess),
        key,
        message=str(notice.get("message") or ""),
    )
    return True


# --- 军情页“辅助实时行动”（任务引擎侧） -------------------------------------
#
# 0x1600/0x8600 只反映野外军情（攻占/驻守/返回）；副本战斗走 0x1938/0x8938
# 独立信道，正在配兵/发起中的出征也不会出现在军情列表里。这里从任务引擎
# 真实持有的运行时状态汇总“辅助此刻正在做的军事行动”：
#
#   - 刷黄：brushInFlight 在途编队（目标山贼、battleId、出征时刻）
#   - 副本：execute_dungeon 战斗标记 currentDungeonBattle / currentDungeonStage
#   - 打矿：lastTarget + 指挥中心 fighting 状态
#   - 其他常驻任务：schedulerState=fighting/dispatching 与 schedulerMessage
#
# 行动的“状态”一律以心跳回来的将领真实忙闲（征/战/防/返）定名，将领已经
# 全部回闲的在途记录不再展示——宁可少一条也不把已结束的行动冒充“此刻”。
# 该列表纯本地组装，不发任何游戏请求，因此可以随 2 秒任务轮询实时刷新。

ASSISTANT_OPERATION_STATE_ORDER = {"战斗": 0, "出征": 1, "驻守": 2, "返回": 3, "准备": 4}


def _assistant_operation_state_from_generals(states: list[dict[str, Any]]) -> str:
    """Map real general statuses (征/战/防/返) to the operation state label."""
    statuses = {str(item.get("status") or "") for item in states}
    if "战" in statuses:
        return "战斗"
    if "征" in statuses:
        return "出征"
    if "防" in statuses:
        return "驻守"
    if "返" in statuses:
        return "返回"
    return ""


def _assistant_target_display(target: dict[str, Any] | None) -> str:
    """Human-readable target like 6级山贼(92,25); never invents missing fields."""
    data = target if isinstance(target, dict) else {}
    name = str(data.get("name") or "").strip()
    level = data.get("level")
    kind = str(data.get("kind") or "").strip()
    if not name:
        if level:
            name = f"{level}级{kind or '山贼'}"
        else:
            name = kind
    elif level and "级" not in name:
        name = f"{level}级{name}"
    x, y = data.get("x"), data.get("y")
    if name and x is not None and y is not None:
        return f"{name}({x},{y})"
    return name


def _assistant_int_or_none(value: Any) -> int | None:
    try:
        result = int(value)
    except (TypeError, ValueError):
        return None
    return result or None


def _assistant_operation(
    task: dict[str, Any],
    task_key: str,
    task_name: str,
    *,
    state: str,
    text: str,
    general_states: list[dict[str, Any]],
    target_text: str = "",
    battle_id: Any = None,
    cycle_no: Any = None,
    started_at: Any = None,
) -> dict[str, Any]:
    return {
        "source": "task-engine",
        "taskKey": task_key,
        "taskName": task_name,
        "state": state,
        "text": text,
        "generalStates": [
            {"name": str(item.get("name") or ""), "status": str(item.get("status") or "")}
            for item in general_states
        ],
        "targetText": target_text,
        "battleId": _assistant_int_or_none(battle_id),
        "cycleNo": _assistant_int_or_none(cycle_no),
        "startedAt": _assistant_int_or_none(started_at),
        "updatedAt": (
            _assistant_int_or_none(task.get("schedulerUpdatedAt"))
            or _assistant_int_or_none(task.get("updatedAt"))
            or now_ms()
        ),
    }


def _assistant_general_names(states: list[dict[str, Any]], general_ids: list[str]) -> str:
    names = "、".join(
        str(item.get("name") or "") for item in states if str(item.get("name") or "")
    )
    return names or (f"{len(general_ids)}名将领" if general_ids else "")


def assistant_live_operations(sess: dict[str, Any]) -> list[dict[str, Any]]:
    """军情页的“辅助此刻正在进行的军事行动”；只报真实状态，不猜测。"""
    sid = str(sess.get("sessionId") or "")
    if not sid:
        return []
    task_names = dict(RESIDENT_TASKS)
    with TASK_LOCK:
        tasks = [
            task
            for task in AUTO_TASKS.values()
            if str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "") == sid
            and str(task.get("status") or "") in ACTIVE_TASK_STATUSES
        ]
    ops: list[dict[str, Any]] = []
    for task in tasks:
        key = resident_task_key(task)
        task_name = task_names.get(key)
        if not task_name:
            continue
        scheduler_state = str(task.get("schedulerState") or "")
        scheduler_ids = [
            str(item or "").strip()
            for item in task.get("schedulerGeneralIds") or []
            if str(item or "").strip()
        ]
        if key == "brushYellow":
            flights = task.get("brushInFlight")
            # 任务线程会随时 pop 归队编队，这里复制后再遍历，避免并发变更。
            for flight in (list(flights.values()) if isinstance(flights, dict) else []):
                if not isinstance(flight, dict):
                    continue
                general_ids = [
                    str(item or "").strip()
                    for item in flight.get("generalIds") or []
                    if str(item or "").strip()
                ]
                states = cached_general_states(sess, general_ids)
                state = _assistant_operation_state_from_generals(states)
                if not state:
                    # 将领已全部回闲：行动已结束，只剩战后维护，不算军情。
                    continue
                target_text = _assistant_target_display(flight.get("target")) or "山贼"
                names = _assistant_general_names(states, general_ids)
                verb = {
                    "战斗": f"正在与{target_text}战斗",
                    "出征": f"正在出征{target_text}",
                    "驻守": f"正在驻守{target_text}",
                    "返回": f"正在从{target_text}返回",
                }[state]
                ops.append(_assistant_operation(
                    task, key, task_name,
                    state=state,
                    text=f"{names} {verb}",
                    general_states=states,
                    target_text=target_text,
                    battle_id=flight.get("battleId"),
                    cycle_no=flight.get("cycleNo"),
                    started_at=flight.get("dispatchedAt"),
                ))
            if scheduler_state == "dispatching":
                states = cached_general_states(sess, scheduler_ids)
                names = _assistant_general_names(states, scheduler_ids)
                ops.append(_assistant_operation(
                    task, key, task_name,
                    state="准备",
                    text=(f"{names} " if names else "") + "已取得出征权，正在执行刷黄治疗/配兵",
                    general_states=states,
                ))
        elif key == "dungeon":
            battle = task.get("currentDungeonBattle")
            battle = battle if isinstance(battle, dict) else None
            stage_info = task.get("currentDungeonStage")
            stage_info = stage_info if isinstance(stage_info, dict) else None
            info = battle or stage_info or {}
            chapter_name = str(info.get("chapterName") or "").strip()
            stage = info.get("stage")
            stage_text = (
                f"{chapter_name}第{stage}关" if chapter_name and stage is not None else ""
            )
            if scheduler_state == "fighting":
                general_ids = [
                    str(item or "").strip()
                    for item in (battle or {}).get("generalIds") or scheduler_ids
                    if str(item or "").strip()
                ]
                states = cached_general_states(sess, general_ids)
                names = _assistant_general_names(states, general_ids)
                target_text = f"副本{stage_text}" if stage_text else "副本"
                dungeon_state = sess.get("lastDungeonState")
                dungeon_state = dungeon_state if isinstance(dungeon_state, dict) else {}
                battle_id = (battle or {}).get("battleId") or (
                    dungeon_state.get("battleId") if dungeon_state.get("active") else None
                )
                ops.append(_assistant_operation(
                    task, key, task_name,
                    state="战斗",
                    text=f"{names} 正在与{target_text}战斗",
                    general_states=states,
                    target_text=target_text,
                    battle_id=battle_id,
                    cycle_no=task.get("currentCycle") or task.get("cycle"),
                    started_at=(battle or {}).get("startedAt"),
                ))
            elif scheduler_state == "dispatching":
                states = cached_general_states(sess, scheduler_ids)
                names = _assistant_general_names(states, scheduler_ids)
                suffix = f"副本{stage_text}" if stage_text else "副本"
                ops.append(_assistant_operation(
                    task, key, task_name,
                    state="准备",
                    text=(f"{names} " if names else "") + f"正在准备{suffix}出征（治疗/配兵）",
                    general_states=states,
                    target_text=f"副本{stage_text}" if stage_text else "",
                ))
        else:
            if scheduler_state == "fighting":
                states = cached_general_states(sess, scheduler_ids)
                state = _assistant_operation_state_from_generals(states) or "战斗"
                names = _assistant_general_names(states, scheduler_ids)
                target_text = (
                    _assistant_target_display(task.get("lastTarget"))
                    if key == "mine" else ""
                )
                if target_text:
                    verb = {
                        "战斗": f"正在攻打{target_text}",
                        "出征": f"正在出征{target_text}",
                        "驻守": f"正在驻守{target_text}",
                        "返回": f"正在从{target_text}返回",
                    }[state]
                    text = f"{names} {verb}" if names else verb
                else:
                    message = str(task.get("schedulerMessage") or "").strip()
                    text = message or f"{task_name}战斗进行中"
                    if names:
                        text = f"{names}：{text}"
                battle_id = None
                if key == "mine":
                    last_result = task.get("lastResult")
                    if isinstance(last_result, dict) and last_result.get("success"):
                        battle_id = last_result.get("successBattleId")
                ops.append(_assistant_operation(
                    task, key, task_name,
                    state=state,
                    text=text,
                    general_states=states,
                    target_text=target_text,
                    battle_id=battle_id,
                    cycle_no=task.get("cycle"),
                ))
            elif scheduler_state == "dispatching":
                states = cached_general_states(sess, scheduler_ids)
                names = _assistant_general_names(states, scheduler_ids)
                ops.append(_assistant_operation(
                    task, key, task_name,
                    state="准备",
                    text=(f"{names} " if names else "") + f"正在准备{task_name}出征",
                    general_states=states,
                ))
    ops.sort(key=lambda item: (
        ASSISTANT_OPERATION_STATE_ORDER.get(str(item.get("state") or ""), 9),
        -int(item.get("startedAt") or item.get("updatedAt") or 0),
    ))
    return ops


def current_task_overview(sess: dict[str, Any]) -> dict[str, Any]:
    """Return the role task page model without triggering any game action."""
    sid = str(sess.get("sessionId") or "")
    overview_at = now_ms()
    shared_public = shared_account_public_state_snapshot(sess)
    role_state = sess.get("roleState") if isinstance(sess.get("roleState"), dict) else {}
    resource_point_current = max(0, int(role_state.get("resourcePointCurrent") or 0))
    resource_point_cap = max(0, int(role_state.get("resourcePointCap") or 0))
    shared_dungeon_count = shared_resident_daily_count(
        sess,
        "dungeon",
        at_millis=overview_at,
        public_state=shared_public,
    )
    daily_dungeon_count = (
        shared_dungeon_count
        if shared_dungeon_count is not None
        else get_daily_dungeon_count(sess)
    )
    shared_lossless_count = shared_resident_daily_count(
        sess,
        "lossless",
        at_millis=overview_at,
        public_state=shared_public,
    )
    persisted_lossless_status = shared_lossless_last_status(
        sess,
        at_millis=overview_at,
        public_state=shared_public,
    )
    active_by_key: dict[str, dict[str, Any]] = {}
    with TASK_LOCK:
        session_tasks = [
            task
            for task in AUTO_TASKS.values()
            if str(task.get("sessionId") or task.get("config", {}).get("sessionId") or "") == sid
        ]
        tasks = [
            task for task in session_tasks
            if str(task.get("status") or "") in ACTIVE_TASK_STATUSES
        ]
        tasks.sort(key=lambda task: int(task.get("createdAt") or 0), reverse=True)
        for task in tasks:
            overview_key = AUTO_TASK_OVERVIEW_KEYS.get(str(task.get("type") or ""))
            if overview_key and overview_key not in active_by_key:
                active_by_key[overview_key] = task
    resident = []
    latest_lossless_task = next((
        task for task in sorted(
            session_tasks,
            key=lambda item: int(item.get("updatedAt") or item.get("createdAt") or 0),
            reverse=True,
        )
        if AUTO_TASK_OVERVIEW_KEYS.get(str(task.get("type") or "")) == "lossless"
        and isinstance(task.get("lastLosslessStatus"), dict)
    ), None)
    lossless_status_candidates = [
        value
        for value in (
            persisted_lossless_status,
            sess.get("lastLosslessStatus"),
            (latest_lossless_task or {}).get("lastLosslessStatus"),
            (active_by_key.get("lossless") or {}).get("lastLosslessStatus"),
        )
        if isinstance(value, dict) and value
    ]
    overview_lossless_status = max(
        lossless_status_candidates,
        key=lambda value: int(value.get("updatedAt") or 0),
        default={},
    )
    lossless_used_candidates: list[int] = []
    if shared_lossless_count is not None:
        lossless_used_candidates.append(int(shared_lossless_count))
    for source_task in (
        active_by_key.get("lossless"),
        latest_lossless_task,
    ):
        if not isinstance(source_task, dict):
            continue
        direct_used = source_task.get("losslessUsedAttempts")
        if direct_used is not None:
            lossless_used_candidates.append(max(0, int(direct_used)))
    if overview_lossless_status.get("usedAttempts") is not None:
        lossless_used_candidates.append(
            max(0, int(overview_lossless_status["usedAttempts"]))
        )
    elif overview_lossless_status.get("remainingAttempts") is not None:
        lossless_used_candidates.append(max(
            0,
            LOSSLESS_DAILY_LIMIT
            - int(overview_lossless_status["remainingAttempts"]),
        ))
    overview_lossless_used = (
        min(LOSSLESS_DAILY_LIMIT, max(lossless_used_candidates))
        if lossless_used_candidates
        else 0
    )
    overview_lossless_remaining = max(
        0, LOSSLESS_DAILY_LIMIT - overview_lossless_used
    )
    for key, name in RESIDENT_TASKS:
        task = active_by_key.get(key)
        lossless_status = overview_lossless_status if key == "lossless" else {}
        scheduler_state = str((task or {}).get("schedulerState") or "idle")
        scheduler_next_check_at = (task or {}).get("schedulerNextCheckAt")
        if key == "lossless" and lossless_status_phase(lossless_status) == "cooldown":
            scheduler_state = "cooldown"
            updated_at = int(lossless_status.get("updatedAt") or now_ms())
            scheduler_next_check_at = updated_at + int(lossless_status.get("cooldownSec") or 0) * 1000
        resident.append({
            "key": key,
            "name": name,
            "running": bool(task),
            "status": str((task or {}).get("status") or "idle"),
            "schedulerState": scheduler_state,
            "schedulerMessage": str((task or {}).get("schedulerMessage") or ""),
            "schedulerPriority": int((task or {}).get("schedulerPriority") or RESIDENT_TASK_PRIORITIES.get(key, 0)),
            "schedulerRunnable": bool((task or {}).get("schedulerRunnable")),
            "schedulerGeneralIds": list((task or {}).get("schedulerGeneralIds") or []),
            "schedulerNextCheckAt": scheduler_next_check_at,
            "mode": (
                str(((task or {}).get("config") or {}).get("mode") or DUNGEON_MODE_LOOP)
                if key == "dungeon" else None
            ),
            "currentDungeonStage": (
                (task or {}).get("currentDungeonStage")
                if key == "dungeon" else None
            ),
            "taskId": (task or {}).get("taskId"),
            "cycle": int((task or {}).get("cycle") or 0),
            "usedAttempts": overview_lossless_used if key == "lossless" else None,
            "remainingAttempts": overview_lossless_remaining if key == "lossless" else None,
            "resourcePointCurrent": resource_point_current if key == "mine" else None,
            "resourcePointCap": resource_point_cap if key == "mine" else None,
            "dailyDungeonCount": daily_dungeon_count if key == "dungeon" else None,
            "updatedAt": (task or {}).get("updatedAt"),
        })
    task_stack = task_stack_for_session(sid, tasks)
    if shared_lossless_count is not None or overview_lossless_status:
        for item in task_stack:
            if str(item.get("key") or "") == "lossless":
                item["remainingAttempts"] = overview_lossless_remaining
    return {
        "date": time.strftime("%Y%m%d"),
        "updatedAt": overview_at,
        "savedTasksStarted": bool(sess.get("savedTasksStarted")),
        "savedTasksStartedAt": sess.get("savedTasksStartedAt"),
        "taskStack": task_stack,
        "resident": resident,
        "daily": current_daily_task_completions(sess),
        "notices": current_important_notices(sess),
        "commandCenter": command_center_snapshot(sid),
    }


def dashboard_general_status(general: dict[str, Any]) -> tuple[str, str]:
    status = str(
        general.get("displayStatus")
        or general.get("statusText")
        or general_status_text_from_code(general.get("status"))
        or "未知"
    ).strip()
    if status == "闲":
        return "idle", status
    if status in {"征", "战", "修"}:
        return "active", status
    if status == "返":
        return "returning", status
    if status == "防":
        return "defending", status
    return "other", status or "未知"


def dashboard_general_snapshot(generals: list[dict[str, Any]]) -> dict[str, Any]:
    counts = {
        "idle": 0,
        "active": 0,
        "returning": 0,
        "defending": 0,
        "other": 0,
    }
    items = []
    for general in generals:
        group, status = dashboard_general_status(general)
        counts[group] += 1
        items.append({
            "id": general.get("id"),
            "idHex": general.get("idHex"),
            "name": general.get("name") or str(general.get("id") or "未知将领"),
            "status": status,
            "statusGroup": group,
            "level": general.get("level"),
            "energy": general.get("energy"),
            "loyalty": general.get("loyalty"),
            "soldierType": (
                general.get("soldierType")
                or (
                    soldier_type_name(general.get("soldierTypeCode"))
                    if general.get("soldierTypeCode") is not None
                    else ""
                )
            ),
            "soldierCount": general.get(
                "soldierCount",
                general.get("currentSoldierCount"),
            ),
        })
    return {"total": len(items), **counts, "items": items}


DASHBOARD_COUNTRY_SHORT_NAMES = (
    "汉", "魏", "蜀", "吴", "楚", "胡", "赵",
    "秦", "羌", "鲁", "蛮", "燕", "晋", "陈",
)


def dashboard_country_short_name(role: dict[str, Any] | None) -> str:
    role = role if isinstance(role, dict) else {}
    title = str(role.get("title") or "").strip()
    if title in DASHBOARD_COUNTRY_SHORT_NAMES:
        return title
    country = str(role.get("country") or "").strip()
    for short_name in (
        "蜀", "魏", "吴", "楚", "胡", "赵", "秦",
        "羌", "鲁", "蛮", "燕", "晋", "陈", "汉",
    ):
        if short_name in country:
            return short_name
    return ""


def current_dashboard_snapshot() -> dict[str, Any]:
    """Aggregate existing local snapshots without issuing any game request."""
    with ACCOUNT_LOCK:
        account_records = [dict(acc) for acc in ACCOUNTS.values()]
    activity_by_session = recent_game_activity_summaries([
        str(acc.get("sessionId") or "") for acc in account_records
    ])

    accounts = []
    general_totals = {
        "total": 0,
        "idle": 0,
        "active": 0,
        "returning": 0,
        "defending": 0,
        "other": 0,
    }
    status_totals = {"online": 0, "offline": 0, "stopped": 0, "checking": 0}
    active_account_count = 0
    notice_account_count = 0
    notice_total = 0

    for acc in account_records:
        sid = str(acc.get("sessionId") or "")
        live_sess = SESSIONS.get(sid)
        sess = dict(live_sess) if isinstance(live_sess, dict) else {
            "sessionId": sid,
            "username": acc.get("username"),
            "role": acc.get("role") or {},
            "roleState": acc.get("roleState") or {},
            "area": acc.get("area") or {},
            "generals": [],
            "dailyActivity": {},
        }
        summary = public_account_summary(acc)
        overview = current_task_overview(sess)
        daily_stats = current_daily_stats(sess)
        habits = load_account_habits(sess)
        config = habits.get("config") if isinstance(habits.get("config"), dict) else {}
        brush_limit = max(1, int((config or {}).get("dailyLimit") or 500))
        generals = dashboard_general_snapshot(list(sess.get("generals") or []))
        for key in general_totals:
            general_totals[key] += int(generals.get(key) or 0)

        resident = list(overview.get("resident") or [])
        resident_by_key = {
            str(item.get("key") or ""): item
            for item in resident
        }
        task_stack = list(overview.get("taskStack") or [])
        current_task = next(
            (item for item in task_stack if item.get("current")),
            task_stack[0] if task_stack else None,
        )
        if current_task:
            active_account_count += 1
        notices = list(overview.get("notices") or [])
        if notices:
            notice_account_count += 1
            notice_total += len(notices)
        daily_tasks = {
            str(item.get("key") or ""): item
            for item in (overview.get("daily") or [])
        }
        status = str(summary.get("status") or "stopped")
        status_key = status if status in status_totals else "stopped"
        status_totals[status_key] += 1
        role = sess.get("role") if isinstance(sess.get("role"), dict) else {}
        role_state = sess.get("roleState") if isinstance(sess.get("roleState"), dict) else {}
        logs = database_read_account_logs(account_storage_key(sess=sess, acc=acc), 5)
        request_history = list(summary.get("recentGameRequests") or [])[-30:]
        request_successes = sum(
            1 for item in request_history if str(item.get("status") or "") == "success"
        )
        request_failures = sum(
            1 for item in request_history if str(item.get("status") or "") == "failure"
        )
        mine = resident_by_key.get("mine") or {}
        lossless = resident_by_key.get("lossless") or {}
        accounts.append({
            "accountKey": account_storage_key(sess=sess, acc=acc),
            "sessionId": sid,
            "username": summary.get("username"),
            "roleName": summary.get("roleName"),
            "countryShort": dashboard_country_short_name(role),
            "level": summary.get("level"),
            "areaName": summary.get("areaName"),
            "status": status,
            "statusText": summary.get("statusText"),
            "started": bool(summary.get("started")),
            "hasLiveSession": bool(live_sess),
            "live": bool(live_sess) and status == "online",
            "stale": not (bool(live_sess) and status == "online"),
            "lastHeartbeat": summary.get("lastHeartbeat") or {},
            "lastError": summary.get("lastError") or "",
            "reconnectState": summary.get("reconnectState") or "",
            "reconnectRemainingSec": int(summary.get("reconnectRemainingSec") or 0),
            "networkDegraded": bool(summary.get("networkDegraded")),
            "responseUnconfirmed": bool(summary.get("responseUnconfirmed")),
            "proxy": {
                "mode": summary.get("proxyMode"),
                "group": summary.get("proxyGroup"),
                "node": summary.get("proxyNode"),
                "ip": summary.get("proxyIp"),
                "status": summary.get("proxyStatus"),
                "error": summary.get("proxyError"),
                "checkedAt": summary.get("proxyCheckedAt"),
            },
            "currentTask": current_task,
            "taskStack": task_stack,
            "residentTasks": resident,
            "dailyTasks": daily_tasks,
            "notices": notices,
            "generals": generals,
            "dailyProgress": {
                "brushYellow": {
                    "current": int(daily_stats.get("brushYellowCount") or 0),
                    "limit": brush_limit,
                },
                "mine": {
                    "current": int(
                        mine.get("resourcePointCurrent")
                        if mine.get("resourcePointCurrent") is not None
                        else role_state.get("resourcePointCurrent") or 0
                    ),
                    "limit": int(
                        mine.get("resourcePointCap")
                        if mine.get("resourcePointCap") is not None
                        else role_state.get("resourcePointCap") or 0
                    ),
                },
                "lossless": {
                    "current": int(lossless.get("usedAttempts") or 0),
                    "limit": LOSSLESS_DAILY_LIMIT,
                },
                "dungeon": {
                    "current": int(daily_stats.get("dungeonCount") or 0),
                },
            },
            "resources": {
                "copper": role_state.get("copper"),
                "food": role_state.get("food"),
                "prestige": role_state.get("prestige"),
                "populationCurrent": role_state.get("populationCurrent"),
                "populationCap": role_state.get("populationCap"),
                "resourcePointCurrent": role_state.get("resourcePointCurrent"),
                "resourcePointCap": role_state.get("resourcePointCap"),
            },
            "recentLogs": logs,
            "recentGameRequests": request_history,
            "recentActivity": activity_by_session.get(sid) or recent_game_activity_summary(""),
            "requestSummary": {
                "total": len(request_history),
                "success": request_successes,
                "failure": request_failures,
                "successRate": (
                    round(request_successes * 100 / len(request_history), 1)
                    if request_history else None
                ),
            },
            "updatedAt": int(
                (summary.get("lastHeartbeat") or {}).get("checkedAt")
                or summary.get("startedAt")
                or summary.get("createdAt")
                or 0
            ),
        })

    with BANDIT_COORDINATOR_LOCK:
        coordinator = {
            "running": bool(
                BANDIT_COORDINATOR_THREAD
                and BANDIT_COORDINATOR_THREAD.is_alive()
            ),
            "inflightCount": int(
                BANDIT_COORDINATOR_STATE.get("inflightCount") or 0
            ),
            "servers": {
                str(key): {
                    field: json_safe(value.get(field))
                    for field in (
                        "lastDispatchedAt", "lastFinishedAt", "lastAccountId",
                        "lastRouteKey", "lastRequestCount", "lastTargetCount",
                        "lastError", "water", "updatedAt",
                    )
                    if field in value
                }
                for key, value in (
                    BANDIT_COORDINATOR_STATE.get("servers") or {}
                ).items()
            },
        }

    # 保持 ACCOUNTS 的持久化插入顺序。账号状态和提示变化时不再重排，
    # 避免总控列表每次轮询都上下跳动；需要关注的账号由前端独立区域展示。
    return {
        "ok": True,
        "date": time.strftime("%Y%m%d"),
        "updatedAt": now_ms(),
        "source": "local-cache-and-sqlite",
        "gameRequestsIssued": 0,
        "totals": {
            "accounts": len(accounts),
            **status_totals,
            "active": active_account_count,
            "noticeAccounts": notice_account_count,
            "notices": notice_total,
        },
        "generalTotals": general_totals,
        "banditCoordinator": coordinator,
        "mineSettings": {
            "candidateTargetCount": mine_candidate_target_count(),
        },
        "accounts": accounts,
    }


