def start_dungeon_task(
    sess: dict[str, Any],
    rows: list[dict[str, Any]],
    *,
    mode: str = DUNGEON_MODE_LOOP,
) -> dict[str, Any]:
    sid = str(sess.get("sessionId") or "")
    normalized_mode = normalize_dungeon_mode(mode)
    stopped_task_ids = request_stop_tasks_for_session_type(
        sid,
        "dungeon",
        "收到新的副本配置，停止旧副本任务并切换到新配置",
    )
    with TASK_LOCK:
        task_id = uuid4().hex[:12]
        task = {
            "taskId": task_id,
            "type": "dungeon",
            "sessionId": sid,
            "status": "starting",
            "cycle": 0,
            "createdAt": now_ms(),
            "updatedAt": now_ms(),
            "config": {
                "sessionId": sid,
                "rows": [dict(r) for r in rows],
                "mode": normalized_mode,
            },
            "logs": [],
            "stopEvent": threading.Event(),
            "schedulerState": "checking",
            "schedulerRunnable": True,
            "schedulerPriority": RESIDENT_TASK_PRIORITIES["dungeon"],
            "schedulerGeneralIds": list(dict.fromkeys(
                str(general_id)
                for row in rows
                for general_id in row.get("generalIds") or []
            )),
            "schedulerMessage": (
                "等待指挥中心安排打通副本"
                if normalized_mode == DUNGEON_MODE_CLEAR
                else "等待指挥中心安排副本"
            ),
        }
        thread = threading.Thread(target=dungeon_worker, args=(task_id,), daemon=True)
        task["thread"] = thread
        AUTO_TASKS[task_id] = task
        thread.start()
        return {
            "started": True,
            "stoppedOldTaskIds": stopped_task_ids,
            "task": task_public(task),
        }


def ensure_brush_energy(
    task: dict[str, Any],
    sess: dict[str, Any],
    general: dict[str, Any],
) -> bool:
    enabled, threshold = general_energy_policy(sess, task)
    current = general.get("tili")
    if not general.get("energyReliable") or current is None:
        state_machine_stop(task, "无法确认将领体力，不能决定是否使用活血丹")
        return False
    if int(current) < threshold and not enabled:
        state_machine_stop(task, f"将领体力={current}，低于阈值{threshold}；自动使用活血丹未开启")
        return False
    try:
        ensure_general_energy_for_check(
            sess,
            general,
            "刷黄",
            task=task,
        )
    except Exception as exc:
        state_machine_stop(task, str(exc))
        return False
    return True


def ensure_account_copper_floor(
    sess: dict[str, Any],
    *,
    task: dict[str, Any] | None = None,
    context: str = "",
    required_copper: int = 0,
    reserve_food: int = 0,
) -> dict[str, Any]:
    sid = str(sess.get("sessionId") or "")
    cfg = dict(SAVED_CONFIGS.get(sid) or {})
    task_cfg = dict((task or {}).get("config") or {})
    for key in ("foodToCopper", "copperFloorWan"):
        if key in task_cfg:
            cfg[key] = task_cfg[key]
    if not cfg.get("foodToCopper"):
        return {"ok": True, "exchanged": False, "reason": "粮食转铜未开启"}
    floor = max(
        max(0, int(cfg.get("copperFloorWan") or 0)) * 10000,
        max(0, int(required_copper or 0)),
    )
    if floor <= 0:
        return {"ok": True, "exchanged": False, "reason": "未设置铜钱保底"}
    role_state = sess.get("roleState") or {}
    copper = int(role_state.get("copper") or 0)
    food = int(role_state.get("food") or 0)
    if copper >= floor:
        return {"ok": True, "exchanged": False, "copper": copper, "floor": floor}
    deficit = floor - copper
    copper_amount = max(3000, int(math.ceil(deficit / 3000)) * 3000)
    # The original exchange unit is 10,000 food -> 3,000 copper.
    food_amount = copper_amount // 3000 * 10000
    if food < food_amount + max(0, int(reserve_food or 0)):
        message = (
            f"{context + '：' if context else ''}铜钱低于保底，当前{copper}，目标{floor}；"
            f"本次需兑换{copper_amount}铜、消耗粮食{food_amount}，"
            f"并需预留粮食{max(0, int(reserve_food or 0))}，当前粮食只有{food}"
        )
        if task:
            task_log(task, message)
        else:
            account_log(sid, message, source="food-to-copper")
        return {"ok": False, "exchanged": False, "message": message}
    try:
        result = execute_food_to_copper(sess, food_amount, confirm="food-to-copper")
    except Exception as e:
        message = f"{context + '：' if context else ''}粮食转铜失败：{e}"
        if task:
            task_log(task, message)
        else:
            account_log(sid, message, source="food-to-copper")
        return {"ok": False, "exchanged": False, "message": message}
    if not result.get("success"):
        message = f"{context + '：' if context else ''}粮食转铜失败：{result.get('message') or '无提示'}"
        if task:
            task_log(task, message)
        else:
            account_log(sid, message, source="food-to-copper")
        return {"ok": False, "exchanged": False, "message": message}
    message = (
        f"{context + '：' if context else ''}粮食转铜完成：兑换{copper_amount}铜，"
        f"消耗粮食{food_amount}；当前铜钱={result.get('copper')}，粮食={result.get('food')}"
    )
    if task:
        task_log(task, message)
    else:
        account_log(sid, message, source="food-to-copper")
    return {"ok": True, "exchanged": True, "message": message, "copperAmount": copper_amount, **result}


def ensure_brush_copper(task: dict[str, Any], sess: dict[str, Any]) -> bool:
    result = ensure_account_copper_floor(sess, task=task, context="刷黄出征前")
    if not result.get("ok"):
        state_machine_stop(task, result.get("message") or "粮食转铜失败")
        return False
    return True


def perform_recover_and_replenish(
    task: dict[str, Any],
    sess: dict[str, Any],
    formation: dict[str, Any],
    *,
    perform_heal: bool = True,
) -> None:
    gate_reason = account_state_block_reason(str(task.get("config", {}).get("sessionId") or sess.get("sessionId") or ""))
    if gate_reason:
        state_machine_stop(task, gate_reason)
        return
    soldier_type = formation.get("soldierType") or "轻骑兵"
    soldier_count = int(formation.get("soldierCount") or 0)
    if perform_heal and task.get("config", {}).get("healWounded"):
        try:
            heal = execute_heal_wounded(
                sess,
                formation,
                confirm="heal-wounded",
                allow_all_if_count_unknown=bool(task.get("config", {}).get("healAllIfCountUnknown", True)),
            )
            task["lastHealPlan"] = heal.get("plan")
            task["lastHeal"] = {"success": heal.get("success"), "message": heal.get("message"), "reportFile": heal.get("reportFile"), "skipped": heal.get("skipped")}
            if heal.get("success"):
                plan = heal.get("plan") or {}
                general_id = str(formation.get("generalId") or "")
                general = next((
                    item for item in sess.get("generals") or []
                    if str(item.get("id")) == general_id
                    or str(item.get("idHex")) == general_id
                ), {})
                fief_id = plan.get("fiefId")
                fief_name = str(
                    formation.get("fiefName")
                    or general.get("fiefName")
                    or ""
                ).strip()
                fief_label = (
                    f"{fief_name}({fief_id})"
                    if fief_name and fief_id is not None
                    else fief_name or f"封地{fief_id}"
                )
                if plan.get("healAll"):
                    task_log(
                        task,
                        f"治疗伤兵完成：封地={fief_label} 范围=全部伤兵；"
                        f"{heal.get('message') or '成功'}",
                    )
                else:
                    task_log(
                        task,
                        f"治疗伤兵完成：封地={fief_label} "
                        f"兵种={soldier_type_name(plan.get('soldierTypeCode'))} "
                        f"数量={plan.get('woundedCount')}；"
                        f"{heal.get('message') or '成功'}",
                    )
            elif heal.get("skipped"):
                task_log(task, f"治疗伤兵跳过：{heal.get('message')}")
            else:
                state_machine_stop(task, f"治疗伤兵响应未确认成功：{heal.get('message') or '无提示'}")
                return
        except Exception as e:
            msg = str(e)
            mark_account_offline_if_session_invalid(str(sess.get("sessionId") or ""), msg)
            state_machine_stop(task, f"治疗伤兵失败，无法确认恢复状态；{msg}")
            return
    if soldier_count > 0:
        gate_reason = account_state_block_reason(str(task.get("config", {}).get("sessionId") or sess.get("sessionId") or ""))
        if gate_reason:
            state_machine_stop(task, gate_reason)
            return
        general_id = str(formation.get("generalId") or "")
        generals = refresh_generals(sess)
        general = next((
            item for item in generals
            if str(item.get("id")) == general_id or str(item.get("idHex")) == general_id
        ), None)
        general_name = str((general or {}).get("name") or general_id)
        mismatch = formation_match_reason(general, formation)
        if mismatch is None:
            current_code, current_count = _general_current_troops(general or {})
            task_log(
                task,
                f"返回后配兵跳过：将领 {general_name} 当前 {current_count}"
                f"{soldier_type_name(current_code)}，已符合目标 {soldier_count}{soldier_type}",
            )
            return
        try:
            assign = execute_assign_troops(sess, general_id, soldier_type, soldier_count, confirm="assign-troops")
            task["lastAssignTroops"] = {"success": assign.get("success"), "message": assign.get("message"), "reportFile": assign.get("reportFile")}
            if assign.get("success"):
                parsed = assign.get("parsed") or {}
                current = parsed.get("currentSoldierCount")
                task_log(task, f"配兵完成：将领 {general_name} 已设为 {soldier_count} {soldier_type}；当前带兵={current if current is not None else '未知'}")
            else:
                state_machine_stop(
                    task,
                    f"返回后配兵响应未确认成功：将领 {general_name}；"
                    f"目标 {soldier_count} {soldier_type}；响应 {assign.get('message') or '无提示'}",
                )
                return
        except Exception as e:
            msg = str(e)
            mark_account_offline_if_session_invalid(str(sess.get("sessionId") or ""), msg)
            state_machine_stop(task, f"返回后配兵失败：将领 {general_name}；目标 {soldier_count} {soldier_type}；{msg}")
            return


def perform_brush_maintenance(
    task: dict[str, Any],
    sess: dict[str, Any],
    formation: dict[str, Any],
) -> bool:
    return perform_brush_group_maintenance(task, sess, [formation])


def perform_brush_group_maintenance(
    task: dict[str, Any],
    sess: dict[str, Any],
    formations: list[dict[str, Any]],
) -> bool:
    healed_fiefs: set[str] = set()
    for formation in formations:
        general_id = str(formation.get("generalId") or "")
        general = next((
            item for item in sess.get("generals") or []
            if str(item.get("id")) == general_id
            or str(item.get("idHex")) == general_id
        ), {})
        fief_id = str(
            formation.get("fiefId")
            or formation.get("placeID")
            or general.get("fiefId")
            or general.get("placeID")
            or ""
        )
        # 治疗协议是以封地为单位，且伤兵数量未知时发送的是“治疗全部”。
        # 同一刷黄编队的多名将领常驻同一封地，战后只应治疗一次；
        # 补兵仍按每名将领分别执行。
        heal_key = f"fief:{fief_id}" if fief_id else f"general:{general_id}"
        perform_heal = heal_key not in healed_fiefs
        if perform_heal:
            healed_fiefs.add(heal_key)
        perform_recover_and_replenish(
            task,
            sess,
            formation,
            perform_heal=perform_heal,
        )
        if task.get("status") == "error":
            return False
    cfg = task.get("config") or {}
    if cfg.get("cleanMail"):
        try:
            result = execute_delete_all_mail(sess, confirm="delete-all-mail")
        except Exception as e:
            state_machine_stop(task, f"邮件清理失败：{e}")
            return False
        if not result.get("success"):
            state_machine_stop(task, f"邮件清理失败：{result.get('message') or '无提示'}")
            return False
        task["lastMailClean"] = result
        task_log(task, f"邮件清理完成：剩余{result.get('remaining', 0)}封")
    if cfg.get("cleanInventory"):
        try:
            result = clean_inventory_by_policy(sess, cfg)
        except Exception as e:
            state_machine_stop(task, f"宝库清理失败：{e}")
            return False
        task["lastInventoryClean"] = result
        task_log(
            task,
            f"宝库清理完成：丢弃道具{result.get('itemCount', 0)}项、装备{result.get('equipmentCount', 0)}件",
        )
    return True


def perform_pre_dispatch_troops(
    task: dict[str, Any],
    sess: dict[str, Any],
    formation: dict[str, Any],
    current_general: dict[str, Any] | None = None,
    *,
    heal_before_assign: bool = True,
    stop_on_shortage: bool = True,
) -> bool:
    """Ensure the user-selected general is set to the configured troop before the first dispatch.

    The product flow is: user configures "将领A + 200 + 轻骑兵", then saves brush-yellow.
    Formation assignment is independent from the optional batch-refill request.
    """
    soldier_type = formation.get("soldierType") or "轻骑兵"
    soldier_count = int(formation.get("soldierCount") or 0)
    general_id = str(formation.get("generalId") or "")
    if not general_id or soldier_count <= 0:
        return True
    target_code = soldier_type_code(soldier_type)
    if current_general is None:
        current_general = load_general_for_state_machine(task, sess, general_id, "出征前配兵检查")
        if current_general is None:
            return False
    current_matches_rule = False
    if current_general:
        current_code = current_general.get("soldierTypeCode")
        current_count = current_general.get("soldierCount", current_general.get("currentSoldierCount"))
        if current_code is not None and current_count is not None and int(current_code) == target_code and int(current_count) == soldier_count:
            current_matches_rule = True
            task_log(task, f"出征前配兵检查通过：将领 {current_general.get('name') or general_id} 当前 {current_count} {soldier_type_name(current_code)}，与规则完全一致：{soldier_count} {soldier_type}")
        else:
            task_log(task, f"出征前配兵不符合规则：将领 {current_general.get('name') or general_id} 当前 {current_count if current_count is not None else '未知'} {soldier_type_name(current_code) if current_code is not None else '未知兵种'}，需要 {soldier_count} {soldier_type}，开始重新配兵")
            if heal_before_assign and task.get("config", {}).get("healWounded"):
                heal_formation = {
                    **formation,
                    "fiefId": (
                        formation.get("fiefId")
                        or current_general.get("fiefId")
                        or current_general.get("placeID")
                    ),
                }
                try:
                    task_log(task, "出征前已开启治疗：先治疗伤兵，再刷新兵力并配兵")
                    heal = execute_heal_wounded(
                        sess,
                        heal_formation,
                        confirm="heal-wounded",
                        allow_all_if_count_unknown=bool(
                            task.get("config", {}).get("healAllIfCountUnknown", True)
                        ),
                    )
                    task["lastPreDispatchHeal"] = {
                        "success": heal.get("success"),
                        "message": heal.get("message"),
                        "reportFile": heal.get("reportFile"),
                        "skipped": heal.get("skipped"),
                    }
                    if heal.get("success"):
                        task_log(task, f"出征前治疗完成：{heal.get('message') or '成功'}；正在刷新闲兵库存")
                    elif heal.get("skipped"):
                        task_log(task, f"出征前治疗跳过：{heal.get('message')}")
                    else:
                        state_machine_stop(
                            task, f"出征前治疗失败：{heal.get('message') or '服务器未确认成功'}",
                        )
                        return False
                    refreshed = refresh_generals(sess)
                    refreshed_general = next((
                        general for general in refreshed
                        if str(general.get("id")) == general_id
                        or str(general.get("idHex")) == general_id
                    ), None)
                    if refreshed_general:
                        current_general = refreshed_general
                except Exception as exc:
                    msg = str(exc)
                    mark_account_offline_if_session_invalid(str(sess.get("sessionId") or ""), msg)
                    state_machine_stop(task, f"出征前治疗失败：{msg}")
                    return False
    actual_after_assign: int | None = None
    actual_type_after_assign: int | None = None
    assign_ok = False
    if current_matches_rule:
        assign_ok = True
    else:
        try:
            assign = execute_assign_troops(sess, general_id, soldier_type, soldier_count, confirm="assign-troops")
            task["lastPreDispatchAssignTroops"] = {"success": assign.get("success"), "message": assign.get("message"), "reportFile": assign.get("reportFile")}
            assign_ok = bool(assign.get("success"))
            if assign.get("success"):
                parsed = assign.get("parsed") or {}
                actual_type_after_assign = int(parsed.get("assignedSoldierTypeCode")) if parsed.get("assignedSoldierTypeCode") is not None else None
                actual_after_assign = int(parsed.get("assignedSoldierCount")) if parsed.get("assignedSoldierCount") is not None else None
                task_log(task, f"出征前配兵完成：将领 {general_id} → {soldier_count} {soldier_type}；实际={actual_after_assign if actual_after_assign is not None else '未知'}")
            else:
                assign_msg = assign.get("message") or "无提示"
                task_log(task, f"出征前配兵响应未确认成功：将领 {general_id}；目标 {soldier_count} {soldier_type}；响应 {assign_msg}")
                if is_session_invalid_message(assign_msg):
                    mark_account_offline_if_session_invalid(str(sess.get("sessionId") or ""), assign_msg)
                    state_machine_stop(task, f"出征前配兵失败：账号/角色状态不可用；{assign_msg}")
                    return False
        except Exception as e:
            msg = str(e)
            mark_account_offline_if_session_invalid(str(sess.get("sessionId") or ""), msg)
            state_machine_stop(task, f"出征前配兵失败：将领 {general_id}；目标 {soldier_count} {soldier_type}；{msg}")
            return False
    # 用户明确配置“将领A带 200 轻骑兵”时，这就是出征前置条件。
    # 如果 0x1226 配兵失败且 0x1229 只能补到少量/其他兵种，继续 actionType=3 的 0x1522 只会得到
    # 0x8522=ff0000 这类无提示失败，用户看起来像“保存没反应”。这里提前停止并给出原因。
    candidates = []
    if actual_after_assign is not None:
        candidates.append((actual_type_after_assign, actual_after_assign, "配兵"))
    best = max(
        (c for c in candidates if c[0] == target_code),
        key=lambda c: c[1],
        default=None,
    )
    if candidates:
        if best is None or best[1] != soldier_count:
            task["status"] = "error"
            actual_desc = "；".join(f"{src}: {soldier_type_name(typ)}(code={typ}) 数量={cnt}" for typ, cnt, src in candidates)
            task["error"] = (
                f"出征前兵力与配置不一致：需要 {soldier_count} {soldier_type}(code={target_code})，"
                f"实际 {actual_desc}；已停止，避免无效出征"
            )
            task_log(task, task["error"])
            return False
    elif not assign_ok:
        assign_message = str(
            (task.get("lastPreDispatchAssignTroops") or {}).get("message") or ""
        )
        if not stop_on_shortage and is_troop_shortage_message(assign_message):
            return False
        task["status"] = "error"
        task["error"] = f"出征前无法确认已配到 {soldier_count} {soldier_type}，已停止，避免无效出征"
        task_log(task, task["error"])
        return False
    return True


def perform_brush_batch_refill(
    task: dict[str, Any],
    sess: dict[str, Any],
    general_ids: list[str],
) -> bool:
    if not task.get("config", {}).get("replenishTroops"):
        task_log(task, "批量补满未开启：目标已选中，按当前配兵直接出征")
        return True
    try:
        result = execute_refill_troops(
            sess,
            general_ids,
            confirm="batch-refill",
        )
    except Exception as exc:
        msg = str(exc)
        mark_account_offline_if_session_invalid(
            str(sess.get("sessionId") or ""),
            msg,
        )
        state_machine_stop(task, f"目标选中后批量补满失败：{msg}")
        return False
    task["lastTargetBatchRefill"] = {
        "success": result.get("success"),
        "message": result.get("message"),
        "reportFile": result.get("reportFile"),
        "generalIds": list(general_ids),
    }
    if not result.get("success"):
        state_machine_stop(
            task,
            f"目标选中后批量补满响应未确认成功："
            f"{result.get('message') or '服务器未返回说明'}",
        )
        return False
    names = [
        str(general.get("name") or general_id)
        for general_id in general_ids
        for general in [next((
            item for item in sess.get("generals") or []
            if str(item.get("id")) == str(general_id)
            or str(item.get("idHex")) == str(general_id)
        ), {})]
    ]
    task_log(
        task,
        f"目标选中后批量补满完成：编队将领={'、'.join(names)}；"
        f"{result.get('message') or '成功'}",
    )
    return True


def pause_brush_after_search_miss(
    task: dict[str, Any],
    general_ids: list[str],
    cycle_no: int,
    found: dict[str, Any],
    *,
    rule_index: int,
) -> bool:
    request_count = int(found.get("requestCount") or found.get("scanCount") or 0)
    cache_skip_count = int(found.get("cacheSkipCount") or 0)
    if request_count:
        reason = f"本批 {request_count} 次找黄请求均未命中"
    else:
        reason = "近期坐标缓存中没有可用目标"
    command_center_set_state(
        task,
        "waiting_target",
        general_ids=general_ids,
        runnable=False,
        message=f"{reason}，等待准备阶段补充候选",
    )
    task_log(
        task,
        f"第 {cycle_no} 轮：{reason}，缓存跳过 {cache_skip_count} 个近期坐标；"
        f"不设置找黄冷却，当前编队等待候选池更新；"
        f"其他刷黄编队、副本和无损可继续",
    )
    return bool(task["stopEvent"].is_set())


def brush_search_options(
    cfg: dict[str, Any],
    rule: dict[str, Any],
    sess: dict[str, Any],
    *,
    batch_size: int | None = None,
    scan_owner: str = "",
) -> dict[str, Any]:
    opts = dict(cfg.get("brush") or {})
    levels = normalize_brush_levels(rule.get("levels"), rule.get("level"))
    opts.update({
        "levels": levels,
        "level": levels[0] if levels else None,
        "drops": list(rule.get("drops") or []),
        "drop": rule.get("drop") or "",
        "compositionCode": rule.get("compositionCode"),
        "compositionFilter": dict(rule.get("compositionFilter") or {}),
        "sessionId": sess.get("sessionId"),
    })
    if batch_size is not None:
        opts["batchSize"] = int(batch_size)
    if scan_owner:
        opts["scanOwner"] = str(scan_owner)
    if scan_owner.endswith(":brush-preparation"):
        opts["noncritical"] = True
    return opts


def brush_rule_has_prepared_target(
    task: dict[str, Any],
    sess: dict[str, Any],
    rule: dict[str, Any],
) -> bool:
    """Use the local shared pool as an event-driven gate before preparation."""
    if not shared_map_server_key(sess):
        return True
    opts = brush_search_options(task.get("config") or {}, rule, sess)
    return bool(shared_map_available_targets(
        sess,
        "bandit",
        target_kind=str(opts.get("targetKind") or "山贼"),
        level=normalize_brush_levels(opts.get("levels"), opts.get("level")),
        drops=normalize_drop_keywords(opts.get("drop"), opts.get("drops")),
        composition_filter=dict(opts.get("compositionFilter") or {}),
        max_results=1,
        center_x=int(opts.get("startX") or 0),
        center_y=int(opts.get("startY") or 0),
    ))


def brush_map_preparation_worker(
    task: dict[str, Any],
    sess: dict[str, Any],
    brush_rules: list[dict[str, Any]],
) -> None:
    """Continuously keep the shared target pool warm for every brush rule."""
    stop_event = task["stopEvent"]
    scan_states: dict[int, dict[str, Any]] = {}
    cursor = 0
    last_target_signatures: dict[int, str] = {}
    sid = str(sess.get("sessionId") or "")
    if session_role_level(sess) < BRUSH_MIN_ROLE_LEVEL:
        task["mapPreparation"] = {
            "state": "disabled_level",
            "message": "请30级之后再开启刷黄！",
            "updatedAt": now_ms(),
        }
        return
    while not stop_event.is_set():
        if SESSIONS.get(sid) is not sess:
            return
        cloud_policy = legacy_map_prefetch_policy(sid)
        if not cloud_policy["legacyLocalMapPrefetchAllowed"]:
            task["mapPreparation"] = {
                **legacy_map_prefetch_pause_view(
                    cloud_policy,
                    task_name="刷黄地图准备",
                ),
                "task": "brushYellow",
            }
            if stop_event.wait(MAP_PREPARATION_IDLE_PAUSE_SEC):
                return
            continue
        rule_index = cursor % len(brush_rules)
        cursor = (rule_index + 1) % len(brush_rules)
        rule = brush_rules[rule_index]
        try:
            found = search_targets(
                sess,
                brush_search_options(
                    task.get("config") or {},
                    rule,
                    sess,
                    batch_size=MAP_PREPARATION_BATCH_SIZE,
                    scan_owner=f"{sid}:brush-preparation",
                ),
                scan_state=scan_states.setdefault(rule_index, {}),
                stop_event=stop_event,
            )
        except Exception as exc:
            task["mapPreparation"] = {
                "state": "error",
                "message": f"刷黄地图准备失败：{exc}",
                "updatedAt": now_ms(),
            }
            if stop_event.wait(BRUSH_SCAN_MISS_PAUSE_SEC):
                return
            continue
        targets = list(found.get("targets") or [])
        task["mapPreparation"] = {
            "state": "ready" if targets else "scanning",
            "task": "brushYellow",
            "rule": rule_index + 1,
            "candidateCount": len(targets),
            "requestCount": int(found.get("requestCount") or 0),
            "cacheHitCount": int(found.get("cacheHitCount") or 0),
            "nextCursor": int(found.get("nextCursor") or 0),
            "updatedAt": now_ms(),
        }
        if targets:
            first = targets[0]
            signature = (
                f"{first.get('id') or first.get('idHex')}:{len(targets)}"
            )
            if signature != last_target_signatures.get(rule_index):
                last_target_signatures[rule_index] = signature
                if has_bandit_target_waiter(sess):
                    with COMMAND_CENTER_CONDITION:
                        COMMAND_CENTER_CONDITION.notify_all()
                task_log(
                    task,
                    f"准备阶段已备好刷黄候选：编队 {rule_index + 1}，"
                    f"候选 {len(targets)} 个，首选 "
                    f"{first.get('name')}({first.get('x')},{first.get('y')})",
                )
            if stop_event.wait(MAP_PREPARATION_IDLE_PAUSE_SEC):
                return
        elif int(found.get("requestCount") or 0) == 0:
            if stop_event.wait(MAP_PREPARATION_IDLE_PAUSE_SEC):
                return


def process_brush_inflight(
    task: dict[str, Any],
    sess: dict[str, Any],
) -> bool:
    """Advance returned formations and run maintenance without blocking dispatch travel."""
    flights = task.setdefault("brushInFlight", {})
    if not isinstance(flights, dict) or not flights:
        return True
    for flight_key, flight in sorted(
        list(flights.items()),
        key=lambda item: int((item[1] or {}).get("cycleNo") or 0),
    ):
        if not isinstance(flight, dict):
            flights.pop(flight_key, None)
            continue
        current_ms = now_ms()
        if current_ms >= int(flight.get("nextFullStateRefreshAt") or 0):
            flight["nextFullStateRefreshAt"] = (
                current_ms
                + BRUSH_SETTLEMENT_FULL_REFRESH_INTERVAL_SEC * 1000
            )
            try:
                refresh_military_intel(sess)
                refresh_generals(sess)
            except Exception as exc:
                task_log(
                    task,
                    f"第 {flight.get('cycleNo')} 轮归队完整状态复查失败，"
                    f"保留任务稍后重试：{exc}",
                )
        result = observe_brush_settlement(sess, flight)
        status_text = str(result.get("statusText") or "未知")
        if result.get("fresh") and status_text != flight.get("lastLoggedStatus"):
            flight["lastLoggedStatus"] = status_text
            phase = "已确认进入出征状态" if result.get("sawBusy") else "等待新的出征状态"
            task_log(
                task,
                f"第 {flight.get('cycleNo')} 轮编队 {int(flight.get('ruleIndex') or 0) + 1}"
                f"归队跟踪：将领={status_text}；{phase}",
            )
        if not result.get("confirmed"):
            if now_ms() < int(flight.get("deadlineAt") or 0):
                continue
            try:
                refresh_military_intel(sess)
                refresh_generals(sess)
            except Exception as exc:
                task_log(task, f"归队超时强制复核失败：{exc}")
            result = observe_brush_settlement(sess, flight)
            if not result.get("confirmed"):
                flight["deadlineAt"] = (
                    now_ms()
                    + BRUSH_SETTLEMENT_RECHECK_GRACE_SEC * 1000
                )
                task_log(
                    task,
                    f"第 {flight.get('cycleNo')} 轮归队状态暂无法确认："
                    f"将领={result.get('statusText') or status_text}；"
                    f"任务不中止，5分钟后继续强制复核",
                )
                continue

        general_ids = [
            str(value)
            for value in flight.get("generalIds") or []
            if str(value or "").strip()
        ]
        if _command_center_blockers(task, general_ids):
            continue
        if not command_center_acquire(task, general_ids):
            return False
        maintenance_ok = False
        try:
            task_log(
                task,
                f"第 {flight.get('cycleNo')} 轮将领已真实回闲，开始检查伤兵并执行战后维护",
            )
            maintenance_ok = perform_brush_group_maintenance(
                task,
                sess,
                [dict(value) for value in flight.get("formations") or []],
            )
        finally:
            command_center_release(
                task,
                state="checking" if maintenance_ok else "error",
                runnable=False,
                message=(
                    "刷黄战后维护完成"
                    if maintenance_ok
                    else task.get("error") or "刷黄战后维护未完成"
                ),
            )
        if not maintenance_ok:
            task["stopEvent"].set()
            return False
        flights.pop(flight_key, None)
        task["cycle"] = int(task.get("cycle") or 0) + 1
        task["lastSettlement"] = result
        task_log(
            task,
            f"第 {flight.get('cycleNo')} 轮闭环完成：将领真实回闲、"
            f"伤兵治疗/补兵及已启用清理均完成；"
            f"今日刷黄次数={get_daily_brush_count(sess)}/{task.get('config', {}).get('dailyLimit')}",
        )
    return True


def claim_shared_resident_wake_owner(session_id: str, task_id: str) -> bool:
    """Elect exactly one desktop wake owner for an account's shared tick.

    Ownership is a lease released explicitly by the worker's hand-off/finally
    path.  Task status alone cannot revoke it: during a network pause the row
    is marked ``stopped`` before an already-sent pending operation finishes.
    Allowing another stopped worker to steal at that point caused a thundering
    herd of identical recovery ticks and cross-task notices.
    """

    sid = str(session_id or "")
    tid = str(task_id or "")
    if not sid or not tid:
        return False
    with SHARED_RESIDENT_WAKE_OWNER_LOCK:
        current = str(SHARED_RESIDENT_WAKE_OWNERS.get(sid) or "")
        if current == tid:
            return True
        if current:
            return False
        SHARED_RESIDENT_WAKE_OWNERS[sid] = tid
        return True


def release_shared_resident_wake_owner(session_id: str, task_id: str) -> None:
    sid = str(session_id or "")
    tid = str(task_id or "")
    with SHARED_RESIDENT_WAKE_OWNER_LOCK:
        if str(SHARED_RESIDENT_WAKE_OWNERS.get(sid) or "") == tid:
            SHARED_RESIDENT_WAKE_OWNERS.pop(sid, None)


def shared_resident_result_task(
    session_id: str,
    feature: str,
    fallback: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Return only the active row that owns ``feature``.

    ``fallback`` is retained for source/API compatibility with older callers,
    but is intentionally ignored.  A shared tick is account-scoped and can
    finish after its display row has been stopped/replaced.  Falling back to
    the wake-owner row silently changes feature identity and creates false
    task errors/notices (the exact failure seen in the role提示 page).
    """

    key = "brushYellow" if str(feature or "") == "brush" else str(feature or "")
    sid = str(session_id or "")
    with TASK_LOCK:
        candidates = [
            task
            for task in AUTO_TASKS.values()
            if str(
                task.get("sessionId")
                or (task.get("config") or {}).get("sessionId")
                or ""
            ) == sid
            and str(task.get("status") or "") in ACTIVE_TASK_STATUSES
            and resident_task_key(task) == key
            and not bool(
                task.get("stopEvent") is not None
                and task["stopEvent"].is_set()
            )
    ]
    if not candidates:
        return None
    return max(
        candidates,
        key=lambda item: int(item.get("createdAt") or 0),
    )


def sync_shared_resident_feature_notice(
    session_id: str,
    feature: str,
    result: dict[str, Any],
) -> None:
    """Keep retryable warnings active and resolve them on verified recovery."""

    normalized = str(feature or "")
    if normalized == "brushYellow":
        normalized = "brush"
    state = str(result.get("state") or "")
    message = str(result.get("message") or "").strip()
    account_key = account_storage_key(session_id=str(session_id or ""))
    if normalized == "brush":
        main_notice_key = "task:brushYellow"
        if bool(result.get("requiresAttention")) or state in {
            "blocked", "uncertain", "timeout",
        }:
            database_upsert_important_notice(
                account_key,
                main_notice_key,
                severity="error",
                title="刷黄已中止",
                message=message or "刷黄恢复需要处理",
                source="automation",
            )
        elif state in {
            "completed", "dispatched", "fighting", "reconciled",
            "recovered-ready", "retry", "settled", "waiting",
            "waiting-generals", "waiting-return",
        }:
            database_resolve_important_notice(account_key, main_notice_key)
        # 筛选过严不是故障而是给操作者的建议：核心只在建议生效的 tick 返回
        # filter-strict，任何其他刷黄状态（命中目标、用户改了筛选、计数未
        # 越阈值）都意味着建议已失效，提示随之自动消失。
        advice_notice_key = "task:brushYellow:filter-advice"
        if state == "filter-strict" and "【建议】" in message:
            database_upsert_important_notice(
                account_key,
                advice_notice_key,
                severity="info",
                title="刷黄建议",
                message=message,
                source="automation",
            )
        else:
            database_resolve_important_notice(account_key, advice_notice_key)
        error_code = str(result.get("errorCode") or "")
        server_message = str(result.get("serverMessage") or message)
        try:
            source_row_index = max(
                0, int(result.get("sourceRowIndex") or 0)
            )
        except (TypeError, ValueError):
            source_row_index = 0
        notice_key = brush_high_level_troops_notice_key(source_row_index)
        if (
            error_code == "BRUSH_DISPATCH_REJECTED"
            and "每个将领至少需配1000兵力" in server_message
        ):
            display_row_number = source_row_index + 1
            database_upsert_important_notice(
                account_key,
                notice_key,
                severity="warning",
                title=f"刷黄编队{display_row_number}配兵不足",
                message=(
                    f"刷黄编队{display_row_number}未满足每个将领配兵达到1000"
                ),
                source="shared-brush-high-level-troops",
            )
            return
        target = result.get("target")
        target = target if isinstance(target, dict) else {}
        try:
            target_level = int(target.get("level") or 0)
        except (TypeError, ValueError):
            target_level = 0
        selected_levels = result.get("selectedLevels")
        selected_levels = (
            list(selected_levels) if isinstance(selected_levels, list) else []
        )
        selected_levels_are_high = bool(selected_levels) and all(
            str(level) in {"9", "10"} for level in selected_levels
        )
        if (
            state == "dispatched"
            and bool(result.get("success"))
            and (target_level in {9, 10} or selected_levels_are_high)
        ):
            database_resolve_important_notice(account_key, notice_key)
        return
    if normalized not in {"dungeon", "lossless"}:
        return
    notice_key = f"task:{normalized}"
    if state == "waiting-resources":
        label = "副本" if normalized == "dungeon" else "无损"
        database_upsert_important_notice(
            account_key,
            notice_key,
            severity="warning",
            title=f"{label}等待资源",
            message=message or f"{label}资源暂时不足，等待下一轮重新检查",
            source="automation",
        )
        return
    if bool(result.get("requiresAttention")) or state in {
        "blocked", "uncertain", "timeout",
    }:
        return
    healthy_states = {
        "all-clear",
        "chest-opened",
        "completed",
        "configured-daily-limit",
        "cooldown",
        "daily_done",
        "dispatched",
        "fighting",
        "reconciled",
        "recovered-ready",
        "settled",
        "settlement-recovered",
        "waiting-generals",
        "waiting-unlock",
    }
    if state in healthy_states:
        database_resolve_important_notice(account_key, notice_key)


def auto_brush_worker(task_id: str) -> None:
    """One-account wake loop; shared Python owns every resident decision."""

    task = AUTO_TASKS.get(task_id)
    if not task:
        return
    cfg = task.get("config") or {}
    sid = str(cfg.get("sessionId") or task.get("sessionId") or "")
    sess = SESSIONS.get(sid)
    if not sess:
        task["status"] = "error"
        task["error"] = "账号未登录或 session 已失效"
        task_log(task, task["error"])
        return
    owns_wake = False
    owner_start_logged = False
    try:
        # Starting one feature row (for example the always-on inventory
        # helper restored at login) must not claim that the user's complete
        # saved resident plan has started. Only resume_saved_resident_tasks()
        # owns that account-level intent flag.
        sync_shared_resident_automation(sess, started=True)
        task["status"] = "running"
        task_log(
            task,
            "已接入账号共享常驻调度；同一账号只保留一个唤醒线程",
        )
        while True:
            stop_requested = bool(task["stopEvent"].is_set())
            pending = _shared_resident_pending(sid)
            if stop_requested and not pending:
                break
            if not claim_shared_resident_wake_owner(sid, task_id):
                if stop_requested:
                    break
                task["stopEvent"].wait(0.5)
                continue
            owns_wake = True
            if not owner_start_logged:
                owner_start_logged = True
                task_log(
                    task,
                    "当前任务线程已成为该账号唯一共享 tick 唤醒者",
                )
            # If this display task was replaced while other resident tasks are
            # still active, hand ownership over immediately. If it was the
            # final task, keep draining an already-sent pending action first.
            active_keys = _desktop_active_shared_resident_keys(sid)
            if stop_requested and active_keys:
                release_shared_resident_wake_owner(sid, task_id)
                owns_wake = False
                break
            if not stop_requested and not wait_for_task_account_online(
                task, sid, "共享常驻任务"
            ):
                break
            drain_final_pending = bool(
                stop_requested and not active_keys and pending
            )
            try:
                result = execute_shared_resident_automation_tick(
                    sess,
                    # The account scheduler, not one feature row, owns an
                    # in-flight operation. Stopping a single row must not
                    # cancel another feature after its request crossed the
                    # send boundary.
                    task=None,
                    configured_execution_allowed=not stop_requested,
                    allowed_features=(
                        None
                        if drain_final_pending
                        else desktop_shared_allowed_features(active_keys)
                    ),
                )
            except Exception as error:
                # A shared operation has no feature-safe task owner at this
                # layer.  In particular, noncritical read failures are
                # intentionally raised by the transport with “任务保持运行”;
                # do not convert that exception into an error on whichever
                # display row happened to own the wake thread.
                error_message = str(error) or error.__class__.__name__
                if is_session_invalid_message(error_message):
                    mark_account_offline_if_session_invalid(
                        sid,
                        error_message,
                    )
                    break
                if is_network_failure_message(error_message):
                    # If a mutation ledger exists, fail closed and pause the
                    # account until heartbeat recovery.  A read-only failure
                    # without pending mutation may retry in place.
                    if (
                        _shared_resident_pending(sid)
                        and not task["stopEvent"].is_set()
                    ):
                        pause_tasks_for_transient_network_failure(
                            sid,
                            error_message,
                        )
                    else:
                        mark_account_network_degraded_without_pause(
                            sid,
                            error_message,
                        )
                    if not task["stopEvent"].is_set():
                        # Let the heartbeat (normally 20s) confirm recovery
                        # before issuing another read-only scan; this avoids a
                        # dead proxy turning into a tight request loop.
                        task["stopEvent"].wait(
                            max(5.0, CLIENT_HEARTBEAT_INTERVAL_SEC)
                        )
                        continue
                    # A critical request already stopped this account's
                    # workers.  Leave the pending ledger untouched and let
                    # the heartbeat/reconnect owner resume it safely.
                    break
                raise
            feature = str(result.get("feature") or "")
            state = str(result.get("state") or "idle")
            message = str(result.get("message") or "共享常驻 tick 已完成")
            task_scoped_result = feature not in {"", "daily"}
            result_task = (
                shared_resident_result_task(sid, feature, task)
                if task_scoped_result
                else task
            )
            if result_task is not None:
                result_task["lastSharedResidentResult"] = dict(result)
                result_task["updatedAt"] = now_ms()
            elif task_scoped_result:
                account_log(
                    sid,
                    f"共享常驻结果未找到对应活动任务，已按账号记录且未写入唤醒线程："
                    f"feature={feature} state={state}；{message}",
                    level=(
                        "warning"
                        if result.get("requiresAttention")
                        or state in {"blocked", "uncertain", "timeout"}
                        else "info"
                    ),
                    source="automation",
                    detail={
                        "feature": feature,
                        "state": state,
                        "wakeOwnerTaskId": task.get("taskId"),
                        "requiresAttention": bool(
                            result.get("requiresAttention")
                        ),
                        "errorCode": result.get("errorCode"),
                        "nextWakeAtMillis": result.get(
                            "nextWakeAtMillis"
                        ),
                    },
                )
            if feature in {
                "ministry", "general", "domestic", "inventory", "captives",
            } and state == "completed":
                if result_task is not None:
                    result_task["cycle"] = (
                        int(result_task.get("cycle") or 0) + 1
                    )
                record_success_action(
                    sid,
                    {
                        "ministry": "六部",
                        "general": "将领维护",
                        "domestic": "自动内政",
                        "inventory": "背包整理",
                        "captives": "俘虏营",
                    }[feature],
                    message,
                    detail={
                        "feature": feature,
                        "state": state,
                        "action": result.get("action") or {},
                        "consumedCount": result.get("consumedCount"),
                    },
                )
            elif result.get("dispatchAccepted"):
                if result_task is not None:
                    result_task["cycle"] = (
                        int(result_task.get("cycle") or 0) + 1
                    )
                category = {
                    "mine": "打矿",
                    "brush": "刷黄",
                    "brushYellow": "刷黄",
                    "raid": "掠夺",
                    "lossless": "无损",
                    "dungeon": "副本",
                }.get(feature, "常驻任务")
                target = result.get("target")
                target = target if isinstance(target, dict) else {}
                stage = result.get("stage")
                stage = stage if isinstance(stage, dict) else {}
                destination = (
                    target.get("name")
                    or target.get("mineType")
                    or target.get("type")
                    or stage.get("chapterName")
                    or stage.get("stageName")
                    or result.get("playerName")
                    or "目标"
                )
                shared_record = result.get("successRecord")
                shared_record = (
                    shared_record if isinstance(shared_record, dict) else {}
                )
                record_detail = {
                    "battleId": result.get("battleId"),
                    "feature": feature,
                    "target": target,
                    "stage": stage,
                }
                if feature in {"brush", "brushYellow", "lossless"} \
                        and shared_record.get("message"):
                    category = str(shared_record.get("category") or category)
                    record_message = str(shared_record["message"])
                    shared_detail = shared_record.get("detail")
                    if isinstance(shared_detail, dict):
                        record_detail.update(shared_detail)
                    if shared_record.get("dedupeKey"):
                        record_detail["dedupeKey"] = str(
                            shared_record["dedupeKey"]
                        )
                elif feature in {"brush", "brushYellow"}:
                    if target.get("x") is not None and target.get("y") is not None:
                        destination += f"({target['x']}，{target['y']})"
                    try:
                        formation_number = max(
                            0, int(result.get("sourceRowIndex"))
                        ) + 1
                    except (TypeError, ValueError):
                        try:
                            formation_number = max(
                                1, int(result.get("formationNumber"))
                            )
                        except (TypeError, ValueError):
                            formation_number = None
                    action = (
                        f"编队{formation_number}"
                        if formation_number is not None else "出征"
                    )
                    battle_id = result.get("battleId")
                    suffix = f"（battleId={battle_id}）" if battle_id else ""
                    record_message = f"{action} > {destination}{suffix}"
                elif feature == "lossless":
                    try:
                        lossless_level = max(1, int(stage.get("level")))
                    except (TypeError, ValueError):
                        match = re.search(
                            r"(\d+)\s*级", str(stage.get("levelName") or "")
                        )
                        lossless_level = int(match.group(1)) if match else None
                    stage_name = str(stage.get("stageName") or "").strip()
                    record_message = (
                        f"{lossless_level}级-{stage_name}"
                        if lossless_level is not None and stage_name
                        else destination
                    )
                else:
                    record_message = f"共享核心出征 > {destination}"
                record_success_action(
                    sid,
                    category,
                    record_message,
                    detail=record_detail,
                )
            scheduler_state = {
                "dispatched": "fighting",
                "waiting": "waiting_generals",
                "waiting-generals": "waiting_generals",
                "waiting-return": "waiting_generals",
                "fighting": "fighting",
                "completed": "checking",
                "settled": "checking",
                "chest-opened": "checking",
                "settlement-recovered": "checking",
                "cooldown": "cooldown",
                "configured-daily-limit": "daily_done",
                "daily_done": "daily_done",
                "all-clear": "daily_done",
                "no-targets": "checking",
                "retry": "checking",
                "idle": "checking",
            }.get(state, "checking")
            if task_scoped_result and result_task is not None:
                command_center_set_state(
                    result_task,
                    scheduler_state,
                    runnable=False,
                    message=message,
                )
                task_log(
                    result_task,
                    f"共享常驻：feature={feature} state={state}；{message}",
                )
            if task_scoped_result:
                sync_shared_resident_feature_notice(sid, feature, result)
            persist_runtime_state()
            if result.get("requiresAttention") or state in {
                "blocked", "uncertain", "timeout"
            }:
                if not task_scoped_result:
                    account_log(
                        sid,
                        f"共享每日任务已暂停：{message}",
                        level="warning",
                        source="automation",
                    )
                    next_wake = result.get("nextWakeAtMillis")
                    try:
                        wait_seconds = max(
                            0.5,
                            min(
                                60.0,
                                (int(next_wake) - now_ms()) / 1000.0,
                            ),
                        )
                    except (TypeError, ValueError):
                        wait_seconds = 5.0
                    task["stopEvent"].wait(wait_seconds)
                    continue
                if result_task is None:
                    # The core may finish a pending workflow after its
                    # display row was stopped.  Keep the durable pending
                    # record and stop this wake owner when no resident row is
                    # left; never manufacture an error on the owner/fallback.
                    if not _desktop_active_shared_resident_keys(sid):
                        break
                    next_wake = result.get("nextWakeAtMillis")
                    try:
                        wait_seconds = max(
                            0.5,
                            min(
                                60.0,
                                (int(next_wake) - now_ms()) / 1000.0,
                            ),
                        )
                    except (TypeError, ValueError):
                        wait_seconds = 5.0
                    task["stopEvent"].wait(wait_seconds)
                    continue
                result_task["status"] = "error"
                result_task["error"] = message
                result_task["updatedAt"] = now_ms()
                result_stop = result_task.get("stopEvent")
                if result_stop is not None:
                    result_stop.set()
                command_center_set_state(
                    result_task,
                    "error",
                    runnable=False,
                    message=message,
                )
                task_log(result_task, "共享常驻任务已暂停：" + message)
                try_sync_shared_resident_automation(sess)
                if result_task is task:
                    break
            next_wake = result.get("nextWakeAtMillis")
            try:
                wait_seconds = max(
                    0.5,
                    min(60.0, (int(next_wake) - now_ms()) / 1000.0),
                )
            except (TypeError, ValueError):
                wait_seconds = 5.0
            task["stopEvent"].wait(wait_seconds)
        if str(task.get("status") or "") != "error":
            task["status"] = "stopped"
            command_center_set_state(
                task,
                "stopped",
                runnable=False,
                message="共享常驻唤醒线程已停止",
            )
            if task.get("_transientNetworkPause"):
                task["_suppressImportantNotice"] = True
            try:
                task_log(task, "共享常驻唤醒线程已停止")
            finally:
                if not task.get("_operatorMaintenancePause"):
                    task.pop("_suppressImportantNotice", None)
        try_sync_shared_resident_automation(sess)
        persist_runtime_state()
    except Exception as error:
        message = str(error)
        # Exceptions outside the shared tick (for example the account-online
        # gate) still do not identify a feature.  Session/network failures are
        # lifecycle events and must not become a terminal notice on the wake
        # owner's display row.
        if is_session_invalid_message(message):
            mark_account_offline_if_session_invalid(sid, message)
            task["status"] = "stopped"
            task.pop("error", None)
            task["updatedAt"] = now_ms()
            command_center_set_state(
                task,
                "stopped",
                runnable=False,
                message="账号会话失效，等待重新登录",
            )
            task["_suppressImportantNotice"] = True
            try:
                task_log(task, "账号会话失效，唤醒线程已停止并等待重新登录")
            finally:
                task.pop("_suppressImportantNotice", None)
            try_sync_shared_resident_automation(sess)
            try:
                persist_runtime_state()
            except Exception:
                pass
            return
        if is_network_failure_message(message):
            if _shared_resident_pending(sid) and not task["stopEvent"].is_set():
                pause_tasks_for_transient_network_failure(sid, message)
            else:
                mark_account_network_degraded_without_pause(sid, message)
            if task["stopEvent"].is_set():
                task["status"] = "stopped"
                task.pop("error", None)
                task["updatedAt"] = now_ms()
                command_center_set_state(
                    task,
                    "stopped",
                    runnable=False,
                    message="网络暂时不可用，等待心跳恢复",
                )
                task["_suppressImportantNotice"] = True
                try:
                    task_log(task, "网络暂时不可用，唤醒线程已停止并等待心跳恢复")
                finally:
                    task.pop("_suppressImportantNotice", None)
            else:
                task["stopEvent"].wait(
                    max(5.0, CLIENT_HEARTBEAT_INTERVAL_SEC)
                )
            try_sync_shared_resident_automation(sess)
            try:
                persist_runtime_state()
            except Exception:
                pass
            return
        task["status"] = "error"
        task["error"] = message
        task["updatedAt"] = now_ms()
        command_center_set_state(
            task, "error", runnable=False, message=message
        )
        task_log(task, "共享常驻任务失败：" + message)
        try_sync_shared_resident_automation(sess)
        try:
            persist_runtime_state()
        except Exception:
            pass
    finally:
        if owns_wake:
            release_shared_resident_wake_owner(sid, task_id)


def start_auto_brush(config: dict[str, Any]) -> dict[str, Any]:
    sess = SESSIONS.get(str(config.get("sessionId") or ""))
    require_brush_level(sess)
    # 同一 session 只保留一个活跃刷黄任务，避免重复出征。
    configured_general_ids = list(dict.fromkeys(
        str(general_id)
        for rule in config.get("brush", {}).get("rules") or []
        for general_id in rule.get("generalIds") or []
        if str(general_id or "").strip()
    ))
    if not configured_general_ids:
        legacy_general_id = str(config.get("brush", {}).get("generalId") or "")
        configured_general_ids = [legacy_general_id] if legacy_general_id else []
    with TASK_LOCK:
        for old in AUTO_TASKS.values():
            if (
                old.get("config", {}).get("sessionId") == config.get("sessionId")
                and str(old.get("type") or "") in {"auto-brush-yellow", "brush-yellow"}
                and old.get("status") in {"starting", "running", "stopping"}
            ):
                old["stopEvent"].set()
                old["status"] = "stopping"
                task_log(old, "收到新的刷黄设置，停止旧刷黄任务；其他常驻任务继续由指挥中心管理")
        task_id = uuid4().hex[:12]
        task = {
            "taskId": task_id,
            "type": "auto-brush-yellow",
            "sessionId": config["sessionId"],
            "status": "starting",
            "cycle": 0,
            "createdAt": now_ms(),
            "updatedAt": now_ms(),
            "config": config,
            "logs": [],
            "stopEvent": threading.Event(),
            "schedulerState": "checking",
            "schedulerRunnable": True,
            "schedulerPriority": RESIDENT_TASK_PRIORITIES["brushYellow"],
            "schedulerGeneralIds": configured_general_ids,
            "schedulerMessage": "等待指挥中心安排刷黄",
            "scanCursor": 0,
            "scanCacheEntries": 0,
        }
        thread = threading.Thread(target=auto_brush_worker, args=(task_id,), daemon=True)
        task["thread"] = thread
        AUTO_TASKS[task_id] = task
        thread.start()
        return task_public(task)


def normalize_mine_settings(
    sess: dict[str, Any],
    body: dict[str, Any],
) -> dict[str, Any]:
    settings = body.get("settings") if isinstance(body.get("settings"), dict) else body
    write_plan = shared_settings_write_plan(
        "/api/mine/save",
        {
            "settings": dict(settings or {}),
            "knownGenerals": list(sess.get("generals") or []),
        },
    )
    response_fields = write_plan.get("response") or {}
    persisted = dict(response_fields.get("settings") or {})
    execution_rows = list(response_fields.get("executionRows") or [])
    return {
        **persisted,
        "rows": execution_rows,
        "uiRows": list(persisted.get("rows") or []),
    }


MINISTRY_CROP_OPTIONS = SHARED_MINISTRY_CROP_OPTIONS


def normalize_ministry_settings(body: dict[str, Any]) -> dict[str, Any]:
    return shared_normalize_ministry_settings(body)


def mine_target_owner_matches(target: dict[str, Any], player_name: str) -> bool:
    expected = str(player_name or "").strip()
    if not expected:
        return not bool(target.get("playerOccupied"))
    actual = str(target.get("ownerName") or "").strip()
    return bool(target.get("playerOccupied")) and actual == expected


def retryable_mine_preflight_error(message: Any) -> bool:
    text = str(message or "")
    return (
        text.startswith("打矿满忠失败：")
        or is_troop_shortage_message(text)
        or (
            text.startswith("打矿出征前检查未通过：")
            and "将领当前不是空闲状态" in text
        )
    )


def mine_capacity_full_error(message: Any) -> bool:
    return str(message or "").startswith("资源点数量已满(")


def mine_search_options(
    cfg: dict[str, Any],
    row: dict[str, Any],
    session_id: str,
    *,
    batch_size: int | None = None,
    scan_owner: str = "",
) -> dict[str, Any]:
    opts = {
        "resourceType": row.get("resourceType"),
        "level": row.get("level"),
        "x": row.get("x") if row.get("scope") == "定点" else cfg.get("centerX"),
        "y": row.get("y") if row.get("scope") == "定点" else cfg.get("centerY"),
        "scope": row.get("scope"),
        "onlyEmpty": row.get("onlyEmpty"),
        "onlyDefended": row.get("onlyDefended"),
        "scanLimit": (
            (186 + 1) * (66 + 1)
            if row.get("scope") == "全国"
            else 80
        ),
        "scanOwner": scan_owner or session_id,
    }
    if batch_size is not None:
        opts["batchSize"] = int(batch_size)
    if scan_owner.endswith(":mine-preparation"):
        opts["noncritical"] = True
    return opts


def mine_row_has_prepared_target(
    sess: dict[str, Any],
    row: dict[str, Any],
) -> bool:
    scope = str(row.get("scope") or "附近")
    return bool(shared_map_available_mine_targets(
        sess,
        resource_types=[str(row.get("resourceType") or "")],
        levels=(
            [int(row.get("level"))]
            if str(row.get("level") or "").strip()
            else []
        ),
        only_empty=bool(row.get("onlyEmpty")),
        only_defended=bool(row.get("onlyDefended")),
        exact_x=int(row.get("x") or 0) if scope == "定点" else None,
        exact_y=int(row.get("y") or 0) if scope == "定点" else None,
    ))


def mine_has_dispatchable_row(
    task: dict[str, Any],
    sess: dict[str, Any],
    rows: list[dict[str, Any]],
) -> bool:
    for row in rows:
        general_ids = [
            str(value)
            for value in row.get("generalIds") or []
            if str(value or "").strip()
        ]
        if not general_ids:
            continue
        states = cached_general_states(sess, general_ids)
        if (
            len(states) != len(general_ids)
            or not all(
                state.get("found") and state.get("status") == "闲"
                for state in states
            )
            or _command_center_blockers(task, general_ids)
        ):
            continue
        if mine_row_has_prepared_target(sess, row):
            return True
    return False


def mine_map_preparation_worker(
    task: dict[str, Any],
    sess: dict[str, Any],
    rows: list[dict[str, Any]],
) -> None:
    """Scan resource maps while every configured mining formation is busy."""
    stop_event = task["stopEvent"]
    scan_states: dict[int, dict[str, Any]] = {}
    cursor = 0
    last_target_signature = ""
    sid = str(sess.get("sessionId") or "")
    while not stop_event.is_set():
        if SESSIONS.get(sid) is not sess:
            return
        cloud_policy = legacy_map_prefetch_policy(sid)
        if not cloud_policy["legacyLocalMapPrefetchAllowed"]:
            task["mapPreparation"] = {
                **legacy_map_prefetch_pause_view(
                    cloud_policy,
                    task_name="打矿地图准备",
                ),
                "task": "mine",
            }
            if stop_event.wait(MAP_PREPARATION_IDLE_PAUSE_SEC):
                return
            continue
        role_state = sess.get("roleState") or {}
        current = int(role_state.get("resourcePointCurrent") or 0)
        cap = int(role_state.get("resourcePointCap") or 0)
        if cap > 0 and current >= cap:
            task["mapPreparation"] = {
                "state": "capacity_done",
                "task": "mine",
                "message": f"资源点额度已满 {current}/{cap}",
                "updatedAt": now_ms(),
            }
            stop_event.wait(BRUSH_SCAN_MISS_PAUSE_SEC)
            continue
        if mine_has_dispatchable_row(task, sess, rows):
            task["mapPreparation"] = {
                "state": "yielding",
                "task": "mine",
                "message": "存在可立即执行的打矿编队，准备阶段已让行",
                "updatedAt": now_ms(),
            }
            stop_event.wait(MAP_PREPARATION_IDLE_PAUSE_SEC)
            continue
        row_index = cursor % len(rows)
        cursor = (row_index + 1) % len(rows)
        row = rows[row_index]
        try:
            found = search_mine_targets(
                sess,
                mine_search_options(
                    task.get("config") or {},
                    row,
                    sid,
                    batch_size=MAP_PREPARATION_BATCH_SIZE,
                    scan_owner=f"{sid}:mine-preparation",
                ),
                scan_state=scan_states.setdefault(row_index, {}),
                stop_event=stop_event,
            )
        except Exception as exc:
            task["mapPreparation"] = {
                "state": "error",
                "task": "mine",
                "message": f"资源点地图准备失败：{exc}",
                "updatedAt": now_ms(),
            }
            if stop_event.wait(BRUSH_SCAN_MISS_PAUSE_SEC):
                return
            continue
        targets = list(found.get("targets") or [])
        task["mapPreparation"] = {
            "state": "ready" if targets else "scanning",
            "task": "mine",
            "row": row_index + 1,
            "candidateCount": len(targets),
            "requestCount": int(found.get("requestCount") or 0),
            "cacheHitCount": int(found.get("cacheHitCount") or 0),
            "nextCursor": int(found.get("nextCursor") or 0),
            "updatedAt": now_ms(),
        }
        if targets:
            first = targets[0]
            signature = (
                f"{row_index}:{first.get('id') or first.get('idHex')}:"
                f"{len(targets)}"
            )
            if signature != last_target_signature:
                last_target_signature = signature
                task_log(
                    task,
                    f"准备阶段已备好打矿候选：编队 {row_index + 1}，"
                    f"候选 {len(targets)} 个，首选 "
                    f"{first.get('name')}({first.get('x')},{first.get('y')})",
                )
            if stop_event.wait(MAP_PREPARATION_IDLE_PAUSE_SEC):
                return
        elif int(found.get("requestCount") or 0) == 0:
            if stop_event.wait(MAP_PREPARATION_IDLE_PAUSE_SEC):
                return


