def start_auto_mine(
    sess: dict[str, Any],
    settings: dict[str, Any],
) -> dict[str, Any]:
    sid = str(sess.get("sessionId") or "")
    rows = list(settings.get("rows") or [])
    if not rows:
        return {
            "started": False,
            "disabled": True,
            "reason": "未启用任何打矿编队",
        }
    request_stop_tasks_for_session_type(
        sid,
        "auto-mine",
        "收到新的打矿设置，停止旧打矿任务",
    )
    task_id = uuid4().hex[:12]
    general_ids = list(dict.fromkeys(
        str(general_id)
        for row in rows
        for general_id in row.get("generalIds") or []
        if str(general_id or "").strip()
    ))
    config = {**settings, "sessionId": sid}
    task = {
        "taskId": task_id,
        "type": "auto-mine",
        "sessionId": sid,
        "status": "starting",
        "cycle": 0,
        "createdAt": now_ms(),
        "updatedAt": now_ms(),
        "config": config,
        "logs": [],
        "stopEvent": threading.Event(),
        "schedulerState": "checking",
        "schedulerRunnable": True,
        "schedulerPriority": RESIDENT_TASK_PRIORITIES["mine"],
        "schedulerGeneralIds": general_ids,
        "schedulerMessage": "等待执行打矿任务",
    }
    thread = threading.Thread(
        target=auto_mine_worker,
        args=(task_id,),
        daemon=True,
    )
    task["thread"] = thread
    with TASK_LOCK:
        AUTO_TASKS[task_id] = task
    thread.start()
    return {"started": True, "task": task_public(task)}


